export const maximoChatbotPages = {
  "chatbot-overview": {
    "id": "chatbot-overview",
    "title": "4.1: Maximo Chatbot REST Integration Overview",
    "subtitle": "Architecture evolution of the Natural Language Processing (NLP) chatbot up to Version 10.",
    "html": "<h1>4.1: Maximo Chatbot REST Integration Overview</h1>\n            <p class=\"page-subtitle\">Architecture evolution of the Natural Language Processing (NLP) chatbot up to Version 10.</p>\n            \n            <section>\n              <h2>Evolutionary Roadmap (v1 to v10)</h2>\n              <p>The chatbot has transitioned from a basic rule-based regex script to a fully decoupled ML classifier pipeline and parallel LLM parsing. Below is the progress of each version:</p>\n              \n              <table class=\"ibm-data-table\">\n                <thead>\n                  <tr>\n                    <th>Version</th>\n                    <th>Port</th>\n                    <th>Core Architecture &amp; Key Features</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr>\n                    <td><code>v1 - v3</code></td>\n                    <td><code>5001</code></td>\n                    <td>Rule-based pattern matching (regex) on port 5001, executing Maximo GET/POST calls via base64 encoded admin credentials. Local trace logging.</td>\n                  </tr>\n                  <tr>\n                    <td><code>v4</code></td>\n                    <td><code>5001</code></td>\n                    <td>Modular backend refactor separating API modules. Implemented cookie-based user session login (no admin credentials hardcoded) and dynamic gear-icon configuration of the Maximo base URL.</td>\n                  </tr>\n                  <tr>\n                    <td><code>v5</code></td>\n                    <td><code>5001</code></td>\n                    <td>Switched from rigid regex matching to modular NLP classification (lowercasing, punctuation stripping, synonyms vocabulary, Jaccard similarity template mapping).</td>\n                  </tr>\n                  <tr>\n                    <td><code>v6</code></td>\n                    <td><code>5001</code></td>\n                    <td>NLU pipeline decoupling: TF-IDF Cosine Similarity, suffix-stripping stemming, stop words noise filtering. Added Asset query/update integrations.</td>\n                  </tr>\n                  <tr>\n                    <td><code>v7</code></td>\n                    <td><code>5005</code></td>\n                    <td>Dynamic CSV parsing and bulk record uploads for Work Orders, Service Requests, and Assets on port 5005.</td>\n                  </tr>\n                  <tr>\n                    <td><code>v8</code></td>\n                    <td><code>5006</code></td>\n                    <td>Machine Learning Intent Pipeline using Scikit-Learn (<code>TfidfVectorizer</code> + <code>LogisticRegression</code>) trained once and cached to disk as a serialized pickle file (port 5006).</td>\n                  </tr>\n                  <tr>\n                    <td><code>v9 - v10</code></td>\n                    <td><code>5001</code></td>\n                    <td>Enterprise scikit-learn classifier pipeline with parallel LLM-based parsing (UltraAssist bot, port 5002) using customizable API keys. Added off-topic guards and user creation/security group administration.</td>\n                  </tr>\n                </tbody>\n              </table>\n\n              <h3>Current Architecture: Version 10</h3>\n              <p>The chatbot is fully modularized. When a query is made, it runs through the decoupled <code>nlp_engine.py</code> which preprocesses inputs, checks spelling distances using Levenshtein calculations, expands synonyms, stems tokens, and applies a scikit-learn Logistic Regression classification pipeline. Once an intent (such as <code>SEARCH_WORK_ORDER</code>, <code>UPDATE_RECORD</code>, or <code>ADD_SECURITYGROUP_TO_USER</code>) is identified, it is routed to dedicated API files inside the <code>apis/</code> directory to execute secure REST integrations with Maximo.</p>\n            </section>",
    "title_hi": "4.1: Maximo NLP Chatbot REST Integration Overview",
    "subtitle_hi": "Version 1 se Version 10 tak Natural Language Processing (NLP) chatbot ka complete architecture evolution.",
    "html_hi": "<h1>4.1: Maximo NLP Chatbot REST Integration Overview</h1>\n<p class=\"page-subtitle\">Version 1 se Version 10 tak Natural Language Processing (NLP) chatbot ka complete architecture evolution.</p>\n<section>\n  <h2>Evolutionary Roadmap (v1 to v10)</h2>\n  <p>Yeh chatbot ek simple regex-based rule matching script se shuru hokar ek decoupled Machine Learning classification pipeline aur parallel LLM natural language engine me develop hua hai:</p>\n  \n  <table class=\"ibm-data-table\">\n    <thead>\n      <tr>\n        <th>Version</th>\n        <th>Port</th>\n        <th>Core Architecture &amp; Key Features</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td><code>v1 - v3</code></td>\n        <td><code>5001</code></td>\n        <td>Port 5001 par rule-based regex pattern matching. Hardcoded base64 credentials ke through Maximo GET/POST API calls aur local trace logging.</td>\n      </tr>\n      <tr>\n        <td><code>v4</code></td>\n        <td><code>5001</code></td>\n        <td>Modular backend refactor. Cookie-based user session authentication (no hardcoded passwords) aur dynamic gear-icon URL switcher.</td>\n      </tr>\n      <tr>\n        <td><code>v5</code></td>\n        <td><code>5001</code></td>\n        <td>Regex se hatkar modular NLP classification (lowercasing, punctuation cleanup, synonym expansion, Jaccard similarity template matching).</td>\n      </tr>\n      <tr>\n        <td><code>v6</code></td>\n        <td><code>5001</code></td>\n        <td>Decoupled NLU pipeline: TF-IDF Cosine Similarity, suffix-stripping stemming, stop words filtering. Asset query/update integrations added.</td>\n      </tr>\n      <tr>\n        <td><code>v7</code></td>\n        <td><code>5005</code></td>\n        <td>Port 5005 par dynamic CSV parsing aur bulk record uploads (Work Orders, Service Requests aur Assets).</td>\n      </tr>\n      <tr>\n        <td><code>v8</code></td>\n        <td><code>5006</code></td>\n        <td>Scikit-Learn Machine Learning classifier (<code>TfidfVectorizer</code> + <code>LogisticRegression</code>) jo pre-train hokar serialized pickle (.pkl) format me save hota hai (Port 5006).</td>\n      </tr>\n      <tr>\n        <td><code>v9 - v10</code></td>\n        <td><code>5001</code></td>\n        <td>Enterprise scikit-learn pipeline with parallel LLM parser (UltraAssist bot, port 5002). Added off-topic guardrails, user creation aur security group management.</td>\n      </tr>\n    </tbody>\n  </table>\n\n  <h3>Current Architecture: Version 10</h3>\n  <p>Current architecture fully modular hai: Jab user koi message bhejta hai, toh decoupled <code>nlp_engine.py</code> input preprocess karta hai, spelling distances calculate karta hai, synonyms expand karta hai, aur scikit-learn classifier ke zariye Intent (jaise <code>SEARCH_WORK_ORDER</code>, <code>UPDATE_RECORD</code>, <code>CREATE_SERVICE_REQUEST</code>) identify karta hai. Iske baad request dedicated API handlers ko route hokar Maximo OSLC REST API se directly communicate karti hai.</p>\n</section>"
  },
  "chatbot-audit": {
    "id": "chatbot-audit",
    "title": "4.2: Setup Audit Logging",
    "subtitle": "Configuring local trace logging for chatbot transactions.",
    "html": "<h1>4.2: Setup Audit Logging</h1>\n            <p class=\"page-subtitle\">Configuring local trace logging for chatbot transactions.</p>\n            \n            <section>\n              <h2>Trace Log File</h2>\n              <p>To audit operations and track changes triggered by the chatbot, every REST API call (queries and creations) is tracked in a local audit log file located in the workspace:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\">\n                  <span>Audit Log Path</span>\n                </div>\n                <pre>d:\\AI\\logs\\maximo_trace.json</pre>\n              </div>\n\n              <h2>Live Sidebar Audit Feed</h2>\n              <p>The chatbot interface features a dynamic sidebar component that polls this JSON file asynchronously on load and after every chat event, displaying timestamps, action labels, and parameters of recently handled integrations.</p>\n            </section>",
    "title_hi": "4.2: Audit Trace Logs Setup Karein",
    "subtitle_hi": "Chatbot ke transactions aur REST API calls ke liye local trace logging configure karna.",
    "html_hi": "<h1>4.2: Audit Trace Logs Setup Karein</h1>\n<p class=\"page-subtitle\">Chatbot ke transactions aur REST API calls ke liye local trace logging configure karna.</p>\n<section>\n  <h2>Trace Log File Ka Path</h2>\n  <p>Chatbot ke dwara kiye gaye har operation aur REST API query/creation ko track karne ke liye JSON audit log file use hoti hai:</p>\n  <div class=\"ibm-code-block\">\n    <div class=\"ibm-code-header\"><span>Audit Log Path</span></div>\n    <pre>d:\\AI\\logs\\maximo_trace.json</pre>\n  </div>\n\n  <h2>Live Sidebar Audit Feed</h2>\n  <p>Chatbot UI me ek real-time dynamic sidebar component hai jo is JSON file ko har chat event ke baad asynchronously poll karta hai, aur recent actions ke timestamps, status codes aur payload parameters live display karta hai.</p>\n</section>"
  },
  "chatbot-query-wo": {
    "id": "chatbot-query-wo",
    "title": "4.3: Work Order Queries & Follow-Up Mapping",
    "subtitle": "Extracting deep record structures and mapping follow-up dialogues.",
    "html": "<h1>4.3: Work Order Queries & Follow-Up Mapping</h1>\n            <p class=\"page-subtitle\">Extracting deep record structures and mapping follow-up dialogues.</p>\n            \n            <section>\n              <h2>Scoping All Fields (oslc.properties=*)</h2>\n              <p>When searching for a Work Order (e.g. <code>Find WO 1000</code>), the chatbot backend initiates an OSLC query request fetching all available properties. This large JSON dataset is returned and cached directly inside the conversation context state.</p>\n\n              <h2>Rules-Based Follow-Up Matching</h2>\n              <p>Once a Work Order is active in the context, you can type conversational follow-up questions asking for specific fields (e.g. <em>\"what is the status?\"</em>, <em>\"where is the location?\"</em>). The chatbot maps your query synonyms to JSON properties:</p>\n              \n              <table class=\"ibm-data-table\">\n                <thead>\n                  <tr>\n                    <th>Keyword Synonym</th>\n                    <th>Target OSLC Property</th>\n                    <th>Display Label</th>\n                  </tr>\n                </thead>\n                <tbody>\n                  <tr>\n                    <td>status</td>\n                    <td>spi:status</td>\n                    <td>Status</td>\n                  </tr>\n                  <tr>\n                    <td>location</td>\n                    <td>spi:location</td>\n                    <td>Location</td>\n                  </tr>\n                  <tr>\n                    <td>asset / asset ID</td>\n                    <td>spi:assetnum</td>\n                    <td>Asset ID</td>\n                  </tr>\n                  <tr>\n                    <td>priority</td>\n                    <td>spi:wopriority</td>\n                    <td>Priority</td>\n                  </tr>\n                  <tr>\n                    <td>start / start date</td>\n                    <td>spi:targstartdate</td>\n                    <td>Target Start</td>\n                  </tr>\n                  <tr>\n                    <td>finish / end date</td>\n                    <td>spi:targcompdate</td>\n                    <td>Target Finish</td>\n                  </tr>\n                </tbody>\n              </table>\n\n              <h2>Behind the Scenes: Follow-Up Parsing</h2>\n              <p>When the user sends a message, the server checks if context flow is set to <code>followup_wo</code>. It then checks if the text contains any mapped synonyms and returns the corresponding cached data:</p>\n\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\">\n                  <span>Python Follow-Up Logic</span>\n                </div>\n                <pre>if flow == \"followup_wo\":\n    wo_data = context.get(\"wo_data\", {})\n    wonum = wo_data.get(\"spi:wonum\") or wo_data.get(\"wonum\", \"Unknown\")\n    msg_lower = message.lower()\n    \n    mappings = {\n        \"status\": (\"status\", \"Status\"),\n        \"location\": (\"location\", \"Location\"),\n        \"asset\": (\"assetnum\", \"Asset ID\"),\n        \"description\": (\"description\", \"Description\"),\n        \"priority\": (\"wopriority\", \"Priority\"),\n        \"start\": (\"targstartdate\", \"Target Start\"),\n        \"finish\": (\"targcompdate\", \"Target Finish\"),\n        \"reporter\": (\"reportedby\", \"Reported By\")\n    }\n    \n    matched_field = None\n    for keyword, (field_key, label) in mappings.items():\n        if keyword in msg_lower:\n            matched_field = (field_key, label)\n            break\n            \n    if matched_field:\n        field_key, label = matched_field\n        val = wo_data.get(f\"spi:{field_key}\") or wo_data.get(field_key)\n        # Return matched property text ...</pre>\n              </div>\n\n              <h2>Handling Non-Serializable JSON Data</h2>\n              <p>Maximo payloads contain complex fields like byte sequences (e.g. <code>_rowstamp</code>). Standard JSON encoders will crash on these types. The backend runs a recursive sanitizing function before returning payload data:</p>\n\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\">\n                  <span>Payload Sanitizer</span>\n                </div>\n                <pre>def sanitize_json(data):\n    if isinstance(data, dict):\n        return {k: sanitize_json(v) for k, v in data.items()}\n    elif isinstance(data, list):\n        return [sanitize_json(v) for v in data]\n    elif isinstance(data, bytes):\n        return data.decode(\"utf-8\", errors=\"ignore\")\n    try:\n        json.dumps(data)\n        return data\n    except TypeError:\n        return str(data)</pre>\n              </div>\n\n              <div class=\"ibm-callout\">\n                <div class=\"ibm-callout-title\"><i class=\"fa-solid fa-arrow-right-to-bracket\"></i> Graceful Breakout</div>\n                <div class=\"ibm-callout-content\">\n                  <p>If the user requests a new command (like searching a different ID or creating a ticket) while in a follow-up session, the chatbot automatically clears the old context and serves the new scenario.</p>\n                </div>\n              </div>\n            </section>",
    "title_hi": "4.3: Work Order Query Aur Conversational Follow-Up Mapping",
    "subtitle_hi": "Maximo se deep JSON structure fetch karna aur natural follow-up sawalon ka context mapping.",
    "html_hi": "<h1>4.3: Work Order Query Aur Conversational Follow-Up Mapping</h1>\n<p class=\"page-subtitle\">Maximo se deep JSON structure fetch karna aur natural follow-up sawalon ka context mapping.</p>\n<section>\n  <h2>Scoping All Fields (oslc.properties=*)</h2>\n  <p>Jab user Work Order search karta hai (jaise <code>Find WO 1000</code>), backend OSLC query bhejta hai jo saari properties (<code>oslc.properties=*</code>) fetch karke conversation context state me cache kar leti hai.</p>\n\n  <h2>Rules-Based Follow-Up Matching</h2>\n  <p>Ek baar record context me load ho jaye, user specific sawal puch sakta hai (jaise <em>\"status kya hai?\"</em>, <em>\"location kahan hai?\"</em>). Chatbot keyword synonyms ko direct JSON properties par map kar deta hai:</p>\n  \n  <table class=\"ibm-data-table\">\n    <thead>\n      <tr><th>Keyword Synonym</th><th>Target OSLC Property</th><th>Display Label</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>status</td><td>spi:status</td><td>Status</td></tr>\n      <tr><td>location</td><td>spi:location</td><td>Location</td></tr>\n      <tr><td>asset / asset ID</td><td>spi:assetnum</td><td>Asset ID</td></tr>\n      <tr><td>priority</td><td>spi:wopriority</td><td>Priority</td></tr>\n      <tr><td>start / start date</td><td>spi:targstartdate</td><td>Target Start</td></tr>\n      <tr><td>finish / end date</td><td>spi:targcompdate</td><td>Target Finish</td></tr>\n    </tbody>\n  </table>\n\n  <h2>Follow-Up Parsing Ka Python Code</h2>\n  <div class=\"ibm-code-block\">\n    <div class=\"ibm-code-header\"><span>Python Follow-Up Logic</span></div>\n    <pre>if flow == \"followup_wo\":\n    wo_data = context.get(\"wo_data\", {})\n    wonum = wo_data.get(\"spi:wonum\") or wo_data.get(\"wonum\", \"Unknown\")\n    msg_lower = message.lower()\n    \n    mappings = {\n        \"status\": (\"status\", \"Status\"),\n        \"location\": (\"location\", \"Location\"),\n        \"asset\": (\"assetnum\", \"Asset ID\"),\n        \"description\": (\"description\", \"Description\"),\n        \"priority\": (\"wopriority\", \"Priority\"),\n        \"start\": (\"targstartdate\", \"Target Start\"),\n        \"finish\": (\"targcompdate\", \"Target Finish\"),\n        \"reporter\": (\"reportedby\", \"Reported By\")\n    }\n    \n    matched_field = None\n    for keyword, (field_key, label) in mappings.items():\n        if keyword in msg_lower:\n            matched_field = (field_key, label)\n            break</pre>\n  </div>\n\n  <h2>Graceful Context Breakout</h2>\n  <div class=\"ibm-callout\">\n    <div class=\"ibm-callout-title\"><i class=\"fa-solid fa-arrow-right-to-bracket\"></i> Smart Context Switch</div>\n    <div class=\"ibm-callout-content\">\n      <p>Agar user follow-up session ke dauran koi naya command type karta hai (jaise dusra ID search karna ya naya ticket banana), chatbot purana context clear karke naye flow me switch kar jata hai.</p>\n    </div>\n  </div>\n</section>"
  },
  "chatbot-create-sr": {
    "id": "chatbot-create-sr",
    "title": "4.4: Guided Service Request Creation",
    "subtitle": "Integrating Service Requests with short and long descriptions.",
    "html": "<h1>4.4: Guided Service Request Creation</h1>\n            <p class=\"page-subtitle\">Integrating Service Requests with short and long descriptions.</p>\n            \n            <section>\n              <h2>Guided Dialogue Scenarios</h2>\n              <p>Type <code>Create SR</code> in the chat feed to launch the multi-turn guided scenario. The chatbot walks the user through setting the required information step-by-step:</p>\n              <ol>\n                <li><strong>Description:</strong> Entered as a short description.</li>\n                <li><strong>Long Description:</strong> Configures comprehensive ticket details.</li>\n                <li><strong>Asset Number:</strong> Links the Service Request to a specific asset in the system.</li>\n              </ol>\n\n              <h2>Behind the Scenes: State-Machine Multi-Turn Loop</h2>\n              <p>The Python server uses the <code>step</code> attribute in the context to determine which piece of information the user is submitting. It updates the state machine sequentially until the data is complete:</p>\n              <div class=\"ibm-code-block\">\n                <pre>if flow == \"create_sr\":\n    step = context.get(\"step\", 1)\n    data = context.get(\"data\", {})\n    \n    if step == 1:\n        data[\"description\"] = message\n        context[\"step\"] = 2\n        context[\"data\"] = data\n        reply = \"Got it. Now enter the **Long Description** (or type 'none'):\"\n        return {\"reply\": reply, \"context\": context}\n        \n    elif step == 2:\n        data[\"longdescription\"] = \"\" if message.lower() == \"none\" else message\n        context[\"step\"] = 3\n        # Request next variable ...</pre>\n              </div>\n\n              <h2>OSLC Key Mapping</h2>\n              <p>The chatbot constructs the final POST body matching Maximo's schema requirements. In particular, both descriptions are sent together:</p>\n              \n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\">\n                  <span>POST Payload mapping</span>\n                </div>\n                <pre>{\n    \"spi:description\": \"Short Description text\",\n    \"spi:description_longdescription\": \"Detailed long description content\",\n    \"spi:hasld\": true,\n    \"siteid\": \"BEDFORD\"\n}</pre>\n              </div>\n            </section>",
    "title_hi": "4.4: Guided Service Request Creation Dialogue",
    "subtitle_hi": "Multi-turn state machine ke zariye short aur long descriptions ke saath Service Request banana.",
    "html_hi": "<h1>4.4: Guided Service Request Creation Dialogue</h1>\n<p class=\"page-subtitle\">Multi-turn state machine ke zariye short aur long descriptions ke saath Service Request banana.</p>\n<section>\n  <h2>Multi-Turn Guided Flow</h2>\n  <p>Chat me <code>Create SR</code> type karne par guided scenario start hota hai:</p>\n  <ol>\n    <li><strong>Description:</strong> Short ticket summary enter karein.</li>\n    <li><strong>Long Description:</strong> Detailed problem information enter karein.</li>\n    <li><strong>Asset Number:</strong> Associated equipment/asset select karein.</li>\n  </ol>\n\n  <h2>State-Machine Loop Implementation</h2>\n  <div class=\"ibm-code-block\">\n    <pre>if flow == \"create_sr\":\n    step = context.get(\"step\", 1)\n    data = context.get(\"data\", {})\n    \n    if step == 1:\n        data[\"description\"] = message\n        context[\"step\"] = 2\n        context[\"data\"] = data\n        reply = \"Got it. Now enter the **Long Description** (or type 'none'):\"\n        return {\"reply\": reply, \"context\": context}\n        \n    elif step == 2:\n        data[\"longdescription\"] = \"\" if message.lower() == \"none\" else message\n        context[\"step\"] = 3</pre>\n  </div>\n\n  <h2>OSLC Payload Schema</h2>\n  <div class=\"ibm-code-block\">\n    <div class=\"ibm-code-header\"><span>POST JSON Payload</span></div>\n    <pre>{\n    \"spi:description\": \"Short Description text\",\n    \"spi:description_longdescription\": \"Detailed long description content\",\n    \"spi:hasld\": true,\n    \"siteid\": \"BEDFORD\"\n}</pre>\n  </div>\n</section>"
  },
  "chatbot-create-wo-update": {
    "id": "chatbot-create-wo-update",
    "title": "4.5: Create Work Orders &amp; Update Records",
    "subtitle": "Creating Work Orders via OSLC POST forms and updating WO/SR field values via chat-driven PATCH operations.",
    "html": "<h1>4.5: Create Work Orders &amp; Update Records</h1>\n            <p class=\"page-subtitle\">Creating Work Orders via OSLC POST forms and updating WO/SR field values via chat-driven PATCH operations.</p>\n            \n            <section>\n              <h2>Work Order Creation via Form</h2>\n              <p>Similar to Service Request creation, the chatbot provides a guided form for creating new Work Orders. The user types <code>Create WO</code> or <code>New Work Order</code> in the chat, which triggers the <code>CREATE_WORK_ORDER</code> intent and renders a form overlay.</p>\n              \n              <h3>API Route</h3>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>app.py — /api/create-wo</span></div>\n<pre>if self.path == \"/api/create-wo\":\n    form_data = json.loads(post_data.decode(\"utf-8\"))\n    result = create_work_order(form_data, credentials=credentials)</pre>\n              </div>\n\n              <h3>OSLC POST Payload</h3>\n              <p>The backend constructs the JSON payload, omitting empty optional attributes to prevent Maximo validation errors:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>workorder.py — create_work_order()</span></div>\n<pre>wo_url = f\"{BASE_URL}/oslc/os/mxapiwo\"\npayload = {\n    \"spi:description\": description,\n    \"spi:siteid\": site_id         # Defaults to BEDFORD\n}\n\n# Only include non-empty optional attributes\nif long_desc:\n    payload[\"spi:description_longdescription\"] = long_desc\nif assetnum:\n    payload[\"spi:assetnum\"] = assetnum\nif location:\n    payload[\"spi:location\"] = location\n\nstatus_code, res_headers, body = make_maximo_request(\n    wo_url, \"POST\", payload, credentials=credentials\n)</pre>\n              </div>\n\n              <h3>Retrieving the Created WONUM</h3>\n              <p>After a successful <code>201 Created</code> response, Maximo returns a <code>Location</code> header containing the URI of the newly created record. The chatbot follows this URI with a GET request to extract the auto-generated <code>WONUM</code>:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>Location Header Parsing</span></div>\n<pre># Response header: Location: http://localhost/maximo/oslc/os/mxapiwo/_QkVERk9SRC8xMDAy\nloc_header = res_headers.get(\"Location\")\nloc_rewritten = loc_header.replace(\n    \"http://localhost/maximo\", BASE_URL\n)\nsc, hd, bd = make_maximo_request(loc_rewritten, \"GET\", ...)\nwonum = json.loads(bd).get(\"spi:wonum\", \"Created\")</pre>\n              </div>\n\n              <div class=\"ibm-callout ibm-callout-info\">\n                <p><strong>Important:</strong> Maximo's internal Docker routing often returns <code>http://localhost/maximo</code> in the Location header, even when the external URL is different (e.g. <code>http://localhost:9084/maximo</code>). The <code>replace()</code> call rewrites the URI to match the actual configured base URL before the follow-up GET.</p>\n              </div>\n            </section>\n\n            <section>\n              <h2>Updating Record Fields via Chat</h2>\n              <p>The chatbot supports natural language record updates. Users can type commands like:</p>\n              <ul>\n                <li><code>Update WO 1002 status to CLOSE</code></li>\n                <li><code>Change SR 1177 priority to 3</code></li>\n                <li><code>Assign owner of WO 1010 to MAXADMIN</code></li>\n                <li><code>Close WO 1002</code> (implied status update)</li>\n              </ul>\n\n              <h3>NLU Entity Extraction Flow</h3>\n              <p>The chat engine extracts three entities from the message: <strong>record ID</strong>, <strong>field name</strong>, and <strong>update value</strong>:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>chat_engine.py — Entity Extraction</span></div>\n<pre># Extract Record ID (3+ digit number)\nid_match = re.search(r'\\b\\d{3,}\\b', message)\nrecord_id = id_match.group(0) if id_match else None\n\n# Extract Field Name from keywords\nfield_match = re.search(rf'\\b({fields_list})\\b', message, re.IGNORECASE)\nfield_name = field_match.group(1).lower() if field_match else None\n\n# Extract Update Value (after \"to\", \"as\", or \"=\")\nval_match = re.search(r'\\b(?:to|as|=)\\s+(.+)$', message, re.IGNORECASE)\nupdate_val = val_match.group(1).strip() if val_match else None</pre>\n              </div>\n\n              <h3>Implied Status Values</h3>\n              <p>When a user types <code>Close WO 1002</code> without explicitly saying \"status to CLOSE\", the engine detects implied status verbs:</p>\n              <table class=\"ibm-data-table\">\n                <thead>\n                  <tr><th>User Input</th><th>Implied Field</th><th>Implied Value</th></tr>\n                </thead>\n                <tbody>\n                  <tr><td>Close WO 1002</td><td>status</td><td>CLOSE</td></tr>\n                  <tr><td>Resolve SR 1177</td><td>status</td><td>RESOLVED</td></tr>\n                  <tr><td>Approve WO 1010</td><td>status</td><td>APPR</td></tr>\n                  <tr><td>Complete WO 1002</td><td>status</td><td>COMP</td></tr>\n                </tbody>\n              </table>\n            </section>\n\n            <section>\n              <h2>OSLC PATCH via x-method-override</h2>\n              <p>Maximo's OSLC API does not support the HTTP <code>PATCH</code> method directly. Instead, updates are sent as <code>POST</code> requests with an <code>x-method-override: PATCH</code> header. The target URL is the record's <code>rdf:about</code> member URI:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>workorder.py — update_work_order_field()</span></div>\n<pre># 1. Fetch the record to get its member URI\nwo_url = f\"{BASE_URL}/oslc/os/mxapiwo?oslc.where=wonum=%22{wo_num}%22\"\nstatus_code, headers, body = make_maximo_request(wo_url, \"GET\", ...)\nwo = json.loads(body)[\"rdfs:member\"][0]\nmember_uri = wo[\"rdf:about\"]\n\n# 2. Rewrite localhost URI\nmember_uri = member_uri.replace(\n    \"http://localhost/maximo\", BASE_URL\n)\n\n# 3. Send PATCH via POST with override header\npayload = {f\"spi:{mapped_field}\": value}\nupdate_headers = {\n    \"x-method-override\": \"PATCH\",\n    \"properties\": \"*\"\n}\nsc, hd, bd = make_maximo_request(\n    member_uri, \"POST\", payload,\n    credentials=credentials,\n    extra_headers=update_headers\n)</pre>\n              </div>\n\n              <h3>Field Mapping Table (Work Order)</h3>\n              <table class=\"ibm-data-table\">\n                <thead>\n                  <tr><th>User Keyword</th><th>OSLC Attribute</th><th>Aliases</th></tr>\n                </thead>\n                <tbody>\n                  <tr><td>status</td><td>spi:status</td><td>—</td></tr>\n                  <tr><td>description</td><td>spi:description</td><td>summary</td></tr>\n                  <tr><td>long description</td><td>spi:description_longdescription</td><td>details, longdescription</td></tr>\n                  <tr><td>asset</td><td>spi:assetnum</td><td>assetnum, asset number</td></tr>\n                  <tr><td>location</td><td>spi:location</td><td>—</td></tr>\n                  <tr><td>priority</td><td>spi:wopriority</td><td>wo priority</td></tr>\n                  <tr><td>work type</td><td>spi:worktype</td><td>worktype</td></tr>\n                  <tr><td>owner</td><td>spi:owner</td><td>—</td></tr>\n                  <tr><td>owner group</td><td>spi:ownergroup</td><td>ownergroup</td></tr>\n                  <tr><td>target start</td><td>spi:targstartdate</td><td>—</td></tr>\n                  <tr><td>target finish</td><td>spi:targcompdate</td><td>target completion</td></tr>\n                </tbody>\n              </table>\n            </section>\n\n            <section>\n              <h2>Validation Suggestions (Smart Error Recovery)</h2>\n              <p>When a WO or SR creation fails due to an invalid asset, location, or affected person, the chatbot doesn't just show the raw Maximo error. Instead, it queries Maximo for <strong>valid alternatives</strong> and suggests them to the user:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>workorder.py — get_validation_suggestions()</span></div>\n<pre># On asset validation failure, query active assets\nif attribute == \"assetnum\":\n    url = f\"{BASE_URL}/oslc/os/mxapiasset\" \\\n          f\"?oslc.where=status=%22OPERATING%22\" \\\n          f\"&amp;oslc.properties=assetnum,description\" \\\n          f\"&amp;oslc.pageSize=5\"\n    sc, hd, body = make_maximo_request(url, \"GET\", ...)\n    members = json.loads(body).get(\"rdfs:member\", [])\n    suggestions = [\n        f\"**{m['spi:assetnum']}** ({m['spi:description']})\"\n        for m in members\n    ]\n\n# Returns formatted error with suggestions:\n# ❌ Asset Error: BMXAA4169E ...\n# 💡 Here are some valid operating assets:\n#   - **11300** (Overhead Crane #1)\n#   - **11430** (Fire Pump #2)</pre>\n              </div>\n\n              <div class=\"ibm-callout ibm-callout-warning\">\n                <p><strong>Note:</strong> Validation suggestions query <code>OPERATING</code> assets and <code>ACTIVE</code> locations with <code>pageSize=5</code>. This keeps the suggestion list short and relevant without overwhelming the user.</p>\n              </div>\n            </section>",
    "title_hi": "4.5: Work Order Creation Aur Record Field Updates",
    "subtitle_hi": "OSLC POST form ke through Work Order banana aur chat-driven PATCH se field updates karna.",
    "html_hi": "<h1>4.5: Work Order Creation Aur Record Field Updates</h1>\n<p class=\"page-subtitle\">OSLC POST form ke through Work Order banana aur chat-driven PATCH se field updates karna.</p>\n<section>\n  <h2>Form Ke Zariye Work Order Creation</h2>\n  <p>Chat me <code>Create WO</code> type karne par form pop-up hota hai. Backend <code>/api/create-wo</code> par JSON payload bhejta hai:</p>\n  \n  <div class=\"ibm-code-block\">\n    <div class=\"ibm-code-header\"><span>workorder.py — create_work_order()</span></div>\n    <pre>wo_url = f\"{BASE_URL}/oslc/os/mxapiwo\"\npayload = {\n    \"spi:description\": description,\n    \"spi:siteid\": site_id         # Defaults to BEDFORD\n}\nif long_desc:\n    payload[\"spi:description_longdescription\"] = long_desc\nif assetnum:\n    payload[\"spi:assetnum\"] = assetnum\nif location:\n    payload[\"spi:location\"] = location\n\nstatus_code, res_headers, body = make_maximo_request(\n    wo_url, \"POST\", payload, credentials=credentials\n)</pre>\n  </div>\n\n  <h2>Natural Language Record Field Updates</h2>\n  <p>User natural language commands se records update kar sakta hai:</p>\n  <ul>\n    <li><code>Update WO 1002 status to CLOSE</code></li>\n    <li><code>Change SR 1177 priority to 3</code></li>\n    <li><code>Assign owner of WO 1010 to MAXADMIN</code></li>\n    <li><code>Close WO 1002</code> (implied status update)</li>\n  </ul>\n\n  <h2>OSLC PATCH Implementation (x-method-override)</h2>\n  <p>Maximo direct HTTP PATCH support nahi karta, isliye POST request ke saath <code>x-method-override: PATCH</code> header bhejte hain:</p>\n  <div class=\"ibm-code-block\">\n    <div class=\"ibm-code-header\"><span>PATCH Code</span></div>\n    <pre>payload = {f\"spi:{mapped_field}\": value}\nupdate_headers = {\n    \"x-method-override\": \"PATCH\",\n    \"properties\": \"*\"\n}\nsc, hd, bd = make_maximo_request(\n    member_uri, \"POST\", payload,\n    credentials=credentials,\n    extra_headers=update_headers\n)</pre>\n  </div>\n</section>"
  },
  "chatbot-query-sr": {
    "id": "chatbot-query-sr",
    "title": "4.6: Query Service Requests &amp; Follow-Ups",
    "subtitle": "Querying, inspecting, and updating Service Request records through conversational follow-up dialogues.",
    "html": "<h1>4.6: Query Service Requests &amp; Follow-Ups</h1>\n            <p class=\"page-subtitle\">Querying, inspecting, and updating Service Request records through conversational follow-up dialogues.</p>\n            \n            <section>\n              <h2>SR Query via Chat</h2>\n              <p>Type <code>Find SR 1177</code> or <code>Search ticket 1177</code> to query a Service Request. The chatbot sends an OSLC GET request fetching all properties and caches the full JSON response in the conversation context:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>servicerequest.py — query_service_request()</span></div>\n<pre>sr_url = f\"{BASE_URL}/oslc/os/mxapisr\" \\\n         f\"?oslc.where=ticketid=%22{sr_num}%22\" \\\n         f\"&amp;oslc.properties=*\"\nstatus_code, headers, body = make_maximo_request(\n    sr_url, \"GET\", credentials=credentials\n)\n\n# Cache full SR data in context for follow-up questions\nnew_context = {\n    \"flow\": \"followup_sr\",\n    \"sr_data\": sr\n}</pre>\n              </div>\n\n              <h3>Data Card Display</h3>\n              <p>The response includes a structured <code>dataCard</code> object that the frontend renders as a styled card widget:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>Data Card Structure</span></div>\n<pre>data_card = {\n    \"title\": f\"Service Request #{sr_num}\",\n    \"fields\": {\n        \"Ticket ID\": sr.get(\"spi:ticketid\"),\n        \"Status\":    sr.get(\"spi:status\"),\n        \"Description\": sr.get(\"spi:description\"),\n        \"Asset ID\":  sr.get(\"spi:assetnum\"),\n        \"Location\":  sr.get(\"spi:location\")\n    }\n}</pre>\n              </div>\n            </section>\n\n            <section>\n              <h2>Follow-Up Synonym Mapping</h2>\n              <p>Once a Service Request is active in context (<code>flow=followup_sr</code>), the user can ask natural follow-up questions. The SR follow-up mapper supports a broader set of fields than Work Orders:</p>\n              \n              <table class=\"ibm-data-table\">\n                <thead>\n                  <tr><th>Keyword</th><th>OSLC Property</th><th>Display Label</th></tr>\n                </thead>\n                <tbody>\n                  <tr><td>status</td><td>spi:status</td><td>Status</td></tr>\n                  <tr><td>location</td><td>spi:location</td><td>Location</td></tr>\n                  <tr><td>asset</td><td>spi:assetnum</td><td>Asset ID</td></tr>\n                  <tr><td>description / detail / summary</td><td>spi:description</td><td>Description</td></tr>\n                  <tr><td>report date / date / when</td><td>spi:reportdate</td><td>Report Date</td></tr>\n                  <tr><td>reported by / reporter / who</td><td>spi:reportedby</td><td>Reported By</td></tr>\n                  <tr><td>affected person / affected</td><td>spi:affectedperson</td><td>Affected Person</td></tr>\n                  <tr><td>phone</td><td>spi:phone</td><td>Contact Phone</td></tr>\n                  <tr><td>email</td><td>spi:emailaddress</td><td>Contact Email</td></tr>\n                  <tr><td>priority</td><td>spi:reportedpriority</td><td>Priority</td></tr>\n                  <tr><td>class</td><td>spi:classstructureid</td><td>Classification ID</td></tr>\n                  <tr><td>site</td><td>spi:siteid</td><td>Site ID</td></tr>\n                </tbody>\n              </table>\n\n              <h3>Word Boundary Matching</h3>\n              <p>To prevent substring collisions (e.g. \"update\" matching \"date\"), the follow-up engine uses regex word boundaries for matching:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>servicerequest.py — handle_sr_followup()</span></div>\n<pre>import re\nfor keyword, (field_key, label) in mappings.items():\n    # \\b prevents \"update\" from matching \"date\"\n    if re.search(r'\\b' + re.escape(keyword) + r'\\b', msg_lower):\n        matched_field = (field_key, label)\n        break</pre>\n              </div>\n            </section>\n\n            <section>\n              <h2>SR Field Updates via Chat</h2>\n              <p>Service Request fields can be updated using the same pattern as Work Orders. The SR update mapping table includes additional SR-specific fields:</p>\n              \n              <table class=\"ibm-data-table\">\n                <thead>\n                  <tr><th>User Keyword</th><th>OSLC Attribute</th></tr>\n                </thead>\n                <tbody>\n                  <tr><td>status</td><td>spi:status</td></tr>\n                  <tr><td>description / summary</td><td>spi:description</td></tr>\n                  <tr><td>long description / details</td><td>spi:description_longdescription</td></tr>\n                  <tr><td>priority / reported priority</td><td>spi:reportedpriority</td></tr>\n                  <tr><td>internal priority</td><td>spi:internalpriority</td></tr>\n                  <tr><td>affected / affected person</td><td>spi:affectedperson</td></tr>\n                  <tr><td>reported by / reporter</td><td>spi:reportedby</td></tr>\n                  <tr><td>owner</td><td>spi:owner</td></tr>\n                  <tr><td>owner group</td><td>spi:ownergroup</td></tr>\n                  <tr><td>email</td><td>spi:emailaddress</td></tr>\n                  <tr><td>phone</td><td>spi:phone</td></tr>\n                  <tr><td>classification</td><td>spi:classstructureid</td></tr>\n                </tbody>\n              </table>\n\n              <div class=\"ibm-callout ibm-callout-info\">\n                <p><strong>Comparison with WO:</strong> Service Request updates use the same <code>x-method-override: PATCH</code> mechanism as Work Orders. The key difference is the field mapping table — SRs have fields like <code>affectedperson</code>, <code>reportedpriority</code>, and <code>internalpriority</code> that don't exist on Work Orders, while WOs have <code>wopriority</code>, <code>worktype</code>, and target date fields.</p>\n              </div>\n            </section>",
    "title_hi": "4.6: Service Request Query Aur Field Updates",
    "subtitle_hi": "Service Request tickets search karna aur follow-up conversations se updates karna.",
    "html_hi": "<h1>4.6: Service Request Query Aur Field Updates</h1>\n<p class=\"page-subtitle\">Service Request tickets search karna aur follow-up conversations se updates karna.</p>\n<section>\n  <h2>Service Request Search Karna</h2>\n  <p>User chat me <code>Find SR 1177</code> type karta hai. Backend <code>mxapisr</code> Object Structure se full ticket payload fetch karta hai:</p>\n  <div class=\"ibm-code-block\">\n    <div class=\"ibm-code-header\"><span>servicerequest.py — query_service_request()</span></div>\n    <pre>sr_url = f\"{BASE_URL}/oslc/os/mxapisr?oslc.where=ticketid=%22{sr_num}%22&amp;oslc.properties=*\"\nstatus_code, headers, body = make_maximo_request(sr_url, \"GET\", credentials=credentials)</pre>\n  </div>\n\n  <h2>SR Specific Field Mapping</h2>\n  <p>Service Request me Work Order ke alawa extra fields hote hain jaise <code>affectedperson</code>, <code>reportedpriority</code>, aur <code>internalpriority</code> jise follow-up engine map karta hai.</p>\n</section>"
  },
  "chatbot-user-secgroup": {
    "id": "chatbot-user-secgroup",
    "title": "4.7: User &amp; Security Group Management",
    "subtitle": "Creating Maximo users via nested Person/maxuser Object Structures and managing security group assignments via OSLC PATCH.",
    "html": "<h1>4.7: User &amp; Security Group Management</h1>\n            <p class=\"page-subtitle\">Creating Maximo users via nested Person/maxuser Object Structures and managing security group assignments via OSLC PATCH.</p>\n            \n            <section>\n              <h2>Create User via OSLC</h2>\n              <p>The chatbot creates Maximo users through the <code>mxperuser</code> Object Structure, which wraps both the <strong>PERSON</strong> and <strong>MAXUSER</strong> MBOs in a single nested POST request. The user types <code>Create User</code> in the chat, and a form is rendered.</p>\n\n              <h3>API Route</h3>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>app.py — /api/create-user</span></div>\n<pre>if self.path == \"/api/create-user\":\n    form_data = json.loads(post_data.decode(\"utf-8\"))\n    userid = form_data.get(\"userid\", \"\").strip()\n    password = form_data.get(\"password\", \"\").strip()\n    firstname = form_data.get(\"firstname\", \"\").strip()\n    lastname = form_data.get(\"lastname\", \"\").strip()\n    \n    result = create_user(userid, password, firstname, lastname,\n                         credentials=credentials)</pre>\n              </div>\n\n              <h3>Nested Object Structure Payload</h3>\n              <p>The <code>mxperuser</code> Object Structure requires a nested <code>spi:maxuser</code> child array to create the login credentials alongside the person record:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>user.py — create_user()</span></div>\n<pre>url = f\"{BASE_URL}/oslc/os/mxperuser\"\n\npayload = {\n    \"spi:personid\":     username.upper(),\n    \"spi:firstname\":    firstname,\n    \"spi:lastname\":     lastname,\n    \"spi:primaryemail\": email or f\"{username.lower()}@example.com\",\n    \"spi:maxuser\": [\n        {\n            \"spi:userid\":          username.upper(),\n            \"spi:passwordinput\":   password,\n            \"spi:passwordcheck\":   password,\n            \"spi:emailpswd\":       0,   # Don't email password\n            \"spi:forceexpiration\": 0    # Don't force change on login\n        }\n    ]\n}</pre>\n              </div>\n\n              <div class=\"ibm-callout ibm-callout-warning\">\n                <p><strong>Key Pattern:</strong> This is a <strong>nested child MBO creation</strong> — the <code>spi:maxuser</code> array creates a MAXUSER record linked to the parent PERSON record in a single POST. Without this nesting, you would need two separate API calls (create person, then create maxuser).</p>\n              </div>\n\n              <h3>Required Fields</h3>\n              <table class=\"ibm-data-table\">\n                <thead><tr><th>Field</th><th>Level</th><th>OSLC Key</th><th>Notes</th></tr></thead>\n                <tbody>\n                  <tr><td>Person ID</td><td>Parent</td><td><code>spi:personid</code></td><td>Auto-uppercased</td></tr>\n                  <tr><td>First Name</td><td>Parent</td><td><code>spi:firstname</code></td><td>Required</td></tr>\n                  <tr><td>Last Name</td><td>Parent</td><td><code>spi:lastname</code></td><td>Required</td></tr>\n                  <tr><td>Email</td><td>Parent</td><td><code>spi:primaryemail</code></td><td>Defaults to userid@example.com</td></tr>\n                  <tr><td>User ID</td><td>Child (maxuser)</td><td><code>spi:userid</code></td><td>Must match personid</td></tr>\n                  <tr><td>Password</td><td>Child (maxuser)</td><td><code>spi:passwordinput</code></td><td>Plain text, Maximo hashes it</td></tr>\n                  <tr><td>Password Confirm</td><td>Child (maxuser)</td><td><code>spi:passwordcheck</code></td><td>Must match passwordinput</td></tr>\n                </tbody>\n              </table>\n            </section>\n\n            <section>\n              <h2>Security Group Management via Chat</h2>\n              <p>The chatbot supports adding and removing security groups from users through natural language commands:</p>\n              <ul>\n                <li><code>Add security group MAXADMIN to user JOHN</code></li>\n                <li><code>Remove security group MAXDEVREG from user FATE12</code></li>\n              </ul>\n\n              <h3>NLU Entity Parsing</h3>\n              <p>The chat engine uses regex patterns to extract the group name and username from the message:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>chat_engine.py — Entity Extraction</span></div>\n<pre># Pattern: add/assign/map [security] group &lt;GROUP&gt; [to] [user] &lt;USER&gt;\ngroup_to_user_match = re.search(\n    r'\\b(?:add|assign|map)\\s+(?:security\\s+)?group\\s+(\\w+)'\n    r'\\s+(?:to\\s+)?(?:user\\s+)?(\\w+)\\b',\n    message, re.IGNORECASE\n)\n\n# Pattern: remove/delete/revoke [security] group &lt;GROUP&gt; [from] [user] &lt;USER&gt;\ngroup_from_user_match = re.search(\n    r'\\b(?:remove|delete|revoke)\\s+(?:security\\s+)?group\\s+(\\w+)'\n    r'\\s+(?:from\\s+)?(?:user\\s+)?(\\w+)\\b',\n    message, re.IGNORECASE\n)</pre>\n              </div>\n\n              <h3>OSLC PATCH with _action Directives</h3>\n              <p>Security group assignment uses the <code>_action: \"Add\"</code> directive inside a MERGE PATCH request. This tells Maximo to add a new child record to the <code>groupuser</code> collection without replacing existing groups:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>user.py — add_security_group()</span></div>\n<pre># First: get the user's member URI via mxl_usergrp\nmember_uri = get_user_member_uri(username)\n\n# Then: PATCH with _action directive\npayload = {\n    \"groupuser\": [\n        {\"groupname\": \"MAXADMIN\", \"_action\": \"Add\"}\n    ],\n    \"spi:groupuser\": [\n        {\"spi:groupname\": \"MAXADMIN\", \"_action\": \"Add\"}\n    ]\n}\n\nupdate_headers = {\n    \"x-method-override\": \"PATCH\",\n    \"patchtype\": \"MERGE\",     # Critical: MERGE preserves existing groups\n    \"properties\": \"*\"\n}\n\nmake_maximo_request(member_uri, \"POST\", payload,\n                    extra_headers=update_headers)</pre>\n              </div>\n\n              <div class=\"ibm-callout ibm-callout-info\">\n                <p><strong>Dual-Key Pattern:</strong> The payload includes both <code>groupuser</code> (non-prefixed) and <code>spi:groupuser</code> (prefixed) arrays. This ensures compatibility across different Maximo OSLC implementations where the namespace prefix handling may vary.</p>\n              </div>\n\n              <h3>Removing Security Groups</h3>\n              <p>Removal uses the same pattern but with <code>_action: \"Delete\"</code>:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>user.py — remove_security_group()</span></div>\n<pre>payload = {\n    \"groupuser\": [\n        {\"groupname\": \"MAXDEVREG\", \"_action\": \"Delete\"}\n    ],\n    \"spi:groupuser\": [\n        {\"spi:groupname\": \"MAXDEVREG\", \"_action\": \"Delete\"}\n    ]\n}</pre>\n              </div>\n            </section>",
    "title_hi": "4.7: User Aur Security Group Management",
    "subtitle_hi": "Nested mxperuser Object Structure se user create karna aur OSLC PATCH se groups assign karna.",
    "html_hi": "<h1>4.7: User Aur Security Group Management</h1>\n<p class=\"page-subtitle\">Nested mxperuser Object Structure se user create karna aur OSLC PATCH se groups assign karna.</p>\n<section>\n  <h2>User Creation (Nested Object Structure)</h2>\n  <p><code>mxperuser</code> Object Structure ek hi POST call me <strong>PERSON</strong> aur child <strong>MAXUSER</strong> dono MBOs create karta hai:</p>\n  <div class=\"ibm-code-block\">\n    <div class=\"ibm-code-header\"><span>user.py — create_user()</span></div>\n    <pre>payload = {\n    \"spi:personid\":     username.upper(),\n    \"spi:firstname\":    firstname,\n    \"spi:lastname\":     lastname,\n    \"spi:primaryemail\": email or f\"{username.lower()}@example.com\",\n    \"spi:maxuser\": [\n        {\n            \"spi:userid\":          username.upper(),\n            \"spi:passwordinput\":   password,\n            \"spi:passwordcheck\":   password,\n            \"spi:emailpswd\":       0,\n            \"spi:forceexpiration\": 0\n        }\n    ]\n}</pre>\n  </div>\n\n  <h2>Security Group Assign Aur Remove Karna</h2>\n  <p>Chatbot me natural commands support hote hain:</p>\n  <ul>\n    <li><code>Add security group MAXADMIN to user JOHN</code></li>\n    <li><code>Remove security group MAXDEVREG from user FATE12</code></li>\n  </ul>\n  <p>Child <code>groupuser</code> collection me <code>_action: \"Add\"</code> aur <code>patchtype: MERGE</code> ke saath PATCH bhejte hain.</p>\n</section>"
  },
  "chatbot-labor-craft": {
    "id": "chatbot-labor-craft",
    "title": "4.8: Labor Management &amp; Craft Mapping",
    "subtitle": "Creating labor records, mapping crafts/skills, and updating labor attributes via the MXAPILABOR Object Structure.",
    "html": "<h1>4.8: Labor Management &amp; Craft Mapping</h1>\n            <p class=\"page-subtitle\">Creating labor records, mapping crafts/skills, and updating labor attributes via the MXAPILABOR Object Structure.</p>\n            \n            <section>\n              <h2>Create Labor</h2>\n              <p>The chatbot creates Labor records through the <code>mxapilabor</code> Object Structure. The user types <code>Create Labor</code> in the chat, and a form is rendered asking for the labor code, organization ID, and optionally a person ID.</p>\n\n              <h3>API Route</h3>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>app.py — /api/create-labor</span></div>\n<pre>if self.path == \"/api/create-labor\":\n    form_data = json.loads(post_data.decode(\"utf-8\"))\n    laborcode = form_data.get(\"laborcode\", \"\").strip()\n    orgid = form_data.get(\"orgid\", \"\").strip()\n    personid = form_data.get(\"personid\", \"\").strip() or None\n    \n    result = create_labor(laborcode, orgid,\n                          personid=personid,\n                          credentials=credentials)</pre>\n              </div>\n\n              <h3>OSLC POST Payload</h3>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>labor.py — create_labor()</span></div>\n<pre>url = f\"{BASE_URL}/oslc/os/mxapilabor\"\n\npayload = {\n    \"spi:laborcode\": laborcode.upper(),\n    \"spi:orgid\":     orgid.upper(),\n    \"spi:personid\":  (personid or laborcode).upper(),\n    \"spi:status\":    \"ACTIVE\"\n}\n\nstatus_code, headers, body = make_maximo_request(\n    url, \"POST\", payload, credentials=credentials\n)</pre>\n              </div>\n\n              <h3>Required Fields</h3>\n              <table class=\"ibm-data-table\">\n                <thead><tr><th>Field</th><th>OSLC Key</th><th>Required</th><th>Default</th></tr></thead>\n                <tbody>\n                  <tr><td>Labor Code</td><td><code>spi:laborcode</code></td><td>Yes</td><td>—</td></tr>\n                  <tr><td>Organization ID</td><td><code>spi:orgid</code></td><td>Yes</td><td>—</td></tr>\n                  <tr><td>Person ID</td><td><code>spi:personid</code></td><td>Yes</td><td>Defaults to laborcode</td></tr>\n                  <tr><td>Status</td><td><code>spi:status</code></td><td>No</td><td>ACTIVE</td></tr>\n                </tbody>\n              </table>\n\n              <div class=\"ibm-callout ibm-callout-warning\">\n                <p><strong>Security Requirement:</strong> Labor creation via <code>mxapilabor</code> requires the <code>INSERT</code> signature option granted on the <code>MXAPILABOR</code> application for the calling user's security group. See <strong>Section 4.12: OSLC Security &amp; Troubleshooting</strong> for the full <code>BMXAA0024E</code> diagnosis guide.</p>\n              </div>\n            </section>\n\n            <section>\n              <h2>Map Craft to Labor</h2>\n              <p>After creating a Labor record, users can assign a craft and skill level via the <code>Map Craft</code> form. This uses the OSLC PATCH mechanism with a child <code>laborcraftrate</code> array:</p>\n\n              <h3>API Route</h3>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>app.py — /api/map-craft</span></div>\n<pre>if self.path == \"/api/map-craft\":\n    form_data = json.loads(post_data.decode(\"utf-8\"))\n    laborcode = form_data.get(\"laborcode\").strip()\n    craft = form_data.get(\"craft\").strip()\n    skilllevel = form_data.get(\"skilllevel\").strip() or None\n    orgid = form_data.get(\"orgid\").strip()\n    \n    result = map_labor_to_craft(laborcode, craft, skilllevel, orgid,\n                                credentials=credentials)</pre>\n              </div>\n\n              <h3>OSLC PATCH with Child Array Insertion</h3>\n              <p>The craft mapping is done via a MERGE PATCH that adds a new entry to the <code>laborcraftrate</code> child MBO collection:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>labor.py — map_labor_to_craft()</span></div>\n<pre># 1. Get the labor's member URI\nmember_uri = get_labor_member_uri(laborcode, orgid)\n\n# 2. PATCH with child array insertion\npayload = {\n    \"spi:laborcraftrate\": [\n        {\n            \"spi:craft\":      craft.upper(),\n            \"spi:skilllevel\":  skilllevel.upper(),\n            \"spi:orgid\":      orgid.upper(),\n            \"_action\":        \"Add\"\n        }\n    ]\n}\n\nupdate_headers = {\n    \"x-method-override\": \"PATCH\",\n    \"patchtype\": \"MERGE\",\n    \"properties\": \"*\"\n}\n\nmake_maximo_request(member_uri, \"POST\", payload,\n                    extra_headers=update_headers)</pre>\n              </div>\n\n              <div class=\"ibm-callout ibm-callout-info\">\n                <p><strong>Pattern Reuse:</strong> This is the same <code>_action: \"Add\"</code> + <code>patchtype: MERGE</code> pattern used for Security Group assignments (Section 4.7). It's a universal OSLC pattern for inserting child MBO records into a parent without replacing existing entries.</p>\n              </div>\n            </section>\n\n            <section>\n              <h2>Update Labor</h2>\n              <p>The chatbot also supports updating existing labor attributes like status, supervisor, and calendar through the <code>Update Labor</code> form:</p>\n\n              <h3>API Route</h3>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>app.py — /api/update-labor</span></div>\n<pre>if self.path == \"/api/update-labor\":\n    form_data = json.loads(post_data.decode(\"utf-8\"))\n    laborcode = form_data.get(\"laborcode\").strip()\n    orgid = form_data.get(\"orgid\").strip()\n    \n    updates = {}\n    if form_data.get(\"status\"):\n        updates[\"status\"] = form_data[\"status\"].strip().upper()\n    if form_data.get(\"supervisor\"):\n        updates[\"supervisor\"] = form_data[\"supervisor\"].strip().upper()\n    if form_data.get(\"calendar\"):\n        updates[\"calendar\"] = form_data[\"calendar\"].strip().upper()\n    \n    result = update_labor(laborcode, orgid, updates,\n                          credentials=credentials)</pre>\n              </div>\n\n              <h3>Generic Field Update Pattern</h3>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>labor.py — update_labor()</span></div>\n<pre># Build dynamic payload from provided updates\npayload = {}\nfor key, val in updates.items():\n    payload[f\"spi:{key}\"] = val\n\nupdate_headers = {\n    \"x-method-override\": \"PATCH\",\n    \"properties\": \"*\"\n}\n\nmake_maximo_request(member_uri, \"POST\", payload,\n                    extra_headers=update_headers)</pre>\n              </div>\n            </section>\n\n            <section>\n              <h2>Complete API Reference</h2>\n              <p>Summary of all Labor management endpoints:</p>\n              <table class=\"ibm-data-table\">\n                <thead>\n                  <tr><th>Operation</th><th>Route</th><th>Object Structure</th><th>HTTP Method</th></tr>\n                </thead>\n                <tbody>\n                  <tr><td>Create Labor</td><td><code>/api/create-labor</code></td><td>mxapilabor</td><td>POST</td></tr>\n                  <tr><td>Map Craft</td><td><code>/api/map-craft</code></td><td>mxapilabor (PATCH)</td><td>POST + x-method-override</td></tr>\n                  <tr><td>Update Labor</td><td><code>/api/update-labor</code></td><td>mxapilabor (PATCH)</td><td>POST + x-method-override</td></tr>\n                </tbody>\n              </table>\n            </section>",
    "title_hi": "4.8: Labor Management Aur Craft Mapping",
    "subtitle_hi": "MXAPILABOR se labor create karna, craft/skills map karna aur attributes update karna.",
    "html_hi": "<h1>4.8: Labor Management Aur Craft Mapping</h1>\n<p class=\"page-subtitle\">MXAPILABOR se labor create karna, craft/skills map karna aur attributes update karna.</p>\n<section>\n  <h2>Labor Creation (MXAPILABOR)</h2>\n  <p>Chat me <code>Create Labor</code> command se labor record create kiya jata hai:</p>\n  <div class=\"ibm-code-block\">\n    <div class=\"ibm-code-header\"><span>labor.py — create_labor()</span></div>\n    <pre>payload = {\n    \"spi:laborcode\": laborcode.upper(),\n    \"spi:orgid\":     orgid.upper(),\n    \"spi:personid\":  (personid or laborcode).upper(),\n    \"spi:status\":    \"ACTIVE\"\n}</pre>\n  </div>\n\n  <h2>Craft &amp; Skill Level Mapping</h2>\n  <p>Labor record banne ke baad craft assign karne ke liye <code>laborcraftrate</code> child MBO collection me MERGE PATCH bheja jata hai:</p>\n  <div class=\"ibm-code-block\">\n    <pre>payload = {\n    \"spi:laborcraftrate\": [\n        {\n            \"spi:craft\":      craft.upper(),\n            \"spi:skilllevel\":  skilllevel.upper(),\n            \"spi:orgid\":      orgid.upper(),\n            \"_action\":        \"Add\"\n        }\n    ]\n}</pre>\n  </div>\n</section>"
  },
  "chatbot-checklist": {
    "id": "chatbot-checklist",
    "title": "4.9: Maximo Chatbot Integration Checklist",
    "subtitle": "Track your configuration progress for Maximo REST Chatbot access.",
    "html": "<h1>4.9: Maximo Chatbot Integration Checklist</h1>\n            <p class=\"page-subtitle\">Track your configuration progress for Maximo REST Chatbot access.</p>\n            \n            <section>\n              <h2>Checklist</h2>\n              <p>Ensure that all steps for launching and running the Maximo REST integration chatbot are complete:</p>\n              \n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-chatbot-server\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>Chatbot Server Running (Port 5001)</h4>\n                  <p>Start `tools/chatbot_app_v3.py` in the background and confirm it is listening on port 5001.</p>\n                </div>\n              </label>\n\n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-chatbot-ui\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>Versioned UI Assets Ready</h4>\n                  <p>Versioned outputs folder `outputs/others/maximo_chatbot_v2` contains the index.html, style.css, and app.js assets.</p>\n                </div>\n              </label>\n\n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-chatbot-audit-ok\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>Audit Logging Active</h4>\n                  <p>Confirm `d:\\AI\\logs\\maximo_trace.json` is created and gets updated with dynamic records during transactions.</p>\n                </div>\n              </label>\n\n              <label class=\"ibm-checkbox-container\">\n                <input type=\"checkbox\" id=\"chk-chatbot-followup\">\n                <div class=\"ibm-checkbox-text\">\n                  <h4>Follow-Up Queries Validated</h4>\n                  <p>Run query `Find WO 1000` followed by `what is the location?` and verify the correct database values are mapped.</p>\n                </div>\n              </label>\n            </section>",
    "title_hi": "4.9: Maximo Chatbot Integration Checklist",
    "subtitle_hi": "Chatbot server, UI assets aur OSLC queries verify karne ka progress checklist.",
    "html_hi": "<h1>4.9: Maximo Chatbot Integration Checklist</h1>\n<p class=\"page-subtitle\">Chatbot server, UI assets aur OSLC queries verify karne ka progress checklist.</p>\n<section>\n  <h2>Verification Checklist</h2>\n  <label class=\"ibm-checkbox-container\">\n    <input type=\"checkbox\" id=\"chk-chatbot-server\">\n    <div class=\"ibm-checkbox-text\">\n      <h4>Chatbot Web Server Active (Port 5001)</h4>\n      <p>Python web server port 5001 par running hai aur /api endpoints respond kar rahe hain.</p>\n    </div>\n  </label>\n\n  <label class=\"ibm-checkbox-container\">\n    <input type=\"checkbox\" id=\"chk-chatbot-ui\">\n    <div class=\"ibm-checkbox-text\">\n      <h4>UI Components Loaded</h4>\n      <p>Dynamic chat UI and trace sidebar loaded properly.</p>\n    </div>\n  </label>\n\n  <label class=\"ibm-checkbox-container\">\n    <input type=\"checkbox\" id=\"chk-chatbot-audit-ok\">\n    <div class=\"ibm-checkbox-text\">\n      <h4>Audit Log Tracing Active</h4>\n      <p>maximo_trace.json file me API logs update ho rahe hain.</p>\n    </div>\n  </label>\n</section>"
  },
  "chatbot-download-config": {
    "id": "chatbot-download-config",
    "title": "4.6: Chatbot v10 Code &amp; Environment Setup",
    "subtitle": "Full copyable source code and configuration details for enterprise environments.",
    "html": "<h1>4.6: Chatbot v10 Code &amp; Environment Setup</h1>\n            <p class=\"page-subtitle\">Full copyable source code and configuration details for enterprise environments.</p>\n            \n            <section>\n              <h2>Environment Configuration Variables</h2>\n              <p>When deploying Chatbot v10, specify the target configuration in <code>d:\\AI\\connection_config\\maximo.json</code>:</p>\n              <div class=\"ibm-code-block\">\n                <pre>{\n  \"MAXIMO_BASE_URL\": \"http://localhost:9084/maximo\"\n}</pre>\n              </div>\n\n              <h2>Maximo Chatbot v10 Core Code</h2>\n              \n              <h3>1. Web Server: app.py</h3>\n              <div class=\"ibm-code-block\" style=\"max-height: 350px; overflow-y: auto;\">\n                <div class=\"ibm-code-header\"><span>app.py</span></div>\n                <pre># app.py\nimport os\nimport json\nimport urllib.parse\nfrom http.server import HTTPServer, BaseHTTPRequestHandler\nfrom http.cookies import SimpleCookie\nimport config\nfrom maximo_client import make_maximo_request\nfrom apis.servicerequest import create_service_request\nfrom apis.workorder import create_work_order\nfrom chat_engine import handle_chat_message\nimport session_store\n\ndef sanitize_json(data):\n    if isinstance(data, dict):\n        return {k: sanitize_json(v) for k, v in data.items()}\n    elif isinstance(data, list):\n        return [sanitize_json(v) for v in data]\n    elif isinstance(data, bytes):\n        return data.decode(&quot;utf-8&quot;, errors=&quot;ignore&quot;)\n    try:\n        json.dumps(data)\n        return data\n    except TypeError:\n        return str(data)\n\nclass ChatbotHTTPHandler(BaseHTTPRequestHandler):\n    def log_message(self, format, *args):\n        print(f&quot;[HTTP] {format%args}&quot;)\n\n    def get_session_credentials(self):\n        cookie_header = self.headers.get(&quot;Cookie&quot;)\n        if not cookie_header:\n            return None\n        cookie = SimpleCookie(cookie_header)\n        if &quot;session_id&quot; not in cookie:\n            return None\n        session_id = cookie[&quot;session_id&quot;].value\n        return session_store.get_session(session_id)\n\n    def do_GET(self):\n        # Serve API: Get Current Session User\n        if self.path == &quot;/api/session&quot;:\n            credentials = self.get_session_credentials()\n            if not credentials:\n                self.send_response(401)\n                self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n                self.end_headers()\n                self.wfile.write(json.dumps({&quot;error&quot;: &quot;Unauthorized&quot;}).encode(&quot;utf-8&quot;))\n                return\n            \n            # Fetch default site from whoami\n            insert_site = &quot;BEDFORD&quot;\n            try:\n                whoami_url = f&quot;{config.get_maximo_base_url()}/oslc/whoami&quot;\n                status, hd, body = make_maximo_request(whoami_url, &quot;GET&quot;, credentials=credentials)\n                if status == 200:\n                    whoami_data = json.loads(body)\n                    insert_site = whoami_data.get(&quot;insertSite&quot;) or whoami_data.get(&quot;insertsite&quot;) or &quot;BEDFORD&quot;\n            except Exception as e:\n                print(f&quot;Error fetching whoami details: {e}&quot;)\n\n            self.send_response(200)\n            self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n            self.end_headers()\n            self.wfile.write(json.dumps({\n                &quot;username&quot;: credentials.get(&quot;user&quot;),\n                &quot;insertSite&quot;: insert_site\n            }).encode(&quot;utf-8&quot;))\n            return\n\n        # Serve API: Get Maximo URL Configuration\n        if self.path == &quot;/api/config&quot;:\n            self.send_response(200)\n            self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n            self.end_headers()\n            self.wfile.write(json.dumps({&quot;MAXIMO_BASE_URL&quot;: config.get_maximo_base_url()}).encode(&quot;utf-8&quot;))\n            return\n\n        # Serve static UI files\n        static_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), &quot;static&quot;)\n        \n        # Clean query parameters first\n        path_clean = self.path.split(&quot;?&quot;)[0]\n        target_path = path_clean.lstrip(&quot;/&quot;)\n        \n        if not target_path or target_path == &quot;&quot;:\n            target_path = &quot;index.html&quot;\n            \n        file_path = os.path.join(static_dir, target_path)\n        \n        # Verify file path bounds\n        abs_static = os.path.abspath(static_dir)\n        abs_target = os.path.abspath(file_path)\n        \n        if not abs_target.startswith(abs_static) or not os.path.exists(file_path) or os.path.isdir(file_path):\n            self.send_response(404)\n            self.end_headers()\n            self.wfile.write(b&quot;File Not Found&quot;)\n            return\n\n        # Serve static resource\n        content_type = &quot;text/html&quot;\n        if file_path.endswith(&quot;.css&quot;):\n            content_type = &quot;text/css&quot;\n        elif file_path.endswith(&quot;.js&quot;):\n            content_type = &quot;application/javascript&quot;\n            \n        self.send_response(200)\n        self.send_header(&quot;Content-Type&quot;, content_type)\n        self.end_headers()\n        with open(file_path, &quot;rb&quot;) as f:\n            self.wfile.write(f.read())\n\n    def do_POST(self):\n        # 1. API: Login\n        if self.path == &quot;/api/login&quot;:\n            content_length = int(self.headers.get(&#x27;Content-Length&#x27;, 0))\n            post_data = self.rfile.read(content_length)\n            try:\n                login_data = json.loads(post_data.decode(&quot;utf-8&quot;))\n                username = login_data.get(&quot;username&quot;, &quot;&quot;).strip()\n                password = login_data.get(&quot;password&quot;, &quot;&quot;).strip()\n\n                if not username or not password:\n                    self.send_response(400)\n                    self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n                    self.end_headers()\n                    self.wfile.write(json.dumps({&quot;error&quot;: &quot;Username and password are required.&quot;}).encode(&quot;utf-8&quot;))\n                    return\n\n                # Validate credentials by querying whoami\n                creds = {&quot;user&quot;: username, &quot;pass&quot;: password}\n                whoami_url = f&quot;{config.get_maximo_base_url()}/oslc/whoami&quot;\n                status, hd, body = make_maximo_request(whoami_url, &quot;GET&quot;, credentials=creds)\n\n                if status == 200:\n                    session_id = session_store.create_session(username, password)\n                    self.send_response(200)\n                    self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n                    # Set Session Cookie\n                    cookie = SimpleCookie()\n                    cookie[&quot;session_id&quot;] = session_id\n                    cookie[&quot;session_id&quot;][&quot;path&quot;] = &quot;/&quot;\n                    cookie[&quot;session_id&quot;][&quot;httponly&quot;] = True\n                    self.send_header(&quot;Set-Cookie&quot;, cookie.output(header=&quot;&quot;))\n                    self.end_headers()\n                    self.wfile.write(json.dumps({&quot;success&quot;: True}).encode(&quot;utf-8&quot;))\n                else:\n                    self.send_response(401)\n                    self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n                    self.end_headers()\n                    self.wfile.write(json.dumps({&quot;error&quot;: &quot;Invalid username or password.&quot;}).encode(&quot;utf-8&quot;))\n            except Exception as e:\n                self.send_response(500)\n                self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n                self.end_headers()\n                self.wfile.write(json.dumps({&quot;error&quot;: str(e)}).encode(&quot;utf-8&quot;))\n            return\n\n        # 2. API: Update Maximo URL Configuration\n        if self.path == &quot;/api/config&quot;:\n            content_length = int(self.headers.get(&#x27;Content-Length&#x27;, 0))\n            post_data = self.rfile.read(content_length)\n            try:\n                config_data = json.loads(post_data.decode(&quot;utf-8&quot;))\n                new_url = config_data.get(&quot;MAXIMO_BASE_URL&quot;, &quot;&quot;).strip()\n                if not new_url:\n                    self.send_response(400)\n                    self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n                    self.end_headers()\n                    self.wfile.write(json.dumps({&quot;error&quot;: &quot;Maximo Base URL is required.&quot;}).encode(&quot;utf-8&quot;))\n                    return\n\n                # Write back to JSON file\n                with open(config.CONFIG_FILE, &quot;w&quot;, encoding=&quot;utf-8&quot;) as f:\n                    json.dump({&quot;MAXIMO_BASE_URL&quot;: new_url}, f, indent=2)\n\n                self.send_response(200)\n                self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n                self.end_headers()\n                self.wfile.write(json.dumps({&quot;success&quot;: True}).encode(&quot;utf-8&quot;))\n            except Exception as e:\n                self.send_response(500)\n                self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n                self.end_headers()\n                self.wfile.write(json.dumps({&quot;error&quot;: str(e)}).encode(&quot;utf-8&quot;))\n            return\n\n        # 3. API: Logout\n        if self.path == &quot;/api/logout&quot;:\n            cookie_header = self.headers.get(&quot;Cookie&quot;)\n            if cookie_header:\n                cookie = SimpleCookie(cookie_header)\n                if &quot;session_id&quot; in cookie:\n                    session_store.delete_session(cookie[&quot;session_id&quot;].value)\n            \n            self.send_response(200)\n            self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n            # Clear Cookie\n            cookie = SimpleCookie()\n            cookie[&quot;session_id&quot;] = &quot;&quot;\n            cookie[&quot;session_id&quot;][&quot;path&quot;] = &quot;/&quot;\n            cookie[&quot;session_id&quot;][&quot;httponly&quot;] = True\n            cookie[&quot;session_id&quot;][&quot;max-age&quot;] = 0\n            self.send_header(&quot;Set-Cookie&quot;, cookie.output(header=&quot;&quot;))\n            self.end_headers()\n            self.wfile.write(json.dumps({&quot;success&quot;: True}).encode(&quot;utf-8&quot;))\n            return\n\n        # ----------------------------------------------------\n        # Sessions Validation Middleware\n        # ----------------------------------------------------\n        credentials = self.get_session_credentials()\n        if not credentials:\n            self.send_response(401)\n            self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n            self.end_headers()\n            self.wfile.write(json.dumps({&quot;error&quot;: &quot;Unauthorized. Please log in.&quot;}).encode(&quot;utf-8&quot;))\n            return\n\n        # Serve API: Get Audit Logs\n        if self.path == &quot;/api/trace&quot;:\n            self.send_response(200)\n            self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n            self.end_headers()\n            with open(config.TRACE_LOG_PATH, &#x27;r&#x27;, encoding=&#x27;utf-8&#x27;) as f:\n                self.wfile.write(f.read().encode(&quot;utf-8&quot;))\n            return\n\n        # Serve API: Process Chat Message\n        if self.path == &quot;/api/chat&quot;:\n            content_length = int(self.headers.get(&#x27;Content-Length&#x27;, 0))\n            post_data = self.rfile.read(content_length)\n            \n            try:\n                req_data = json.loads(post_data.decode(&quot;utf-8&quot;))\n                message = req_data.get(&quot;message&quot;, &quot;&quot;)\n                context = req_data.get(&quot;context&quot;, {})\n                \n                response_payload = handle_chat_message(message, context, credentials=credentials)\n                \n                if response_payload.get(&quot;status&quot;) in [401, 403]:\n                    self.send_response(403)\n                else:\n                    self.send_response(200)\n                    \n                sanitized_payload = sanitize_json(response_payload)\n                self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n                self.end_headers()\n                self.wfile.write(json.dumps(sanitized_payload).encode(&quot;utf-8&quot;))\n            except Exception as e:\n                import traceback\n                traceback.print_exc()\n                self.send_response(500)\n                self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n                self.end_headers()\n                self.wfile.write(json.dumps({&quot;error&quot;: str(e)}).encode(&quot;utf-8&quot;))\n            return\n\n        # Serve API: Create Service Request\n        if self.path == &quot;/api/create-sr&quot;:\n            content_length = int(self.headers.get(&#x27;Content-Length&#x27;, 0))\n            post_data = self.rfile.read(content_length)\n            try:\n                form_data = json.loads(post_data.decode(&quot;utf-8&quot;))\n                result = create_service_request(form_data, credentials=credentials)\n                \n                if result.get(&quot;success&quot;):\n                    self.send_response(200)\n                else:\n                    self.send_response(400)\n                    \n                self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n                self.end_headers()\n                self.wfile.write(json.dumps(result).encode(&quot;utf-8&quot;))\n            except Exception as e:\n                self.send_response(500)\n                self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n                self.end_headers()\n                self.wfile.write(json.dumps({&quot;error&quot;: str(e)}).encode(&quot;utf-8&quot;))\n            return\n\n        # Serve API: Create Work Order\n        if self.path == &quot;/api/create-wo&quot;:\n            content_length = int(self.headers.get(&#x27;Content-Length&#x27;, 0))\n            post_data = self.rfile.read(content_length)\n            try:\n                form_data = json.loads(post_data.decode(&quot;utf-8&quot;))\n                result = create_work_order(form_data, credentials=credentials)\n                \n                if result.get(&quot;success&quot;):\n                    self.send_response(200)\n                else:\n                    self.send_response(400)\n                    \n                self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n                self.end_headers()\n                self.wfile.write(json.dumps(result).encode(&quot;utf-8&quot;))\n            except Exception as e:\n                self.send_response(500)\n                self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n                self.end_headers()\n                self.wfile.write(json.dumps({&quot;error&quot;: str(e)}).encode(&quot;utf-8&quot;))\n            return\n\n        # Serve API: Clear Audit Logs\n        if self.path == &quot;/api/trace/clear&quot;:\n            self.send_response(200)\n            self.send_header(&quot;Content-Type&quot;, &quot;application/json&quot;)\n            self.end_headers()\n            with open(config.TRACE_LOG_PATH, &#x27;w&#x27;, encoding=&#x27;utf-8&#x27;) as f:\n                json.dump([], f)\n            self.wfile.write(json.dumps({&quot;success&quot;: True}).encode(&quot;utf-8&quot;))\n            return\n\n        self.send_response(404)\n        self.end_headers()\n\ndef run(port=config.PORT):\n    server_address = (&#x27;&#x27;, port)\n    httpd = HTTPServer(server_address, ChatbotHTTPHandler)\n    print(f&quot;\\n==========================================&quot;)\n    print(f&quot;Maximo Virtual Assistant Web Server (v6)&quot;)\n    print(f&quot;Running locally at: http://localhost:{port}&quot;)\n    print(f&quot;==========================================\\n&quot;)\n    try:\n        httpd.serve_forever()\n    except KeyboardInterrupt:\n        print(&quot;\\nStopping Chatbot Server...&quot;)\n        httpd.server_close()\n\nif __name__ == &quot;__main__&quot;:\n    run()\n</pre>\n              </div>\n\n              <h3>2. NLP Engine: nlp_engine.py</h3>\n              <div class=\"ibm-code-block\" style=\"max-height: 350px; overflow-y: auto;\">\n                <div class=\"ibm-code-header\"><span>nlp_engine.py</span></div>\n                <pre># nlp_engine.py\nimport re\nimport os\nimport json\nimport math\n\n# Load configuration relative to this file\nCONFIG_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), &quot;intent_config.json&quot;)\n\ndef load_nlp_config():\n    try:\n        with open(CONFIG_PATH, &quot;r&quot;, encoding=&quot;utf-8&quot;) as f:\n            return json.load(f)\n    except Exception as e:\n        print(f&quot;Error loading NLP config: {e}&quot;)\n        return {\n            &quot;confidence_threshold&quot;: 0.55,\n            &quot;spell_corrections&quot;: {},\n            &quot;synonyms&quot;: {},\n            &quot;intents&quot;: {}\n        }\n\nCONFIG = load_nlp_config()\nTHRESHOLD = CONFIG.get(&quot;confidence_threshold&quot;, 0.55)\n\n# Stop words to prevent magnitude distortion from noise tokens\nSTOP_WORDS = {&quot;me&quot;, &quot;please&quot;, &quot;a&quot;, &quot;for&quot;, &quot;the&quot;, &quot;could&quot;, &quot;you&quot;, &quot;of&quot;, &quot;my&quot;, &quot;i&quot;, &quot;to&quot;, &quot;as&quot;, &quot;is&quot;, &quot;about&quot;, &quot;with&quot;, &quot;show&quot;}\n\n# Fields list for normalization\nFIELDS_LIST = [\n    &quot;status&quot;, &quot;description&quot;, &quot;summary&quot;, &quot;details&quot;, &quot;longdescription&quot;, &quot;long description&quot;,\n    &quot;assetnum&quot;, &quot;asset number&quot;, &quot;asset&quot;, &quot;location&quot;, &quot;siteid&quot;, &quot;site id&quot;, &quot;site&quot;,\n    &quot;reportedpriority&quot;, &quot;reported priority&quot;, &quot;internalpriority&quot;, &quot;internal priority&quot;,\n    &quot;wopriority&quot;, &quot;wo priority&quot;, &quot;priority&quot;, &quot;affectedperson&quot;, &quot;affected person&quot;, &quot;affected&quot;,\n    &quot;reportedby&quot;, &quot;reported by&quot;, &quot;reporter&quot;, &quot;ownergroup&quot;, &quot;owner group&quot;, &quot;owner&quot;,\n    &quot;emailaddress&quot;, &quot;email&quot;, &quot;phone&quot;, &quot;classification&quot;, &quot;classstructureid&quot;, &quot;worktype&quot;,\n    &quot;work type&quot;, &quot;target start&quot;, &quot;targstartdate&quot;, &quot;target finish&quot;, &quot;target completion&quot;, &quot;targcompdate&quot;\n]\n\ndef levenshtein_distance(s1, s2):\n    if len(s1) &lt; len(s2):\n        return levenshtein_distance(s2, s1)\n    if len(s2) == 0:\n        return len(s1)\n\n    previous_row = range(len(s2) + 1)\n    for i, c1 in enumerate(s1):\n        current_row = [i + 1]\n        for j, c2 in enumerate(s2):\n            insertions = previous_row[j + 1] + 1\n            deletions = current_row[j] + 1\n            substitutions = previous_row[j] + (c1 != c2)\n            current_row.append(min(insertions, deletions, substitutions))\n        previous_row = current_row\n\n    return previous_row[-1]\n\ndef stem_word(word):\n    &quot;&quot;&quot;\n    Lightweight suffix-stripping stemmer to normalize tenses and plurals.\n    &quot;&quot;&quot;\n    if len(word) &lt;= 3:\n        return word\n    if word.endswith(&quot;ing&quot;):\n        return word[:-3]\n    if word.endswith(&quot;ed&quot;):\n        return word[:-2]\n    if word.endswith(&quot;es&quot;) and not word.endswith(&quot;ses&quot;):\n        return word[:-2]\n    if word.endswith(&quot;s&quot;) and not word.endswith(&quot;ss&quot;) and not word.endswith(&quot;us&quot;) and not word.endswith(&quot;is&quot;):\n        return word[:-1]\n    return word\n\ndef preprocess_text(text):\n    if not text:\n        return &quot;&quot;\n    text = text.lower().strip()\n    text = re.sub(r&#x27;[^\\w\\s]&#x27;, &#x27; &#x27;, text)\n    text = re.sub(r&#x27;\\s+&#x27;, &#x27; &#x27;, text).strip()\n    return text\n\ndef apply_fuzzy_matching(tokens, spell_corrections):\n    corrected_tokens = []\n    vocabulary = set(spell_corrections.values())\n    for intent_list in CONFIG.get(&quot;intents&quot;, {}).values():\n        for phrase in intent_list:\n            vocabulary.update(phrase.split())\n    vocabulary.update(FIELDS_LIST)\n    vocabulary.update([&quot;wo&quot;, &quot;sr&quot;, &quot;asset&quot;, &quot;id&quot;, &quot;field&quot;, &quot;value&quot;, &quot;to&quot;, &quot;for&quot;])\n\n    for token in tokens:\n        if token in spell_corrections:\n            corrected_tokens.append(spell_corrections[token])\n            continue\n        if token in vocabulary or token.isdigit():\n            corrected_tokens.append(token)\n            continue\n        best_match = token\n        min_dist = 2\n        if len(token) &gt; 3:\n            for vocab_word in vocabulary:\n                if abs(len(token) - len(vocab_word)) &lt;= min_dist:\n                    dist = levenshtein_distance(token, vocab_word)\n                    if dist &lt; min_dist:\n                        min_dist = dist\n                        best_match = vocab_word\n        corrected_tokens.append(best_match)\n    return corrected_tokens\n\ndef apply_synonym_mapping(text, synonyms):\n    sorted_synonyms = sorted(synonyms.items(), key=lambda x: len(x[0]), reverse=True)\n    for synonym, root in sorted_synonyms:\n        pattern = r&#x27;\\b&#x27; + re.escape(synonym) + r&#x27;\\b&#x27;\n        text = re.sub(pattern, root, text)\n    return text\n\ndef normalize_entities(text):\n    # 1. Normalize IDs\n    text = re.sub(r&#x27;\\b(sr|wo|asset)\\s+\\d+\\b&#x27;, r&#x27;\\1 id&#x27;, text, flags=re.IGNORECASE)\n    text = re.sub(r&#x27;\\b\\d{3,}\\b&#x27;, &#x27;id&#x27;, text)\n    \n    # 2. Normalize fields\n    for field in FIELDS_LIST:\n        pattern = r&#x27;\\b&#x27; + re.escape(field) + r&#x27;\\b&#x27;\n        text = re.sub(pattern, &#x27;field&#x27;, text, flags=re.IGNORECASE)\n\n    # 3. Normalize values\n    text = re.sub(r&#x27;\\b(to|as|=)\\s+.+$&#x27;, r&#x27;\\1 value&#x27;, text, flags=re.IGNORECASE)\n    return text\n\n# Check sync and load scikit-learn model\nMODEL_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), &quot;intent_classifier.pkl&quot;)\n\ndef check_sync_and_load():\n    # If the user copied a pre-trained file, don&#x27;t auto-retrain if intent_classifier.pkl exists\n    retrain = False\n    if not os.path.exists(MODEL_PATH):\n        retrain = True\n    else:\n        # Only check sync if intent_config.json is modified AND the user hasn&#x27;t copied a larger pre-trained model (size &gt; 30KB)\n        config_mtime = os.path.getmtime(CONFIG_PATH)\n        model_mtime = os.path.getmtime(MODEL_PATH)\n        model_size = os.path.getsize(MODEL_PATH)\n        if config_mtime &gt; model_mtime and model_size &lt; 30000:\n            retrain = True\n            \n    if retrain:\n        print(&quot;Model file missing or intent_config.json updated. Triggering training...&quot;)\n        try:\n            import train_nlp\n            train_nlp.train_and_save()\n        except Exception as e:\n            print(f&quot;Error during automatic model training: {e}&quot;)\n            \n    import pickle\n    with open(MODEL_PATH, &quot;rb&quot;) as f:\n        data = pickle.load(f)\n        \n    model = data[&quot;model&quot;]\n    if &quot;classes&quot; in data:\n        classes = data[&quot;classes&quot;]\n    else:\n        # Extract classes dynamically from scikit-learn pipeline named steps\n        classes = [str(c) for c in model.named_steps[&#x27;classifier&#x27;].classes_]\n        \n    return model, classes\n\n# Load model and classes\nPIPELINE, CLASSES = check_sync_and_load()\n\nIS_PRETRAINED = &quot;SEARCH_ASSET&quot; not in CLASSES\n\ndef preprocess_for_user_model(text):\n    import string\n    cleaned = text.lower()\n    punc = &quot;&quot;.join(c for c in string.punctuation if c not in (&#x27;#&#x27;, &#x27;/&#x27;, &#x27;-&#x27;))\n    cleaned = cleaned.translate(str.maketrans(&quot;&quot;, &quot;&quot;, punc))\n    cleaned = re.sub(r&#x27;\\s+&#x27;, &#x27; &#x27;, cleaned).strip()\n    \n    # User&#x27;s synonym dictionary mappings\n    synonyms = {\n        &#x27;sr&#x27;: &#x27;service request&#x27;,\n        &#x27;wo&#x27;: &#x27;work order&#x27;,\n        &#x27;ticket&#x27;: &#x27;service request&#x27;,\n        &#x27;incident&#x27;: &#x27;service request&#x27;,\n        &#x27;find&#x27;: &#x27;search&#x27;,\n        &#x27;locate&#x27;: &#x27;search&#x27;,\n        &#x27;fetch&#x27;: &#x27;search&#x27;,\n        &#x27;get&#x27;: &#x27;search&#x27;,\n        &#x27;open&#x27;: &#x27;search&#x27;\n    }\n    sorted_syn = sorted(synonyms.items(), key=lambda x: len(x[0]), reverse=True)\n    for syn, root in sorted_syn:\n        cleaned = re.sub(r&#x27;\\b&#x27; + re.escape(syn) + r&#x27;\\b&#x27;, root, cleaned)\n        \n    return re.sub(r&#x27;\\s+&#x27;, &#x27; &#x27;, cleaned).strip()\n\n# Translate user&#x27;s pre-trained model intent labels to internal chatbot routing labels\nINTENT_TRANSLATION = {\n    &quot;CREATE_SR&quot;: &quot;CREATE_SERVICE_REQUEST&quot;,\n    &quot;CREATE_WO&quot;: &quot;CREATE_WORK_ORDER&quot;,\n    &quot;SEARCH_SR&quot;: &quot;SEARCH_SERVICE_REQUEST&quot;,\n    &quot;SEARCH_WO&quot;: &quot;SEARCH_WORK_ORDER&quot;,\n    &quot;THANKS&quot;: &quot;THANK_YOU&quot;,\n    &quot;UPDATE_ASSET_FIELD&quot;: &quot;UPDATE_RECORD&quot;,\n    &quot;UPDATE_SR_FIELD&quot;: &quot;UPDATE_RECORD&quot;,\n    &quot;UPDATE_WO_FIELD&quot;: &quot;UPDATE_RECORD&quot;\n}\n\ndef classify_intent(message):\n    if IS_PRETRAINED:\n        preprocessed_query = preprocess_for_user_model(message)\n    else:\n        clean_msg = preprocess_text(message)\n        if not clean_msg:\n            return &quot;fallback&quot;, 0.0\n            \n        synonym_msg = apply_synonym_mapping(clean_msg, CONFIG.get(&quot;synonyms&quot;, {}))\n        tokens = synonym_msg.split()\n        corrected_tokens = apply_fuzzy_matching(tokens, CONFIG.get(&quot;spell_corrections&quot;, {}))\n        corrected_msg = &quot; &quot;.join(corrected_tokens)\n        normalized_msg = normalize_entities(corrected_msg)\n        query_tokens = [stem_word(t) for t in normalized_msg.split() if t not in STOP_WORDS]\n        preprocessed_query = &quot; &quot;.join(query_tokens)\n    \n    if not preprocessed_query.strip():\n        return &quot;fallback&quot;, 0.0\n        \n    try:\n        pred_intent = str(PIPELINE.predict([preprocessed_query])[0])\n        probs = PIPELINE.predict_proba([preprocessed_query])[0]\n        pred_idx = CLASSES.index(pred_intent)\n        confidence = float(probs[pred_idx])\n        \n        # Calculate vocabulary match ratio as penalty to suppress false positives on OOV inputs\n        vectorizer = PIPELINE.named_steps[&#x27;vectorizer&#x27;]\n        feature_names = vectorizer.get_feature_names_out()\n        \n        q_tokens = preprocessed_query.split()\n        known_count = sum(1 for t in q_tokens if t in feature_names)\n        if len(q_tokens) &gt; 0:\n            vocab_ratio = known_count / len(q_tokens)\n            confidence = confidence * vocab_ratio\n            \n        mapped_intent = INTENT_TRANSLATION.get(pred_intent, pred_intent)\n            \n        if confidence &lt; 0.35:\n            return &quot;fallback&quot;, round(confidence, 2)\n            \n        return mapped_intent, round(confidence, 2)\n    except Exception as e:\n        print(f&quot;Prediction error: {e}&quot;)\n        return &quot;fallback&quot;, 0.0\n</pre>\n              </div>\n\n              <h3>3. Dialogue Router: chat_engine.py</h3>\n              <div class=\"ibm-code-block\" style=\"max-height: 350px; overflow-y: auto;\">\n                <div class=\"ibm-code-header\"><span>chat_engine.py</span></div>\n                <pre># chat_engine.py\nimport re\nimport sys\nimport os\n\n# Allow importing from apis folder\nsys.path.append(os.path.dirname(os.path.abspath(__file__)))\n\nfrom apis.workorder import query_work_order, handle_wo_followup, update_work_order_field\nfrom apis.servicerequest import query_service_request, handle_sr_followup, update_service_request_field\nfrom apis.asset import query_asset, handle_asset_followup, update_asset_field\nfrom apis.user import create_user, add_security_group, remove_security_group\nimport nlp_engine\n\ndef handle_chat_message(message, context, credentials=None):\n    message = message.strip()\n    flow = context.get(&quot;flow&quot;)\n    \n    # Fields pattern definitions\n    fields_list = r&#x27;(?:status|description|summary|details|longdescription|long\\s+description|assetnum|asset\\s+number|asset|location|siteid|site\\s+id|site|reportedpriority|reported\\s+priority|internalpriority|internal\\s+priority|wopriority|wo\\s+priority|priority|affectedperson|affected\\s+person|affected|reportedby|reported\\s+by|reporter|ownergroup|owner\\s+group|owner|emailaddress|email|phone|classification|classstructureid|worktype|work\\s+type|target\\s+start|targstartdate|target\\s+finish|target\\s+completion|targcompdate)&#x27;\n\n    # 1. Intent Recognition via modular NLP Engine\n    intent, confidence = nlp_engine.classify_intent(message)\n    \n    # 2. Entity Extraction Decoupled from Intent matching (Extract IDs first for breakout check)\n    id_match = re.search(r&#x27;\\b\\d{3,}\\b&#x27;, message)\n    record_id = id_match.group(0) if id_match else None\n\n    # Pre-check for follow-up override (force fallback for simple attribute queries)\n    if flow in [&quot;followup_wo&quot;, &quot;followup_sr&quot;, &quot;followup_asset&quot;]:\n        has_field = re.search(rf&#x27;\\b({fields_list})\\b&#x27;, message, re.IGNORECASE)\n        has_action_verb = re.search(r&#x27;\\b(create|new|add|update|change|set|assign|search|find|locate|open|close|delete|help)\\b&#x27;, message, re.IGNORECASE)\n        if has_field and not record_id and not has_action_verb:\n            intent = &quot;fallback&quot;\n            confidence = 1.0\n\n    # Break out of active follow-up flows if a strong new intent is detected\n    is_main_intent = intent != &quot;fallback&quot;\n    if is_main_intent and flow in [&quot;followup_wo&quot;, &quot;followup_sr&quot;, &quot;followup_asset&quot;]:\n        is_explicit_cmd = intent in [&quot;CREATE_WORK_ORDER&quot;, &quot;CREATE_SERVICE_REQUEST&quot;, &quot;SEARCH_WORK_ORDER&quot;, &quot;SEARCH_SERVICE_REQUEST&quot;, &quot;SEARCH_ASSET&quot;]\n        if not is_explicit_cmd and confidence &lt; 0.70 and not record_id:\n            # Force fallback to keep active follow-up flow\n            intent = &quot;fallback&quot;\n            is_main_intent = False\n        else:\n            flow = None\n            context = {}\n\n\n    # Extract Record Type\n    record_type = None\n    if re.search(r&#x27;\\b(?:wo|workorder|work\\s+order|order)\\b&#x27;, message, re.IGNORECASE):\n        record_type = &quot;wo&quot;\n    elif re.search(r&#x27;\\b(?:sr|ticket|request|incident|service\\s+request)\\b&#x27;, message, re.IGNORECASE):\n        record_type = &quot;sr&quot;\n    elif re.search(r&#x27;\\b(?:asset)\\b&#x27;, message, re.IGNORECASE):\n        record_type = &quot;asset&quot;\n\n    # Dynamic record type overrides to fix cross-classification or low confidence fallback\n    if record_type and (intent == &quot;fallback&quot; or confidence &lt; 0.70):\n        is_update = re.search(r&#x27;\\b(update|change|set|modify|assign|close|closed|resolve|resolved|approve|approved|complete|completed|delegate)\\b&#x27;, message, re.IGNORECASE)\n        if is_update:\n            intent = &quot;UPDATE_RECORD&quot;\n            confidence = max(confidence, 0.90)\n            is_main_intent = True\n        else:\n            if record_type == &quot;asset&quot;:\n                intent = &quot;SEARCH_ASSET&quot;\n                confidence = max(confidence, 0.90)\n                is_main_intent = True\n            elif record_type == &quot;wo&quot; and intent not in [&quot;CREATE_WORK_ORDER&quot;, &quot;CREATE_SERVICE_REQUEST&quot;, &quot;SEARCH_WORK_ORDER&quot;]:\n                intent = &quot;SEARCH_WORK_ORDER&quot;\n                confidence = max(confidence, 0.90)\n                is_main_intent = True\n            elif record_type == &quot;sr&quot; and intent not in [&quot;CREATE_WORK_ORDER&quot;, &quot;CREATE_SERVICE_REQUEST&quot;, &quot;SEARCH_SERVICE_REQUEST&quot;]:\n                intent = &quot;SEARCH_SERVICE_REQUEST&quot;\n                confidence = max(confidence, 0.90)\n                is_main_intent = True\n\n    # Extract username, password, security group for security/user operations\n    oper_username = None\n    oper_password = None\n    oper_groupname = None\n\n    # Detailed parsing for: add security group &lt;GROUP&gt; to user &lt;USER&gt;\n    group_to_user_match = re.search(r&#x27;\\b(?:add|assign|map)\\s+(?:security\\s+)?group\\s+(\\w+)\\s+(?:to\\s+)?(?:user\\s+)?(\\w+)\\b&#x27;, message, re.IGNORECASE)\n    if group_to_user_match:\n        oper_groupname = group_to_user_match.group(1)\n        oper_username = group_to_user_match.group(2)\n\n    # Detailed parsing for: remove security group &lt;GROUP&gt; from user &lt;USER&gt;\n    group_from_user_match = re.search(r&#x27;\\b(?:remove|delete|revoke)\\s+(?:security\\s+)?group\\s+(\\w+)\\s+(?:from\\s+)?(?:user\\s+)?(\\w+)\\b&#x27;, message, re.IGNORECASE)\n    if group_from_user_match:\n        oper_groupname = group_from_user_match.group(1)\n        oper_username = group_from_user_match.group(2)\n\n    # Fallbacks\n    if not oper_groupname:\n        g_match = re.search(r&#x27;\\b(?:group|secgroup)\\s+(\\w+)\\b&#x27;, message, re.IGNORECASE)\n        if g_match:\n            oper_groupname = g_match.group(1)\n\n    if not oper_username:\n        u_match = re.search(r&#x27;\\b(?:user|register)\\s+(\\w+)\\b&#x27;, message, re.IGNORECASE)\n        if u_match:\n            matched_val = u_match.group(1)\n            if matched_val.upper() != (oper_groupname or &quot;&quot;).upper():\n                oper_username = matched_val\n\n    # Password extraction\n    pass_match = re.search(r&#x27;\\b(?:password|pass)\\s+(\\S+)\\b&#x27;, message, re.IGNORECASE)\n    if pass_match:\n        oper_password = pass_match.group(1)\n\n    # Extract Field Name\n    field_match = re.search(rf&#x27;\\b({fields_list})\\b&#x27;, message, re.IGNORECASE)\n    field_name = field_match.group(1).lower() if field_match else None\n    \n    # Extract Update Value\n    val_match = re.search(r&#x27;\\b(?:to|as|=)\\s+(.+)$&#x27;, message, re.IGNORECASE)\n    update_val = val_match.group(1).strip() if val_match else None\n\n    # Parse missing update values from NLU context if &#x27;to/as/=&#x27; was missing\n    if not update_val and record_id:\n        tail_match = re.search(rf&#x27;{record_id}\\s+(?:status|owner|{fields_list})?\\s*(\\w+)$&#x27;, message, re.IGNORECASE)\n        if tail_match:\n            update_val = tail_match.group(1).strip()\n\n    # Implied field detection based on keywords (pre-process before intent override)\n    if intent in [&quot;UPDATE_RECORD&quot;, &quot;CHANGE_STATUS&quot;, &quot;ASSIGN_OWNER&quot;]:\n        if not field_name:\n            if re.search(r&#x27;\\b(close|resolve|approve|complete|status)\\b&#x27;, message, re.IGNORECASE):\n                field_name = &quot;status&quot;\n            elif re.search(r&#x27;\\b(assign|owner|delegate)\\b&#x27;, message, re.IGNORECASE):\n                field_name = &quot;owner&quot;\n                \n        # Implied status values if status value is mentioned without &quot;to&quot; or &quot;as&quot;\n        if field_name == &quot;status&quot; and not update_val:\n            for word in [&quot;close&quot;, &quot;closed&quot;, &quot;resolve&quot;, &quot;resolved&quot;, &quot;approve&quot;, &quot;approved&quot;, &quot;complete&quot;, &quot;completed&quot;]:\n                if re.search(r&#x27;\\b&#x27; + re.escape(word) + r&#x27;\\b&#x27;, message, re.IGNORECASE):\n                    update_val = word.upper()\n                    if update_val == &quot;CLOSED&quot;:\n                        update_val = &quot;CLOSE&quot;\n                    elif update_val == &quot;RESOLVED&quot;:\n                        update_val = &quot;RESOLVED&quot;\n                    elif update_val == &quot;APPROVED&quot;:\n                        update_val = &quot;APPR&quot;\n                    elif update_val == &quot;COMPLETED&quot;:\n                        update_val = &quot;COMP&quot;\n                    break\n\n        # Implied owner values if owner value is mentioned without &quot;to&quot; or &quot;as&quot;\n        if field_name == &quot;owner&quot; and not update_val:\n            owner_match = re.search(r&#x27;\\b(?:assign|owner)\\s+(?:to\\s+)?(?:wo|sr|asset)?\\s*(?:\\d+)?\\s+(\\w+)\\b&#x27;, message, re.IGNORECASE)\n            if owner_match:\n                update_val = owner_match.group(1)\n\n    # Override UPDATE_RECORD to SEARCH if no update value is provided (handles pre-trained model bias)\n    if intent == &quot;UPDATE_RECORD&quot; and not update_val:\n        if record_type == &quot;wo&quot;:\n            intent = &quot;SEARCH_WORK_ORDER&quot;\n        elif record_type == &quot;sr&quot;:\n            intent = &quot;SEARCH_SERVICE_REQUEST&quot;\n        elif record_type == &quot;asset&quot;:\n            intent = &quot;SEARCH_ASSET&quot;\n    \n    # 3. Follow-up Details Flows (evaluated first if in flow and no clear main intent)\n    if flow == &quot;followup_wo&quot; and not is_main_intent:\n        res = handle_wo_followup(message, context)\n        res[&quot;intent&quot;] = &quot;followup_wo&quot;\n        res[&quot;confidence&quot;] = 1.0\n        return res\n        \n    if flow == &quot;followup_sr&quot; and not is_main_intent:\n        res = handle_sr_followup(message, context)\n        res[&quot;intent&quot;] = &quot;followup_sr&quot;\n        res[&quot;confidence&quot;] = 1.0\n        return res\n\n    if flow == &quot;followup_asset&quot; and not is_main_intent:\n        res = handle_asset_followup(message, context)\n        res[&quot;intent&quot;] = &quot;followup_asset&quot;\n        res[&quot;confidence&quot;] = 1.0\n        return res\n\n    # 4. Intent Routing\n    if intent == &quot;GREETING&quot;:\n        reply = &quot;Hello! I am your &lt;strong&gt;Maximo Virtual Assistant&lt;/strong&gt;. How can I help you today? 😊\\n\\nYou can ask me to:\\n- &lt;strong&gt;Find a Work Order&lt;/strong&gt; (e.g. &lt;em&gt;\\&quot;Find WO 1002\\&quot;&lt;/em&gt;)\\n- &lt;strong&gt;Find a Service Request&lt;/strong&gt; (e.g. &lt;em&gt;\\&quot;Find SR 1177\\&quot;&lt;/em&gt;)\\n- &lt;strong&gt;Create new records&lt;/strong&gt; (e.g. &lt;em&gt;\\&quot;New WO\\&quot;&lt;/em&gt; or &lt;em&gt;\\&quot;Create SR\\&quot;&lt;/em&gt;)\\n- &lt;strong&gt;Update fields&lt;/strong&gt; (e.g. &lt;em&gt;\\&quot;Change status of WO 1002 to CLOSE\\&quot;&lt;/em&gt;)&quot;\n        return {&quot;reply&quot;: reply, &quot;context&quot;: {}, &quot;intent&quot;: intent, &quot;confidence&quot;: confidence}\n\n    elif intent == &quot;THANK_YOU&quot;:\n        reply = &quot;You&#x27;re very welcome! Glad I could help. Let me know if there&#x27;s anything else you need. 👍&quot;\n        return {&quot;reply&quot;: reply, &quot;context&quot;: {}, &quot;intent&quot;: intent, &quot;confidence&quot;: confidence}\n\n    elif intent == &quot;GOODBYE&quot;:\n        reply = &quot;Goodbye! Have a wonderful day. Feel free to log back in whenever you need assistance with Maximo. 👋&quot;\n        return {&quot;reply&quot;: reply, &quot;context&quot;: {}, &quot;intent&quot;: intent, &quot;confidence&quot;: confidence}\n\n    elif intent == &quot;HELP&quot;:\n        reply = (\n            &quot;Here are the commands I can help you with:\\n\\n&quot;\n            &quot;1. &lt;strong&gt;Find WO [ID]&lt;/strong&gt; — Look up Work Order details and ask follow-ups\\n&quot;\n            &quot;2. &lt;strong&gt;Find SR [ID]&lt;/strong&gt; — Check Service Request status\\n&quot;\n            &quot;3. &lt;strong&gt;Create SR&lt;/strong&gt; — Guided Service Request creation\\n&quot;\n            &quot;4. &lt;strong&gt;Create WO&lt;/strong&gt; — Guided Work Order creation\\n&quot;\n            &quot;5. &lt;strong&gt;Update WO [ID] [field] to [value]&lt;/strong&gt; — Update WO attribute\\n&quot;\n            &quot;6. &lt;strong&gt;Update SR [ID] [field] to [value]&lt;/strong&gt; — Update SR attribute\\n&quot;\n            &quot;Just type a command or ask a question to get started.&quot;\n        )\n        return {&quot;reply&quot;: reply, &quot;context&quot;: {}, &quot;intent&quot;: intent, &quot;confidence&quot;: confidence}\n\n    elif intent == &quot;CREATE_SERVICE_REQUEST&quot;:\n        reply = &quot;Please fill in the details below. Only &lt;strong&gt;Summary&lt;/strong&gt; is required.&quot;\n        return {&quot;reply&quot;: reply, &quot;context&quot;: {}, &quot;showForm&quot;: &quot;create_sr&quot;, &quot;intent&quot;: intent, &quot;confidence&quot;: confidence}\n\n    elif intent == &quot;CREATE_WORK_ORDER&quot;:\n        reply = &quot;Please fill in the details below to create a new &lt;strong&gt;Work Order&lt;/strong&gt;.&quot;\n        return {&quot;reply&quot;: reply, &quot;context&quot;: {}, &quot;showForm&quot;: &quot;create_wo&quot;, &quot;intent&quot;: intent, &quot;confidence&quot;: confidence}\n\n    elif intent == &quot;SEARCH_SERVICE_REQUEST&quot;:\n        if record_id:\n            res = query_service_request(record_id, credentials=credentials)\n            res[&quot;intent&quot;] = intent\n            res[&quot;confidence&quot;] = confidence\n            return res\n        else:\n            reply = &quot;I detected you want to find a Service Request. Please provide the ID (e.g. &#x27;Search SR 1177&#x27;).&quot;\n            return {&quot;reply&quot;: reply, &quot;context&quot;: {}, &quot;intent&quot;: intent, &quot;confidence&quot;: confidence}\n\n    elif intent == &quot;SEARCH_WORK_ORDER&quot;:\n        if record_id:\n            res = query_work_order(record_id, credentials=credentials)\n            res[&quot;intent&quot;] = intent\n            res[&quot;confidence&quot;] = confidence\n            return res\n        else:\n            reply = &quot;I detected you want to find a Work Order. Please provide the ID (e.g. &#x27;Search WO 1002&#x27;).&quot;\n            return {&quot;reply&quot;: reply, &quot;context&quot;: {}, &quot;intent&quot;: intent, &quot;confidence&quot;: confidence}\n\n    elif intent == &quot;SEARCH_ASSET&quot;:\n        search_query = None\n        if record_id:\n            search_query = record_id\n        else:\n            asset_text_match = re.search(r&#x27;\\basset\\s+(.+)$&#x27;, message, re.IGNORECASE)\n            if asset_text_match:\n                search_query = asset_text_match.group(1).strip()\n            else:\n                search_query = re.sub(r&#x27;\\b(find|search|query|locate|open|get|fetch|show)\\b&#x27;, &#x27;&#x27;, message, flags=re.IGNORECASE).strip()\n                \n        if search_query:\n            res = query_asset(search_query, credentials=credentials)\n            res[&quot;intent&quot;] = intent\n            res[&quot;confidence&quot;] = confidence\n            return res\n        else:\n            reply = &quot;I detected you want to find an Asset. Please provide the ID or description keyword (e.g. &#x27;Search Asset boiler&#x27;).&quot;\n            return {&quot;reply&quot;: reply, &quot;context&quot;: {}, &quot;intent&quot;: intent, &quot;confidence&quot;: confidence}\n\n    elif intent in [&quot;UPDATE_RECORD&quot;, &quot;CHANGE_STATUS&quot;, &quot;ASSIGN_OWNER&quot;]:\n        \n        # Route depending on extracted record type (wo/sr/asset)\n        if record_id and field_name and update_val:\n            if record_type == &quot;wo&quot;:\n                res = update_work_order_field(record_id, field_name, update_val, credentials=credentials)\n            elif record_type == &quot;asset&quot;:\n                res = update_asset_field(record_id, field_name, update_val, credentials=credentials)\n            else:\n                res = update_service_request_field(record_id, field_name, update_val, credentials=credentials)\n            res[&quot;intent&quot;] = intent\n            res[&quot;confidence&quot;] = confidence\n            return res\n        else:\n            reply = &quot;I detected you want to update a record. Please use format: &lt;strong&gt;Update [WO/SR/Asset] [ID] [field] to [value]&lt;/strong&gt;.&quot;\n            return {&quot;reply&quot;: reply, &quot;context&quot;: {}, &quot;intent&quot;: intent, &quot;confidence&quot;: confidence}\n\n    elif intent == &quot;CREATE_USER&quot;:\n        if oper_username:\n            pwd = oper_password or &quot;MaximoUser2026!&quot;\n            res = create_user(oper_username, pwd, credentials=credentials)\n            res[&quot;intent&quot;] = intent\n            res[&quot;confidence&quot;] = confidence\n            return res\n        else:\n            reply = &quot;I detected you want to create a user. Please specify the username (e.g. &lt;em&gt;\\&quot;create user John\\&quot;&lt;/em&gt;).&quot;\n            return {&quot;reply&quot;: reply, &quot;context&quot;: {}, &quot;intent&quot;: intent, &quot;confidence&quot;: confidence}\n\n    elif intent == &quot;ADD_SECURITYGROUP_TO_USER&quot;:\n        if oper_username and oper_groupname:\n            res = add_security_group(oper_username, oper_groupname, credentials=credentials)\n            res[&quot;intent&quot;] = intent\n            res[&quot;confidence&quot;] = confidence\n            return res\n        else:\n            reply = &quot;I detected you want to add a security group to a user. Please specify both the group and username (e.g. &lt;em&gt;\\&quot;add security group MAXADMIN to user John\\&quot;&lt;/em&gt;).&quot;\n            return {&quot;reply&quot;: reply, &quot;context&quot;: {}, &quot;intent&quot;: intent, &quot;confidence&quot;: confidence}\n\n    elif intent == &quot;REMOVE_SECURITYGROUP_FROM_USER&quot;:\n        if oper_username and oper_groupname:\n            res = remove_security_group(oper_username, oper_groupname, credentials=credentials)\n            res[&quot;intent&quot;] = intent\n            res[&quot;confidence&quot;] = confidence\n            return res\n        else:\n            reply = &quot;I detected you want to remove a security group from a user. Please specify both the group and username (e.g. &lt;em&gt;\\&quot;remove security group MAXADMIN from user John\\&quot;&lt;/em&gt;).&quot;\n            return {&quot;reply&quot;: reply, &quot;context&quot;: {}, &quot;intent&quot;: intent, &quot;confidence&quot;: confidence}\n\n\n\n    # Low confidence or unknown intent -&gt; Clarification\n    reply = (\n        &quot;I&#x27;m not completely sure I understood that query.\\n\\n&quot;\n        &quot;Did you mean to:\\n&quot;\n        &quot;- &lt;strong&gt;Search Service Request&lt;/strong&gt; (e.g., &#x27;Find SR 1177&#x27;)\\n&quot;\n        &quot;- &lt;strong&gt;Search Work Order&lt;/strong&gt; (e.g., &#x27;Find WO 1002&#x27;)\\n&quot;\n        &quot;- &lt;strong&gt;Search Asset&lt;/strong&gt; (e.g., &#x27;Find Asset 11300&#x27; or &#x27;Search Asset boiler&#x27;)\\n&quot;\n        &quot;- &lt;strong&gt;Create Service Request&lt;/strong&gt; (e.g., &#x27;New SR&#x27;)\\n\\n&quot;\n        &quot;Please clarify your request.&quot;\n    )\n    return {&quot;reply&quot;: reply, &quot;context&quot;: {}, &quot;intent&quot;: &quot;fallback&quot;, &quot;confidence&quot;: confidence}\n</pre>\n              </div>\n\n              <h3>4. REST Client: maximo_client.py</h3>\n              <div class=\"ibm-code-block\" style=\"max-height: 300px; overflow-y: auto;\">\n                <div class=\"ibm-code-header\"><span>maximo_client.py</span></div>\n                <pre># maximo_client.py\nimport os\nimport json\nimport base64\nimport urllib.request\nimport urllib.error\nfrom datetime import datetime\nimport config\n\n# Ensure trace log directory exists\nos.makedirs(os.path.dirname(config.TRACE_LOG_PATH), exist_ok=True)\nif not os.path.exists(config.TRACE_LOG_PATH):\n    with open(config.TRACE_LOG_PATH, &#x27;w&#x27;, encoding=&#x27;utf-8&#x27;) as f:\n        json.dump([], f)\n\ndef log_to_trace(action, action_label, details):\n    try:\n        with open(config.TRACE_LOG_PATH, &#x27;r+&#x27;, encoding=&#x27;utf-8&#x27;) as f:\n            logs = json.load(f)\n            logs.insert(0, {\n                &quot;timestamp&quot;: datetime.now().isoformat(),\n                &quot;action&quot;: action,\n                &quot;action_label&quot;: action_label,\n                &quot;details&quot;: details\n            })\n            logs = logs[:50]  # Keep last 50 entries\n            f.seek(0)\n            json.dump(logs, f, indent=2)\n            f.truncate()\n    except Exception as e:\n        print(f&quot;Error writing to trace log: {e}&quot;)\n\ndef get_maximo_headers(credentials=None):\n    if not credentials:\n        return {\n            &quot;Accept&quot;: &quot;application/json&quot;,\n            &quot;Content-Type&quot;: &quot;application/json&quot;\n        }\n    user = credentials.get(&quot;user&quot;, &quot;&quot;)\n    password = credentials.get(&quot;pass&quot;, &quot;&quot;)\n    raw_auth = f&quot;{user}:{password}&quot;.encode(&quot;utf-8&quot;)\n    encoded_auth = base64.b64encode(raw_auth).decode(&quot;utf-8&quot;)\n    return {\n        &quot;Accept&quot;: &quot;application/json&quot;,\n        &quot;Content-Type&quot;: &quot;application/json&quot;,\n        &quot;maxauth&quot;: encoded_auth\n    }\n\ndef make_maximo_request(url, method=&quot;GET&quot;, data=None, credentials=None, extra_headers=None):\n    headers = get_maximo_headers(credentials)\n    # Merge any extra headers (e.g. x-method-override for PATCH)\n    if extra_headers:\n        headers.update(extra_headers)\n    req = urllib.request.Request(url, method=method)\n    for key, val in headers.items():\n        req.add_header(key, val)\n    \n    if data:\n        req.data = json.dumps(data).encode(&quot;utf-8&quot;)\n        \n    try:\n        with urllib.request.urlopen(req, timeout=10) as response:\n            res_headers = dict(response.info())\n            res_body = response.read().decode(&quot;utf-8&quot;)\n            return response.status, res_headers, res_body\n    except urllib.error.HTTPError as e:\n        res_body = e.read().decode(&quot;utf-8&quot;)\n        return e.code, dict(e.info()), res_body\n    except Exception as e:\n        if &quot;Unauthorized&quot; in str(e) or &quot;401&quot; in str(e):\n            return 401, {}, &quot;Unauthorized connection to Maximo instance.&quot;\n        return 500, {}, str(e)\n\ndef parse_maximo_error_base(body):\n    &quot;&quot;&quot;\n    Parses raw Maximo OSLC JSON responses to extract friendly messages and the offending attribute.\n    &quot;&quot;&quot;\n    try:\n        err_data = json.loads(body)\n        oslc_err = err_data.get(&quot;oslc:Error&quot;, {})\n        if not oslc_err and isinstance(err_data.get(&quot;Error&quot;), dict):\n            oslc_err = err_data.get(&quot;Error&quot;)\n            \n        message = oslc_err.get(&quot;oslc:message&quot;) or oslc_err.get(&quot;message&quot;) or body\n        attr = oslc_err.get(&quot;errorattrname&quot;) or &quot;&quot;\n        return message, attr\n    except Exception:\n        return body, &quot;&quot;\n</pre>\n              </div>\n\n              <h3>5. Config Utility: config.py</h3>\n              <div class=\"ibm-code-block\" style=\"max-height: 200px; overflow-y: auto;\">\n                <div class=\"ibm-code-header\"><span>config.py</span></div>\n                <pre># config.py\n# Configuration settings for Maximo Virtual Assistant\nimport os\nimport json\n\nCONFIG_FILE = &quot;d:\\\\AI\\\\connection_config\\\\maximo.json&quot;\nTRACE_LOG_PATH = &quot;d:\\\\AI\\\\logs\\\\maximo_trace.json&quot;\nPORT = 5001\n\ndef get_maximo_base_url():\n    if os.path.exists(CONFIG_FILE):\n        try:\n            with open(CONFIG_FILE, &quot;r&quot;, encoding=&quot;utf-8&quot;) as f:\n                data = json.load(f)\n                return data.get(&quot;MAXIMO_BASE_URL&quot;, &quot;http://localhost:9084/maximo&quot;)\n        except Exception as e:\n            print(f&quot;Error reading connection config: {e}&quot;)\n    return &quot;http://localhost:9084/maximo&quot;\n\n# Dynamically evaluated property\nMAXIMO_BASE_URL = get_maximo_base_url()\n</pre>\n              </div>\n\n              <h3>6. Session Store: session_store.py</h3>\n              <div class=\"ibm-code-block\" style=\"max-height: 200px; overflow-y: auto;\">\n                <div class=\"ibm-code-header\"><span>session_store.py</span></div>\n                <pre># session_store.py\nimport uuid\nimport json\nimport os\n\nSESSION_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), &quot;sessions_db.json&quot;)\n\ndef _load_sessions():\n    if not os.path.exists(SESSION_FILE):\n        return {}\n    try:\n        with open(SESSION_FILE, &quot;r&quot;, encoding=&quot;utf-8&quot;) as f:\n            return json.load(f)\n    except Exception:\n        return {}\n\ndef _save_sessions(sessions):\n    try:\n        with open(SESSION_FILE, &quot;w&quot;, encoding=&quot;utf-8&quot;) as f:\n            json.dump(sessions, f, indent=2)\n    except Exception as e:\n        print(f&quot;Error saving sessions: {e}&quot;)\n\ndef create_session(username, password):\n    sessions = _load_sessions()\n    session_id = str(uuid.uuid4())\n    sessions[session_id] = {\n        &quot;user&quot;: username,\n        &quot;pass&quot;: password\n    }\n    _save_sessions(sessions)\n    return session_id\n\ndef get_session(session_id):\n    if not session_id:\n        return None\n    sessions = _load_sessions()\n    return sessions.get(session_id)\n\ndef delete_session(session_id):\n    sessions = _load_sessions()\n    if session_id in sessions:\n        del sessions[session_id]\n        _save_sessions(sessions)\n        return True\n    return False\n</pre>\n              </div>\n\n              <h2>API Integrations (apis/ directory)</h2>\n\n              <h3>7. Asset Integration: apis/asset.py</h3>\n              <div class=\"ibm-code-block\" style=\"max-height: 300px; overflow-y: auto;\">\n                <div class=\"ibm-code-header\"><span>asset.py</span></div>\n                <pre># apis/asset.py\nimport json\nimport urllib.parse\nimport re\nimport config\nfrom maximo_client import make_maximo_request, log_to_trace, parse_maximo_error_base\n\ndef query_asset(search_query, credentials=None):\n    search_query = search_query.strip()\n    is_numeric_id = search_query.isdigit()\n    \n    # 1. Attempt exact match by asset number first if numeric\n    if is_numeric_id:\n        asset_url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapiasset?oslc.where=assetnum=%22{search_query}%22&amp;oslc.properties=*&quot;\n        status_code, headers, body = make_maximo_request(asset_url, &quot;GET&quot;, credentials=credentials)\n        \n        if status_code in [401, 403]:\n            return {&quot;reply&quot;: &quot;❌ &lt;strong&gt;Authorization Error&lt;/strong&gt;: Your Maximo user does not have permission to read Assets.&quot;, &quot;context&quot;: {}, &quot;status&quot;: status_code}\n            \n        if status_code == 200:\n            res_data = json.loads(body)\n            members = res_data.get(&quot;rdfs:member&quot;, [])\n            if members:\n                asset = members[0]\n                asset_num = asset.get(&quot;spi:assetnum&quot;)\n                reply = (\n                    f&quot;Here are the details for Asset &lt;strong&gt;#{asset_num}&lt;/strong&gt;.\\n\\n&quot;\n                    f&quot;You can ask me follow-up questions about any specific field (e.g. &lt;em&gt;\\&quot;what is the status?\\&quot;&lt;/em&gt; or &lt;em&gt;\\&quot;what is the location?\\&quot;&lt;/em&gt;).&quot;\n                )\n                data_card = {\n                    &quot;title&quot;: f&quot;Asset #{asset_num}&quot;,\n                    &quot;fields&quot;: {\n                        &quot;Asset ID&quot;: asset.get(&quot;spi:assetnum&quot;),\n                        &quot;Status&quot;: asset.get(&quot;spi:status&quot;),\n                        &quot;Description&quot;: asset.get(&quot;spi:description&quot;),\n                        &quot;Manufacturer&quot;: asset.get(&quot;spi:manufacturer&quot;) or &quot;N/A&quot;,\n                        &quot;Location&quot;: asset.get(&quot;spi:location&quot;) or &quot;N/A&quot;\n                    }\n                }\n                new_context = {\n                    &quot;flow&quot;: &quot;followup_asset&quot;,\n                    &quot;asset_data&quot;: asset\n                }\n                log_to_trace(&quot;query_asset&quot;, &quot;Queried Asset&quot;, f&quot;Asset Num: {asset_num} | Status: {asset.get(&#x27;spi:status&#x27;)}&quot;)\n                return {&quot;reply&quot;: reply, &quot;context&quot;: new_context, &quot;dataCard&quot;: data_card}\n\n    # 2. Description Similarity Search using case-insensitive wildcard\n    encoded_search = urllib.parse.quote(f&quot;%~{search_query}%&quot;)\n    desc_url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapiasset?oslc.where=description=%22{encoded_search}%22&amp;oslc.properties=*&quot;\n    status_code, headers, body = make_maximo_request(desc_url, &quot;GET&quot;, credentials=credentials)\n    \n    if status_code in [401, 403]:\n        return {&quot;reply&quot;: &quot;❌ &lt;strong&gt;Authorization Error&lt;/strong&gt;: Your Maximo user does not have permission to read Assets.&quot;, &quot;context&quot;: {}, &quot;status&quot;: status_code}\n        \n    if status_code == 200:\n        res_data = json.loads(body)\n        members = res_data.get(&quot;rdfs:member&quot;, [])\n        \n        if not members:\n            reply = f&quot;No assets matching description &lt;strong&gt;\\&quot;{search_query}\\&quot;&lt;/strong&gt; were found in Maximo.&quot;\n            log_to_trace(&quot;query_asset_failed&quot;, &quot;Queried Asset by Description (Failed)&quot;, f&quot;No matches for: {search_query}&quot;)\n            return {&quot;reply&quot;: reply, &quot;context&quot;: {}}\n            \n        elif len(members) == 1:\n            asset = members[0]\n            asset_num = asset.get(&quot;spi:assetnum&quot;)\n            reply = (\n                f&quot;I found one asset matching &lt;strong&gt;\\&quot;{search_query}\\&quot;&lt;/strong&gt;. Here are the details for Asset &lt;strong&gt;#{asset_num}&lt;/strong&gt;:\\n\\n&quot;\n                f&quot;You can ask me follow-up questions about any specific field (e.g. &lt;em&gt;\\&quot;what is the status?\\&quot;&lt;/em&gt;).&quot;\n            )\n            data_card = {\n                &quot;title&quot;: f&quot;Asset #{asset_num}&quot;,\n                &quot;fields&quot;: {\n                    &quot;Asset ID&quot;: asset.get(&quot;spi:assetnum&quot;),\n                    &quot;Status&quot;: asset.get(&quot;spi:status&quot;),\n                    &quot;Description&quot;: asset.get(&quot;spi:description&quot;),\n                    &quot;Manufacturer&quot;: asset.get(&quot;spi:manufacturer&quot;) or &quot;N/A&quot;,\n                    &quot;Location&quot;: asset.get(&quot;spi:location&quot;) or &quot;N/A&quot;\n                }\n            }\n            new_context = {\n                &quot;flow&quot;: &quot;followup_asset&quot;,\n                &quot;asset_data&quot;: asset\n            }\n            log_to_trace(&quot;query_asset&quot;, &quot;Queried Asset by Description&quot;, f&quot;Asset Num: {asset_num} | Matches description: {search_query}&quot;)\n            return {&quot;reply&quot;: reply, &quot;context&quot;: new_context, &quot;dataCard&quot;: data_card}\n            \n        else:\n            # Multiple matches found\n            reply = f&quot;I found &lt;strong&gt;{len(members)}&lt;/strong&gt; assets matching description &lt;strong&gt;\\&quot;{search_query}\\&quot;&lt;/strong&gt;. Please select one:\\n\\n&quot;\n            # List first 10 matches\n            for m in members[:10]:\n                asset_num = m.get(&quot;spi:assetnum&quot;)\n                desc = m.get(&quot;spi:description&quot;) or &quot;No description&quot;\n                reply += f&quot;- 🔧 &lt;strong&gt;Asset {asset_num}&lt;/strong&gt;: {desc}\\n&quot;\n                \n            if len(members) &gt; 10:\n                reply += f&quot;\\n*Showing 10 of {len(members)} matches. Please refine your search keyword if needed.*&quot;\n                \n            reply += &quot;\\n\\nTry typing **Find Asset [ID]** to view specific details.&quot;\n            log_to_trace(&quot;query_asset_multiple&quot;, &quot;Queried Asset (Multiple Matches)&quot;, f&quot;Found {len(members)} matches for: {search_query}&quot;)\n            return {&quot;reply&quot;: reply, &quot;context&quot;: {}}\n            \n    reply = f&quot;Sorry, I couldn&#x27;t query Assets right now. Please try again later.&quot;\n    return {&quot;reply&quot;: reply, &quot;context&quot;: {}}\n\ndef update_asset_field(asset_num, field_name, value, credentials=None):\n    # 1. Fetch Asset to get URI\n    asset_url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapiasset?oslc.where=assetnum=%22{asset_num}%22&amp;oslc.properties=*&quot;\n    status_code, headers, body = make_maximo_request(asset_url, &quot;GET&quot;, credentials=credentials)\n    \n    if status_code in [401, 403]:\n        return {&quot;reply&quot;: &quot;❌ &lt;strong&gt;Authorization Error&lt;/strong&gt;: You do not have permission to modify Assets.&quot;, &quot;context&quot;: {}, &quot;status&quot;: status_code}\n        \n    if status_code != 200:\n        return {&quot;reply&quot;: f&quot;Sorry, I couldn&#x27;t access Asset #{asset_num} to perform the update.&quot;, &quot;context&quot;: {}}\n        \n    res_data = json.loads(body)\n    members = res_data.get(&quot;rdfs:member&quot;, [])\n    if not members:\n        return {&quot;reply&quot;: f&quot;Asset &lt;strong&gt;#{asset_num}&lt;/strong&gt; was not found in Maximo.&quot;, &quot;context&quot;: {}}\n        \n    asset = members[0]\n    member_uri = asset.get(&quot;rdf:about&quot;)\n    if not member_uri:\n        return {&quot;reply&quot;: &quot;Error: Could not locate the update endpoint for this Asset.&quot;, &quot;context&quot;: {}}\n        \n    # Rewrite localhost URIs\n    member_uri = member_uri.replace(&quot;http://localhost/maximo&quot;, config.get_maximo_base_url())\n    \n    # 2. Map standard fields to OSLC attributes\n    mappings = {\n        &quot;status&quot;: &quot;status&quot;,\n        &quot;description&quot;: &quot;description&quot;,\n        &quot;summary&quot;: &quot;description&quot;,\n        &quot;location&quot;: &quot;location&quot;,\n        &quot;manufacturer&quot;: &quot;manufacturer&quot;,\n        &quot;site&quot;: &quot;siteid&quot;,\n        &quot;siteid&quot;: &quot;siteid&quot;,\n        &quot;site id&quot;: &quot;siteid&quot;\n    }\n    \n    mapped_field = mappings.get(field_name.lower(), field_name.lower())\n    oslc_key = f&quot;spi:{mapped_field}&quot;\n    \n    # Send PATCH update\n    payload = {oslc_key: value}\n    update_headers = {\n        &quot;x-method-override&quot;: &quot;PATCH&quot;,\n        &quot;properties&quot;: &quot;*&quot;\n    }\n    \n    sc, hd, bd = make_maximo_request(member_uri, &quot;POST&quot;, payload, credentials=credentials, extra_headers=update_headers)\n    \n    if sc in [401, 403]:\n        return {&quot;reply&quot;: &quot;❌ &lt;strong&gt;Authorization Error&lt;/strong&gt;: You do not have permission to modify this Asset attribute.&quot;, &quot;context&quot;: {}, &quot;status&quot;: sc}\n        \n    if sc in [200, 204]:\n        log_to_trace(&quot;update_asset&quot;, &quot;Updated Asset&quot;, f&quot;Asset Num: {asset_num} | {field_name} -&gt; {value}&quot;)\n        return {\n            &quot;reply&quot;: f&quot;✅ Asset &lt;strong&gt;#{asset_num}&lt;/strong&gt; has been updated successfully! Changed &lt;strong&gt;{field_name}&lt;/strong&gt; to: &lt;strong&gt;{value}&lt;/strong&gt;.&quot;,\n            &quot;context&quot;: {}\n        }\n    else:\n        raw_message, attr = parse_maximo_error_base(bd)\n        return {\n            &quot;reply&quot;: f&quot;⚠️ Failed to update Asset: {raw_message}&quot;,\n            &quot;context&quot;: {}\n        }\n\ndef handle_asset_followup(message, context):\n    asset_data = context.get(&quot;asset_data&quot;, {})\n    asset_num = asset_data.get(&quot;spi:assetnum&quot;) or asset_data.get(&quot;assetnum&quot;, &quot;Unknown&quot;)\n    msg_lower = message.lower()\n    \n    mappings = {\n        &quot;status&quot;: (&quot;status&quot;, &quot;Status&quot;),\n        &quot;location&quot;: (&quot;location&quot;, &quot;Location&quot;),\n        &quot;description&quot;: (&quot;description&quot;, &quot;Description&quot;),\n        &quot;detail&quot;: (&quot;description&quot;, &quot;Description&quot;),\n        &quot;summary&quot;: (&quot;description&quot;, &quot;Description&quot;),\n        &quot;manufacturer&quot;: (&quot;manufacturer&quot;, &quot;Manufacturer&quot;),\n        &quot;site&quot;: (&quot;siteid&quot;, &quot;Site ID&quot;)\n    }\n    \n    matched_field = None\n    for keyword, (field_key, label) in mappings.items():\n        if re.search(r&#x27;\\b&#x27; + re.escape(keyword) + r&#x27;\\b&#x27;, msg_lower):\n            matched_field = (field_key, label)\n            break\n            \n    if matched_field:\n        field_key, label = matched_field\n        val = asset_data.get(f&quot;spi:{field_key}&quot;) or asset_data.get(field_key)\n        desc_val = asset_data.get(f&quot;spi:{field_key}_description&quot;) or asset_data.get(f&quot;{field_key}_description&quot;)\n        \n        if val is not None and str(val).strip() != &quot;&quot;:\n            display_val = str(val)\n            if desc_val:\n                display_val = f&quot;{val} ({desc_val})&quot;\n            reply = f&quot;For Asset &lt;strong&gt;#{asset_num}&lt;/strong&gt;, the &lt;strong&gt;{label}&lt;/strong&gt; is: &lt;strong&gt;{display_val}&lt;/strong&gt;.&quot;\n        else:\n            reply = f&quot;For Asset &lt;strong&gt;#{asset_num}&lt;/strong&gt;, the &lt;strong&gt;{label}&lt;/strong&gt; field is currently empty in Maximo.&quot;\n        return {&quot;reply&quot;: reply, &quot;context&quot;: context}\n    else:\n        reply = (\n            f&quot;I couldn&#x27;t identify which specific field you&#x27;re asking about for Asset &lt;strong&gt;#{asset_num}&lt;/strong&gt;.\\n\\n&quot;\n            f&quot;You can ask about: **status, location, description, or manufacturer**.&quot;\n        )\n        return {&quot;reply&quot;: reply, &quot;context&quot;: context}\n\n</pre>\n              </div>\n\n              <h3>8. Work Order Integration: apis/workorder.py</h3>\n              <div class=\"ibm-code-block\" style=\"max-height: 300px; overflow-y: auto;\">\n                <div class=\"ibm-code-header\"><span>workorder.py</span></div>\n                <pre>import json\nimport config\nfrom maximo_client import make_maximo_request, log_to_trace, parse_maximo_error_base\n\ndef query_work_order(wo_num, credentials=None):\n    # Query Work Order in Maximo selecting ALL properties\n    wo_url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapiwo?oslc.where=wonum=%22{wo_num}%22&amp;oslc.properties=*&quot;\n    status_code, headers, body = make_maximo_request(wo_url, &quot;GET&quot;, credentials=credentials)\n    \n    if status_code == 401 or status_code == 403:\n        return {&quot;reply&quot;: &quot;❌ &lt;strong&gt;Authorization Error&lt;/strong&gt;: Your Maximo user does not have permission to read Work Orders.&quot;, &quot;context&quot;: {}, &quot;status&quot;: status_code}\n        \n    if status_code == 200:\n        res_data = json.loads(body)\n        members = res_data.get(&quot;rdfs:member&quot;, [])\n        if members:\n            wo = members[0]\n            reply = (\n                f&quot;Here are the details for Work Order &lt;strong&gt;#{wo_num}&lt;/strong&gt;.\\n\\n&quot;\n                f&quot;You can ask me follow-up questions about any specific field (e.g. &lt;em&gt;\\&quot;what is the location?\\&quot;&lt;/em&gt; or &lt;em&gt;\\&quot;what is the asset ID?\\&quot;&lt;/em&gt;).&quot;\n            )\n            \n            data_card = {\n                &quot;title&quot;: f&quot;Work Order #{wo_num}&quot;,\n                &quot;fields&quot;: {\n                    &quot;WONUM&quot;: wo.get(&quot;spi:wonum&quot;),\n                    &quot;Status&quot;: wo.get(&quot;spi:status&quot;),\n                    &quot;Description&quot;: wo.get(&quot;spi:description&quot;),\n                    &quot;Asset ID&quot;: wo.get(&quot;spi:assetnum&quot;),\n                    &quot;Location&quot;: wo.get(&quot;spi:location&quot;)\n                }\n            }\n            \n            new_context = {\n                &quot;flow&quot;: &quot;followup_wo&quot;,\n                &quot;wo_data&quot;: wo\n            }\n            \n            log_to_trace(&quot;query_wo&quot;, &quot;Queried Work Order&quot;, f&quot;WONUM: {wo_num} | Status: {wo.get(&#x27;spi:status&#x27;)}&quot;)\n            return {&quot;reply&quot;: reply, &quot;context&quot;: new_context, &quot;dataCard&quot;: data_card}\n        else:\n            reply = f&quot;Work Order &lt;strong&gt;#{wo_num}&lt;/strong&gt; was not found in Maximo.&quot;\n            log_to_trace(&quot;query_wo_failed&quot;, &quot;Queried Work Order (Failed)&quot;, f&quot;WONUM: {wo_num} not found&quot;)\n            return {&quot;reply&quot;: reply, &quot;context&quot;: {}}\n    else:\n        reply = f&quot;Sorry, I couldn&#x27;t retrieve Work Order #{wo_num} right now. Please try again later.&quot;\n        return {&quot;reply&quot;: reply, &quot;context&quot;: {}}\n\ndef handle_wo_followup(message, context):\n    wo_data = context.get(&quot;wo_data&quot;, {})\n    wonum = wo_data.get(&quot;spi:wonum&quot;) or wo_data.get(&quot;wonum&quot;, &quot;Unknown&quot;)\n    msg_lower = message.lower()\n    \n    # Field mapping dictionary\n    mappings = {\n        &quot;status&quot;: (&quot;status&quot;, &quot;Status&quot;),\n        &quot;location&quot;: (&quot;location&quot;, &quot;Location&quot;),\n        &quot;asset&quot;: (&quot;assetnum&quot;, &quot;Asset ID&quot;),\n        &quot;description&quot;: (&quot;description&quot;, &quot;Description&quot;),\n        &quot;detail&quot;: (&quot;description&quot;, &quot;Description&quot;),\n        &quot;summary&quot;: (&quot;description&quot;, &quot;Description&quot;),\n        &quot;priority&quot;: (&quot;wopriority&quot;, &quot;Priority&quot;),\n        &quot;start&quot;: (&quot;targstartdate&quot;, &quot;Target Start&quot;),\n        &quot;finish&quot;: (&quot;targcompdate&quot;, &quot;Target Finish&quot;),\n        &quot;end&quot;: (&quot;targcompdate&quot;, &quot;Target Finish&quot;),\n        &quot;report&quot;: (&quot;reportdate&quot;, &quot;Reported Date&quot;),\n        &quot;reporter&quot;: (&quot;reportedby&quot;, &quot;Reported By&quot;),\n        &quot;who&quot;: (&quot;reportedby&quot;, &quot;Reported By&quot;),\n        &quot;site&quot;: (&quot;siteid&quot;, &quot;Site ID&quot;),\n        &quot;org&quot;: (&quot;orgid&quot;, &quot;Organization ID&quot;),\n        &quot;work type&quot;: (&quot;worktype&quot;, &quot;Work Type&quot;),\n        &quot;type&quot;: (&quot;worktype&quot;, &quot;Work Type&quot;),\n        &quot;class&quot;: (&quot;woclass&quot;, &quot;Work Order Class&quot;)\n    }\n    \n    import re\n    matched_field = None\n    for keyword, (field_key, label) in mappings.items():\n        # Match word boundaries to prevent substring collisions (like &quot;update&quot; matching &quot;date&quot;)\n        if re.search(r&#x27;\\b&#x27; + re.escape(keyword) + r&#x27;\\b&#x27;, msg_lower):\n            matched_field = (field_key, label)\n            break\n            \n    if matched_field:\n        field_key, label = matched_field\n        val = wo_data.get(f&quot;spi:{field_key}&quot;) or wo_data.get(field_key)\n        desc_val = wo_data.get(f&quot;spi:{field_key}_description&quot;) or wo_data.get(f&quot;{field_key}_description&quot;)\n        \n        if val is not None and str(val).strip() != &quot;&quot;:\n            display_val = str(val)\n            if desc_val:\n                display_val = f&quot;{val} ({desc_val})&quot;\n            reply = f&quot;For Work Order &lt;strong&gt;#{wonum}&lt;/strong&gt;, the &lt;strong&gt;{label}&lt;/strong&gt; is: &lt;strong&gt;{display_val}&lt;/strong&gt;.&quot;\n        else:\n            reply = f&quot;For Work Order &lt;strong&gt;#{wonum}&lt;/strong&gt;, the &lt;strong&gt;{label}&lt;/strong&gt; field is currently not populated/empty in Maximo.&quot;\n        return {&quot;reply&quot;: reply, &quot;context&quot;: context}\n    else:\n        reply = (\n            f&quot;I couldn&#x27;t identify which specific field you&#x27;re asking about for Work Order &lt;strong&gt;#{wonum}&lt;/strong&gt;.\\n\\n&quot;\n            f&quot;You can ask about: **status, location, asset ID, description, priority, target start, target finish, or reporter**.&quot;\n        )\n        return {&quot;reply&quot;: reply, &quot;context&quot;: context}\n\ndef get_validation_suggestions(attribute, message, credentials=None):\n    suggestions = []\n    msg_lower = message.lower()\n    \n    # 1. Asset suggests active assets\n    if attribute == &quot;assetnum&quot; or &quot;asset&quot; in msg_lower:\n        url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapiasset?oslc.where=status=%22OPERATING%22&amp;oslc.properties=assetnum,description&amp;oslc.pageSize=5&quot;\n        sc, hd, body = make_maximo_request(url, &quot;GET&quot;, credentials=credentials)\n        if sc == 200:\n            members = json.loads(body).get(&quot;rdfs:member&quot;, [])\n            suggestions = [f&quot;**{m.get(&#x27;spi:assetnum&#x27;)}** ({m.get(&#x27;spi:description&#x27;, &#x27;No description&#x27;)})&quot; for m in members]\n        return &quot;assetnum&quot;, f&quot;❌ **Asset Error**: {message}\\n\\n💡 *Here are some valid operating assets you can try:* \\n&quot; + (&quot;\\n&quot;.join([f&quot;- {s}&quot; for s in suggestions]) if suggestions else &quot;- No operating assets found.&quot;)\n        \n    # 2. Location suggests active locations\n    elif attribute == &quot;location&quot; or &quot;location&quot; in msg_lower:\n        url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapilocation?oslc.where=status=%22ACTIVE%22&amp;oslc.properties=location,description&amp;oslc.pageSize=5&quot;\n        sc, hd, body = make_maximo_request(url, &quot;GET&quot;, credentials=credentials)\n        if sc == 200:\n            members = json.loads(body).get(&quot;rdfs:member&quot;, [])\n            suggestions = [f&quot;**{m.get(&#x27;spi:location&#x27;)}** ({m.get(&#x27;spi:description&#x27;, &#x27;No description&#x27;)})&quot; for m in members]\n        return &quot;location&quot;, f&quot;❌ **Location Error**: {message}\\n\\n💡 *Here are some valid active locations you can try:* \\n&quot; + (&quot;\\n&quot;.join([f&quot;- {s}&quot; for s in suggestions]) if suggestions else &quot;- No active locations found.&quot;)\n\n    return None, f&quot;❌ **Error**: {message}&quot;\n\ndef create_work_order(form_data, credentials=None):\n    description = form_data.get(&quot;description&quot;, &quot;&quot;).strip()\n    long_desc = form_data.get(&quot;longdescription&quot;, &quot;&quot;).strip() or None\n    assetnum = form_data.get(&quot;assetnum&quot;, &quot;&quot;).strip() or None\n    location = form_data.get(&quot;location&quot;, &quot;&quot;).strip() or None\n    site_id = form_data.get(&quot;siteid&quot;, &quot;&quot;).strip() or &quot;BEDFORD&quot;\n\n    if not description:\n        return {&quot;success&quot;: False, &quot;error&quot;: &quot;Description is required.&quot;}\n\n    wo_url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapiwo&quot;\n    payload = {\n        &quot;spi:description&quot;: description,\n        &quot;spi:siteid&quot;: site_id\n    }\n    \n    # Clean/omit empty attributes\n    if long_desc:\n        payload[&quot;spi:description_longdescription&quot;] = long_desc\n    if assetnum:\n        payload[&quot;spi:assetnum&quot;] = assetnum\n    if location:\n        payload[&quot;spi:location&quot;] = location\n\n    status_code, res_headers, body = make_maximo_request(wo_url, &quot;POST&quot;, payload, credentials=credentials)\n\n    if status_code == 401 or status_code == 403:\n        return {\n            &quot;success&quot;: False,\n            &quot;error&quot;: &quot;❌ &lt;strong&gt;Authorization Error&lt;/strong&gt;: Your Maximo user does not have permission to create Work Orders.&quot;,\n            &quot;error_field&quot;: None\n        }\n\n    if status_code in [200, 201]:\n        loc_header = res_headers.get(&quot;Location&quot;) or res_headers.get(&quot;location&quot;)\n        wonum = &quot;Unknown&quot;\n        if loc_header:\n            loc_rewritten = loc_header.replace(&quot;http://localhost/maximo&quot;, f&quot;{config.get_maximo_base_url()}&quot;)\n            sc, hd, bd = make_maximo_request(loc_rewritten, &quot;GET&quot;, credentials=credentials)\n            if sc == 200:\n                wo_data = json.loads(bd)\n                wonum = wo_data.get(&quot;spi:wonum&quot;, &quot;Created&quot;)\n\n        result = {\n            &quot;success&quot;: True,\n            &quot;wonum&quot;: wonum,\n            &quot;description&quot;: description,\n            &quot;assetnum&quot;: assetnum,\n            &quot;location&quot;: location,\n            &quot;siteid&quot;: site_id\n        }\n        log_to_trace(&quot;create_wo&quot;, &quot;Created Work Order&quot;, f&quot;WONUM: {wonum} | Description: {description}&quot;)\n        return result\n    else:\n        # Parse error attribute and retrieve active alternatives\n        raw_message, attr = parse_maximo_error_base(body)\n        error_field, friendly_error = get_validation_suggestions(attr, raw_message, credentials=credentials)\n        return {\n            &quot;success&quot;: False,\n            &quot;error&quot;: friendly_error,\n            &quot;error_field&quot;: error_field\n        }\n\ndef update_work_order_field(wo_num, field_name, value, credentials=None):\n    # 1. Fetch WO to get the member URI (rdf:about)\n    wo_url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapiwo?oslc.where=wonum=%22{wo_num}%22&amp;oslc.properties=*&quot;\n    status_code, headers, body = make_maximo_request(wo_url, &quot;GET&quot;, credentials=credentials)\n    \n    if status_code in [401, 403]:\n        return {&quot;reply&quot;: &quot;❌ &lt;strong&gt;Authorization Error&lt;/strong&gt;: You do not have permission to modify Work Orders.&quot;, &quot;context&quot;: {}, &quot;status&quot;: status_code}\n        \n    if status_code != 200:\n        return {&quot;reply&quot;: f&quot;Sorry, I couldn&#x27;t access Work Order #{wo_num} to perform the update.&quot;, &quot;context&quot;: {}}\n        \n    res_data = json.loads(body)\n    members = res_data.get(&quot;rdfs:member&quot;, [])\n    if not members:\n        return {&quot;reply&quot;: f&quot;Work Order &lt;strong&gt;#{wo_num}&lt;/strong&gt; was not found in Maximo.&quot;, &quot;context&quot;: {}}\n        \n    wo = members[0]\n    member_uri = wo.get(&quot;rdf:about&quot;)\n    if not member_uri:\n        return {&quot;reply&quot;: &quot;Error: Could not locate the update endpoint for this Work Order.&quot;, &quot;context&quot;: {}}\n        \n    # Rewrite localhost URIs\n    member_uri = member_uri.replace(&quot;http://localhost/maximo&quot;, config.get_maximo_base_url())\n    \n    # 2. Map standard fields to OSLC attributes\n    mappings = {\n        &quot;status&quot;: &quot;status&quot;,\n        &quot;description&quot;: &quot;description&quot;,\n        &quot;summary&quot;: &quot;description&quot;,\n        &quot;details&quot;: &quot;description_longdescription&quot;,\n        &quot;longdescription&quot;: &quot;description_longdescription&quot;,\n        &quot;long description&quot;: &quot;description_longdescription&quot;,\n        &quot;asset&quot;: &quot;assetnum&quot;,\n        &quot;assetnum&quot;: &quot;assetnum&quot;,\n        &quot;asset number&quot;: &quot;assetnum&quot;,\n        &quot;location&quot;: &quot;location&quot;,\n        &quot;site&quot;: &quot;siteid&quot;,\n        &quot;siteid&quot;: &quot;siteid&quot;,\n        &quot;site id&quot;: &quot;siteid&quot;,\n        &quot;priority&quot;: &quot;wopriority&quot;,\n        &quot;wo priority&quot;: &quot;wopriority&quot;,\n        &quot;work type&quot;: &quot;worktype&quot;,\n        &quot;worktype&quot;: &quot;worktype&quot;,\n        &quot;reporter&quot;: &quot;reportedby&quot;,\n        &quot;reportedby&quot;: &quot;reportedby&quot;,\n        &quot;reported by&quot;: &quot;reportedby&quot;,\n        &quot;owner&quot;: &quot;owner&quot;,\n        &quot;ownergroup&quot;: &quot;ownergroup&quot;,\n        &quot;owner group&quot;: &quot;ownergroup&quot;,\n        &quot;target start&quot;: &quot;targstartdate&quot;,\n        &quot;target finish&quot;: &quot;targcompdate&quot;,\n        &quot;target completion&quot;: &quot;targcompdate&quot;,\n    }\n    \n    mapped_field = mappings.get(field_name.lower(), field_name.lower())\n    oslc_key = f&quot;spi:{mapped_field}&quot;\n    \n    # Send PATCH update via x-method-override POST\n    payload = {oslc_key: value}\n    update_headers = {\n        &quot;x-method-override&quot;: &quot;PATCH&quot;,\n        &quot;properties&quot;: &quot;*&quot;\n    }\n    \n    sc, hd, bd = make_maximo_request(member_uri, &quot;POST&quot;, payload, credentials=credentials, extra_headers=update_headers)\n    \n    if sc in [401, 403]:\n        return {&quot;reply&quot;: &quot;❌ &lt;strong&gt;Authorization Error&lt;/strong&gt;: You do not have permission to modify this Work Order attribute.&quot;, &quot;context&quot;: {}, &quot;status&quot;: sc}\n        \n    if sc in [200, 204]:\n        log_to_trace(&quot;update_wo&quot;, &quot;Updated Work Order&quot;, f&quot;WONUM: {wo_num} | {field_name} -&gt; {value}&quot;)\n        return {\n            &quot;reply&quot;: f&quot;✅ Work Order &lt;strong&gt;#{wo_num}&lt;/strong&gt; has been updated successfully! Changed &lt;strong&gt;{field_name}&lt;/strong&gt; to: &lt;strong&gt;{value}&lt;/strong&gt;.&quot;,\n            &quot;context&quot;: {}\n        }\n    else:\n        raw_message, attr = parse_maximo_error_base(bd)\n        return {\n            &quot;reply&quot;: f&quot;⚠️ Failed to update Work Order: {raw_message}&quot;,\n            &quot;context&quot;: {}\n        }\n\n</pre>\n              </div>\n\n              <h3>9. Service Request Integration: apis/servicerequest.py</h3>\n              <div class=\"ibm-code-block\" style=\"max-height: 300px; overflow-y: auto;\">\n                <div class=\"ibm-code-header\"><span>servicerequest.py</span></div>\n                <pre>import json\nimport config\nfrom maximo_client import make_maximo_request, log_to_trace, parse_maximo_error_base\n\ndef query_service_request(sr_num, credentials=None):\n    sr_url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapisr?oslc.where=ticketid=%22{sr_num}%22&amp;oslc.properties=*&quot;\n    status_code, headers, body = make_maximo_request(sr_url, &quot;GET&quot;, credentials=credentials)\n    \n    if status_code == 401 or status_code == 403:\n        return {&quot;reply&quot;: &quot;❌ &lt;strong&gt;Authorization Error&lt;/strong&gt;: Your Maximo user does not have permission to read Service Requests.&quot;, &quot;context&quot;: {}, &quot;status&quot;: status_code}\n\n    if status_code == 200:\n        res_data = json.loads(body)\n        members = res_data.get(&quot;rdfs:member&quot;, [])\n        if members:\n            sr = members[0]\n            reply = (\n                f&quot;Here are the details for Service Request &lt;strong&gt;#{sr_num}&lt;/strong&gt;.\\n\\n&quot;\n                f&quot;You can ask me follow-up questions about any specific field (e.g. &lt;em&gt;\\&quot;what is the status?\\&quot;&lt;/em&gt; or &lt;em&gt;\\&quot;who reported it?\\&quot;&lt;/em&gt;).&quot;\n            )\n            data_card = {\n                &quot;title&quot;: f&quot;Service Request #{sr_num}&quot;,\n                &quot;fields&quot;: {\n                    &quot;Ticket ID&quot;: sr.get(&quot;spi:ticketid&quot;),\n                    &quot;Status&quot;: sr.get(&quot;spi:status&quot;),\n                    &quot;Description&quot;: sr.get(&quot;spi:description&quot;),\n                    &quot;Asset ID&quot;: sr.get(&quot;spi:assetnum&quot;),\n                    &quot;Location&quot;: sr.get(&quot;spi:location&quot;)\n                }\n            }\n            new_context = {\n                &quot;flow&quot;: &quot;followup_sr&quot;,\n                &quot;sr_data&quot;: sr\n            }\n            log_to_trace(&quot;query_sr&quot;, &quot;Queried Service Request&quot;, f&quot;Ticket ID: {sr_num} | Status: {sr.get(&#x27;spi:status&#x27;)}&quot;)\n            return {&quot;reply&quot;: reply, &quot;context&quot;: new_context, &quot;dataCard&quot;: data_card}\n        else:\n            reply = f&quot;Service Request &lt;strong&gt;#{sr_num}&lt;/strong&gt; was not found in Maximo.&quot;\n            log_to_trace(&quot;query_sr_failed&quot;, &quot;Queried Service Request (Failed)&quot;, f&quot;Ticket ID: {sr_num} not found&quot;)\n            return {&quot;reply&quot;: reply, &quot;context&quot;: {}}\n    else:\n        reply = f&quot;Sorry, I couldn&#x27;t retrieve Service Request #{sr_num} right now. Please try again later.&quot;\n        return {&quot;reply&quot;: reply, &quot;context&quot;: {}}\n\ndef handle_sr_followup(message, context):\n    sr_data = context.get(&quot;sr_data&quot;, {})\n    ticketid = sr_data.get(&quot;spi:ticketid&quot;) or sr_data.get(&quot;ticketid&quot;, &quot;Unknown&quot;)\n    msg_lower = message.lower()\n\n    mappings = {\n        &quot;status&quot;: (&quot;status&quot;, &quot;Status&quot;),\n        &quot;location&quot;: (&quot;location&quot;, &quot;Location&quot;),\n        &quot;asset&quot;: (&quot;assetnum&quot;, &quot;Asset ID&quot;),\n        &quot;description&quot;: (&quot;description&quot;, &quot;Description&quot;),\n        &quot;detail&quot;: (&quot;description&quot;, &quot;Description&quot;),\n        &quot;summary&quot;: (&quot;description&quot;, &quot;Description&quot;),\n        &quot;report date&quot;: (&quot;reportdate&quot;, &quot;Report Date&quot;),\n        &quot;date&quot;: (&quot;reportdate&quot;, &quot;Report Date&quot;),\n        &quot;when&quot;: (&quot;reportdate&quot;, &quot;Report Date&quot;),\n        &quot;reported by&quot;: (&quot;reportedby&quot;, &quot;Reported By&quot;),\n        &quot;reporter&quot;: (&quot;reportedby&quot;, &quot;Reported By&quot;),\n        &quot;who&quot;: (&quot;reportedby&quot;, &quot;Reported By&quot;),\n        &quot;affected person&quot;: (&quot;affectedperson&quot;, &quot;Affected Person&quot;),\n        &quot;affected&quot;: (&quot;affectedperson&quot;, &quot;Affected Person&quot;),\n        &quot;phone&quot;: (&quot;phone&quot;, &quot;Contact Phone&quot;),\n        &quot;email&quot;: (&quot;emailaddress&quot;, &quot;Contact Email&quot;),\n        &quot;priority&quot;: (&quot;reportedpriority&quot;, &quot;Priority&quot;),\n        &quot;class&quot;: (&quot;classstructureid&quot;, &quot;Classification ID&quot;),\n        &quot;site&quot;: (&quot;siteid&quot;, &quot;Site ID&quot;)\n    }\n\n    import re\n    matched_field = None\n    for keyword, (field_key, label) in mappings.items():\n        # Match word boundaries to prevent substring collisions (like &quot;update&quot; matching &quot;date&quot;)\n        if re.search(r&#x27;\\b&#x27; + re.escape(keyword) + r&#x27;\\b&#x27;, msg_lower):\n            matched_field = (field_key, label)\n            break\n\n    if matched_field:\n        field_key, label = matched_field\n        val = sr_data.get(f&quot;spi:{field_key}&quot;) or sr_data.get(field_key)\n        desc_val = sr_data.get(f&quot;spi:{field_key}_description&quot;) or sr_data.get(f&quot;{field_key}_description&quot;)\n\n        if val is not None and str(val).strip() != &quot;&quot;:\n            display_val = str(val)\n            if desc_val:\n                display_val = f&quot;{val} ({desc_val})&quot;\n            reply = f&quot;For Service Request &lt;strong&gt;#{ticketid}&lt;/strong&gt;, the &lt;strong&gt;{label}&lt;/strong&gt; is: &lt;strong&gt;{display_val}&lt;/strong&gt;.&quot;\n        else:\n            reply = f&quot;For Service Request &lt;strong&gt;#{ticketid}&lt;/strong&gt;, the &lt;strong&gt;{label}&lt;/strong&gt; field is currently not populated/empty in Maximo.&quot;\n        return {&quot;reply&quot;: reply, &quot;context&quot;: context}\n    else:\n        reply = (\n            f&quot;I couldn&#x27;t identify which specific field you&#x27;re asking about for Service Request &lt;strong&gt;#{ticketid}&lt;/strong&gt;.\\n\\n&quot;\n            f&quot;You can ask about: **status, location, asset ID, description, priority, reported by, report date, or affected person**.&quot;\n        )\n        return {&quot;reply&quot;: reply, &quot;context&quot;: context}\n\ndef get_validation_suggestions(attribute, message, credentials=None):\n    &quot;&quot;&quot;\n    Queries Maximo for active Operating/Active values to suggest to the user on validation errors.\n    &quot;&quot;&quot;\n    suggestions = []\n    msg_lower = message.lower()\n    \n    # 1. Asset suggests active assets\n    if attribute == &quot;assetnum&quot; or &quot;asset&quot; in msg_lower:\n        url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapiasset?oslc.where=status=%22OPERATING%22&amp;oslc.properties=assetnum,description&amp;oslc.pageSize=5&quot;\n        sc, hd, body = make_maximo_request(url, &quot;GET&quot;, credentials=credentials)\n        if sc == 200:\n            members = json.loads(body).get(&quot;rdfs:member&quot;, [])\n            suggestions = [f&quot;**{m.get(&#x27;spi:assetnum&#x27;)}** ({m.get(&#x27;spi:description&#x27;, &#x27;No description&#x27;)})&quot; for m in members]\n        return &quot;assetnum&quot;, f&quot;❌ **Asset Error**: {message}\\n\\n💡 *Here are some valid operating assets you can try:* \\n&quot; + (&quot;\\n&quot;.join([f&quot;- {s}&quot; for s in suggestions]) if suggestions else &quot;- No operating assets found.&quot;)\n        \n    # 2. Location suggests active locations\n    elif attribute == &quot;location&quot; or &quot;location&quot; in msg_lower:\n        url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapilocation?oslc.where=status=%22ACTIVE%22&amp;oslc.properties=location,description&amp;oslc.pageSize=5&quot;\n        sc, hd, body = make_maximo_request(url, &quot;GET&quot;, credentials=credentials)\n        if sc == 200:\n            members = json.loads(body).get(&quot;rdfs:member&quot;, [])\n            suggestions = [f&quot;**{m.get(&#x27;spi:location&#x27;)}** ({m.get(&#x27;spi:description&#x27;, &#x27;No description&#x27;)})&quot; for m in members]\n        return &quot;location&quot;, f&quot;❌ **Location Error**: {message}\\n\\n💡 *Here are some valid active locations you can try:* \\n&quot; + (&quot;\\n&quot;.join([f&quot;- {s}&quot; for s in suggestions]) if suggestions else &quot;- No active locations found.&quot;)\n        \n    # 3. Affected Person suggests active people\n    elif attribute == &quot;affectedperson&quot; or &quot;person&quot; in msg_lower or &quot;affected person&quot; in msg_lower:\n        url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapiperson?oslc.where=status=%22ACTIVE%22&amp;oslc.properties=personid,displayname&amp;oslc.pageSize=5&quot;\n        sc, hd, body = make_maximo_request(url, &quot;GET&quot;, credentials=credentials)\n        if sc == 200:\n            members = json.loads(body).get(&quot;rdfs:member&quot;, [])\n            suggestions = [f&quot;**{m.get(&#x27;spi:personid&#x27;)}** ({m.get(&#x27;spi:displayname&#x27;, &#x27;No display name&#x27;)})&quot; for m in members]\n        return &quot;affectedperson&quot;, f&quot;❌ **Affected Person Error**: {message}\\n\\n💡 *Here are some valid active persons you can try:* \\n&quot; + (&quot;\\n&quot;.join([f&quot;- {s}&quot; for s in suggestions]) if suggestions else &quot;- No active persons found.&quot;)\n\n    return None, f&quot;❌ **Error**: {message}&quot;\n\ndef create_service_request(form_data, credentials=None):\n    description = form_data.get(&quot;description&quot;, &quot;&quot;).strip()\n    long_desc = form_data.get(&quot;longdescription&quot;, &quot;&quot;).strip() or None\n    assetnum = form_data.get(&quot;assetnum&quot;, &quot;&quot;).strip() or None\n    location = form_data.get(&quot;location&quot;, &quot;&quot;).strip() or None\n    affectedperson = form_data.get(&quot;affectedperson&quot;, &quot;&quot;).strip() or None\n    site_id = form_data.get(&quot;siteid&quot;, &quot;&quot;).strip() or &quot;BEDFORD&quot;\n\n    if not description:\n        return {&quot;success&quot;: False, &quot;error&quot;: &quot;Description is required.&quot;}\n\n    sr_url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapisr&quot;\n    payload = {\n        &quot;spi:description&quot;: description,\n        &quot;spi:siteid&quot;: site_id\n    }\n    \n    # Clean/omit empty attributes\n    if long_desc:\n        payload[&quot;spi:description_longdescription&quot;] = long_desc\n        payload[&quot;spi:hasld&quot;] = True\n    if assetnum:\n        payload[&quot;spi:assetnum&quot;] = assetnum\n    if location:\n        payload[&quot;spi:location&quot;] = location\n    if affectedperson:\n        payload[&quot;spi:affectedperson&quot;] = affectedperson\n\n    status_code, res_headers, body = make_maximo_request(sr_url, &quot;POST&quot;, payload, credentials=credentials)\n\n    if status_code == 401 or status_code == 403:\n        return {\n            &quot;success&quot;: False,\n            &quot;error&quot;: &quot;❌ &lt;strong&gt;Authorization Error&lt;/strong&gt;: Your Maximo user does not have permission to create Service Requests.&quot;,\n            &quot;error_field&quot;: None\n        }\n\n    if status_code in [200, 201]:\n        loc_header = res_headers.get(&quot;Location&quot;) or res_headers.get(&quot;location&quot;)\n        ticket_id = &quot;Unknown&quot;\n        if loc_header:\n            loc_rewritten = loc_header.replace(&quot;http://localhost/maximo&quot;, f&quot;{config.get_maximo_base_url()}&quot;)\n            sc, hd, bd = make_maximo_request(loc_rewritten, &quot;GET&quot;, credentials=credentials)\n            if sc == 200:\n                sr_data = json.loads(bd)\n                ticket_id = sr_data.get(&quot;spi:ticketid&quot;, &quot;Created&quot;)\n\n        result = {\n            &quot;success&quot;: True,\n            &quot;ticket_id&quot;: ticket_id,\n            &quot;description&quot;: description,\n            &quot;assetnum&quot;: assetnum,\n            &quot;location&quot;: location,\n            &quot;affectedperson&quot;: affectedperson,\n            &quot;siteid&quot;: site_id\n        }\n        log_to_trace(&quot;create_sr&quot;, &quot;Created Service Request&quot;, f&quot;Ticket ID: {ticket_id} | Description: {description}&quot;)\n        return result\n    else:\n        # Parse error attribute and retrieve active alternatives\n        raw_message, attr = parse_maximo_error_base(body)\n        error_field, friendly_error = get_validation_suggestions(attr, raw_message, credentials=credentials)\n        return {\n            &quot;success&quot;: False,\n            &quot;error&quot;: friendly_error,\n            &quot;error_field&quot;: error_field\n        }\n\ndef update_service_request_field(sr_num, field_name, value, credentials=None):\n    # 1. Fetch SR to get the member URI (rdf:about)\n    sr_url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapisr?oslc.where=ticketid=%22{sr_num}%22&amp;oslc.properties=*&quot;\n    status_code, headers, body = make_maximo_request(sr_url, &quot;GET&quot;, credentials=credentials)\n    \n    if status_code in [401, 403]:\n        return {&quot;reply&quot;: &quot;❌ &lt;strong&gt;Authorization Error&lt;/strong&gt;: You do not have permission to modify Service Requests.&quot;, &quot;context&quot;: {}, &quot;status&quot;: status_code}\n        \n    if status_code != 200:\n        return {&quot;reply&quot;: f&quot;Sorry, I couldn&#x27;t access Service Request #{sr_num} to perform the update.&quot;, &quot;context&quot;: {}}\n        \n    res_data = json.loads(body)\n    members = res_data.get(&quot;rdfs:member&quot;, [])\n    if not members:\n        return {&quot;reply&quot;: f&quot;Service Request &lt;strong&gt;#{sr_num}&lt;/strong&gt; was not found in Maximo.&quot;, &quot;context&quot;: {}}\n        \n    sr = members[0]\n    member_uri = sr.get(&quot;rdf:about&quot;)\n    if not member_uri:\n        return {&quot;reply&quot;: &quot;Error: Could not locate the update endpoint for this Service Request.&quot;, &quot;context&quot;: {}}\n        \n    # Rewrite localhost URIs\n    member_uri = member_uri.replace(&quot;http://localhost/maximo&quot;, config.get_maximo_base_url())\n    \n    # 2. Map standard fields to OSLC attributes\n    mappings = {\n        &quot;status&quot;: &quot;status&quot;,\n        &quot;description&quot;: &quot;description&quot;,\n        &quot;summary&quot;: &quot;description&quot;,\n        &quot;details&quot;: &quot;description_longdescription&quot;,\n        &quot;longdescription&quot;: &quot;description_longdescription&quot;,\n        &quot;long description&quot;: &quot;description_longdescription&quot;,\n        &quot;asset&quot;: &quot;assetnum&quot;,\n        &quot;assetnum&quot;: &quot;assetnum&quot;,\n        &quot;asset number&quot;: &quot;assetnum&quot;,\n        &quot;location&quot;: &quot;location&quot;,\n        &quot;site&quot;: &quot;siteid&quot;,\n        &quot;siteid&quot;: &quot;siteid&quot;,\n        &quot;site id&quot;: &quot;siteid&quot;,\n        &quot;priority&quot;: &quot;reportedpriority&quot;,\n        &quot;reported priority&quot;: &quot;reportedpriority&quot;,\n        &quot;internal priority&quot;: &quot;internalpriority&quot;,\n        &quot;affected&quot;: &quot;affectedperson&quot;,\n        &quot;affectedperson&quot;: &quot;affectedperson&quot;,\n        &quot;affected person&quot;: &quot;affectedperson&quot;,\n        &quot;reporter&quot;: &quot;reportedby&quot;,\n        &quot;reportedby&quot;: &quot;reportedby&quot;,\n        &quot;reported by&quot;: &quot;reportedby&quot;,\n        &quot;owner&quot;: &quot;owner&quot;,\n        &quot;ownergroup&quot;: &quot;ownergroup&quot;,\n        &quot;owner group&quot;: &quot;ownergroup&quot;,\n        &quot;email&quot;: &quot;emailaddress&quot;,\n        &quot;emailaddress&quot;: &quot;emailaddress&quot;,\n        &quot;phone&quot;: &quot;phone&quot;,\n        &quot;classification&quot;: &quot;classstructureid&quot;,\n    }\n    \n    mapped_field = mappings.get(field_name.lower(), field_name.lower())\n    oslc_key = f&quot;spi:{mapped_field}&quot;\n    \n    # Send PATCH update via x-method-override POST\n    payload = {oslc_key: value}\n    update_headers = {\n        &quot;x-method-override&quot;: &quot;PATCH&quot;,\n        &quot;properties&quot;: &quot;*&quot;\n    }\n    \n    sc, hd, bd = make_maximo_request(member_uri, &quot;POST&quot;, payload, credentials=credentials, extra_headers=update_headers)\n    \n    if sc in [401, 403]:\n        return {&quot;reply&quot;: &quot;❌ &lt;strong&gt;Authorization Error&lt;/strong&gt;: You do not have permission to modify this Service Request attribute.&quot;, &quot;context&quot;: {}, &quot;status&quot;: sc}\n        \n    if sc in [200, 204]:\n        log_to_trace(&quot;update_sr&quot;, &quot;Updated Service Request&quot;, f&quot;Ticket ID: {sr_num} | {field_name} -&gt; {value}&quot;)\n        return {\n            &quot;reply&quot;: f&quot;✅ Service Request &lt;strong&gt;#{sr_num}&lt;/strong&gt; has been updated successfully! Changed &lt;strong&gt;{field_name}&lt;/strong&gt; to: &lt;strong&gt;{value}&lt;/strong&gt;.&quot;,\n            &quot;context&quot;: {}\n        }\n    else:\n        raw_message, attr = parse_maximo_error_base(bd)\n        return {\n            &quot;reply&quot;: f&quot;⚠️ Failed to update Service Request: {raw_message}&quot;,\n            &quot;context&quot;: {}\n        }\n\n</pre>\n              </div>\n\n              <h3>10. User Integration: apis/user.py</h3>\n              <div class=\"ibm-code-block\" style=\"max-height: 300px; overflow-y: auto;\">\n                <div class=\"ibm-code-header\"><span>user.py</span></div>\n                <pre>import json\nimport config\nfrom maximo_client import make_maximo_request, log_to_trace, parse_maximo_error_base\n\ndef create_user(username, password, email=None, credentials=None):\n    url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapiperuser&quot;\n    \n    payload = {\n        &quot;spi:personid&quot;: username.upper(),\n        &quot;spi:firstname&quot;: username,\n        &quot;spi:lastname&quot;: &quot;User&quot;,\n        &quot;spi:primaryemail&quot;: email or f&quot;{username.lower()}@example.com&quot;,\n        &quot;spi:maxuser&quot;: [\n            {\n                &quot;spi:userid&quot;: username.upper(),\n                &quot;spi:passwordinput&quot;: password,\n                &quot;spi:passwordcheck&quot;: password\n            }\n        ]\n    }\n    \n    status_code, headers, body = make_maximo_request(url, &quot;POST&quot;, payload, credentials=credentials)\n    \n    if status_code in [401, 403]:\n        return {&quot;reply&quot;: &quot;❌ &lt;strong&gt;Authorization Error&lt;/strong&gt;: You do not have permission to create users.&quot;, &quot;context&quot;: {}, &quot;status&quot;: status_code}\n        \n    if status_code in [200, 201, 204]:\n        log_to_trace(&quot;create_user&quot;, &quot;Created User&quot;, f&quot;USERID: {username.upper()}&quot;)\n        return {\n            &quot;reply&quot;: f&quot;✅ User &lt;strong&gt;{username.upper()}&lt;/strong&gt; has been created successfully with password: &lt;code&gt;{password}&lt;/code&gt;.&quot;,\n            &quot;context&quot;: {}\n        }\n    else:\n        raw_message, attr = parse_maximo_error_base(body)\n        return {\n            &quot;reply&quot;: f&quot;⚠️ Failed to create user: {raw_message}&quot;,\n            &quot;context&quot;: {}\n        }\n\ndef get_user_member_uri(username, credentials=None):\n    # Query mxapiperuser to find the person&#x27;s rdf:about URI\n    query_url = f&quot;{config.get_maximo_base_url()}/oslc/os/mxapiperuser?oslc.where=personid=%22{username.upper()}%22&amp;oslc.properties=*&quot;\n    status_code, headers, body = make_maximo_request(query_url, &quot;GET&quot;, credentials=credentials)\n    \n    if status_code == 200:\n        res_data = json.loads(body)\n        members = res_data.get(&quot;rdfs:member&quot;, [])\n        if members:\n            person = members[0]\n            member_uri = person.get(&quot;rdf:about&quot;)\n            if member_uri:\n                return member_uri.replace(&quot;http://localhost/maximo&quot;, config.get_maximo_base_url()), None\n    return None, body\n\ndef add_security_group(username, groupname, credentials=None):\n    member_uri, error_body = get_user_member_uri(username, credentials=credentials)\n    if not member_uri:\n        return {&quot;reply&quot;: f&quot;❌ User &lt;strong&gt;{username.upper()}&lt;/strong&gt; was not found in Maximo.&quot;, &quot;context&quot;: {}}\n        \n    payload = {\n        &quot;user&quot;: {\n            &quot;groupuser&quot;: [\n                {\n                    &quot;groupname&quot;: groupname.upper(),\n                    &quot;_action&quot;: &quot;Add&quot;\n                }\n            ]\n        },\n        &quot;spi:user&quot;: {\n            &quot;spi:groupuser&quot;: [\n                {\n                    &quot;spi:groupname&quot;: groupname.upper(),\n                    &quot;_action&quot;: &quot;Add&quot;\n                }\n            ]\n        }\n    }\n    \n    update_headers = {\n        &quot;x-method-override&quot;: &quot;PATCH&quot;,\n        &quot;properties&quot;: &quot;*&quot;\n    }\n    \n    status_code, headers, body = make_maximo_request(member_uri, &quot;POST&quot;, payload, credentials=credentials, extra_headers=update_headers)\n    \n    if status_code in [401, 403]:\n        return {&quot;reply&quot;: &quot;❌ &lt;strong&gt;Authorization Error&lt;/strong&gt;: You do not have permission to modify security groups.&quot;, &quot;context&quot;: {}, &quot;status&quot;: status_code}\n        \n    if status_code in [200, 204]:\n        log_to_trace(&quot;add_secgroup&quot;, &quot;Added Security Group&quot;, f&quot;USERID: {username.upper()} | GROUP: {groupname.upper()}&quot;)\n        return {\n            &quot;reply&quot;: f&quot;✅ Security group &lt;strong&gt;{groupname.upper()}&lt;/strong&gt; has been added to user &lt;strong&gt;{username.upper()}&lt;/strong&gt; successfully.&quot;,\n            &quot;context&quot;: {}\n        }\n    else:\n        raw_message, attr = parse_maximo_error_base(body)\n        return {\n            &quot;reply&quot;: f&quot;⚠️ Failed to add security group: {raw_message}&quot;,\n            &quot;context&quot;: {}\n        }\n\ndef remove_security_group(username, groupname, credentials=None):\n    member_uri, error_body = get_user_member_uri(username, credentials=credentials)\n    if not member_uri:\n        return {&quot;reply&quot;: f&quot;❌ User &lt;strong&gt;{username.upper()}&lt;/strong&gt; was not found in Maximo.&quot;, &quot;context&quot;: {}}\n        \n    payload = {\n        &quot;user&quot;: {\n            &quot;groupuser&quot;: [\n                {\n                    &quot;groupname&quot;: groupname.upper(),\n                    &quot;_action&quot;: &quot;Delete&quot;\n                }\n            ]\n        },\n        &quot;spi:user&quot;: {\n            &quot;spi:groupuser&quot;: [\n                {\n                    &quot;spi:groupname&quot;: groupname.upper(),\n                    &quot;_action&quot;: &quot;Delete&quot;\n                }\n            ]\n        }\n    }\n    \n    update_headers = {\n        &quot;x-method-override&quot;: &quot;PATCH&quot;,\n        &quot;properties&quot;: &quot;*&quot;\n    }\n    \n    status_code, headers, body = make_maximo_request(member_uri, &quot;POST&quot;, payload, credentials=credentials, extra_headers=update_headers)\n    \n    if status_code in [401, 403]:\n        return {&quot;reply&quot;: &quot;❌ &lt;strong&gt;Authorization Error&lt;/strong&gt;: You do not have permission to modify security groups.&quot;, &quot;context&quot;: {}, &quot;status&quot;: status_code}\n        \n    if status_code in [200, 204]:\n        log_to_trace(&quot;remove_secgroup&quot;, &quot;Removed Security Group&quot;, f&quot;USERID: {username.upper()} | GROUP: {groupname.upper()}&quot;)\n        return {\n            &quot;reply&quot;: f&quot;✅ Security group &lt;strong&gt;{groupname.upper()}&lt;/strong&gt; has been removed from user &lt;strong&gt;{username.upper()}&lt;/strong&gt; successfully.&quot;,\n            &quot;context&quot;: {}\n        }\n    else:\n        raw_message, attr = parse_maximo_error_base(body)\n        return {\n            &quot;reply&quot;: f&quot;⚠️ Failed to remove security group: {raw_message}&quot;,\n            &quot;context&quot;: {}\n        }\n</pre>\n              </div>\n\n              <h2>Static Front-End Files (static/ directory)</h2>\n\n              <h3>11. UI HTML: static/index.html</h3>\n              <div class=\"ibm-code-block\" style=\"max-height: 300px; overflow-y: auto;\">\n                <div class=\"ibm-code-header\"><span>index.html</span></div>\n                <pre>&lt;!DOCTYPE html&gt;\n&lt;html lang=&quot;en&quot;&gt;\n&lt;head&gt;\n    &lt;meta charset=&quot;UTF-8&quot;&gt;\n    &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt;\n    &lt;title&gt;MaxAssist&lt;/title&gt;\n    &lt;!-- Google Fonts --&gt;\n    &lt;link rel=&quot;preconnect&quot; href=&quot;https://fonts.googleapis.com&quot;&gt;\n    &lt;link rel=&quot;preconnect&quot; href=&quot;https://fonts.gstatic.com&quot; crossorigin&gt;\n    &lt;link href=&quot;https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&amp;family=Outfit:wght@400;500;600;700;800&amp;display=swap&quot; rel=&quot;stylesheet&quot;&gt;\n    &lt;link rel=&quot;stylesheet&quot; href=&quot;style.css&quot;&gt;\n&lt;/head&gt;\n&lt;body&gt;\n    &lt;!-- Login Overlay Screen --&gt;\n    &lt;div id=&quot;login-overlay&quot; class=&quot;login-overlay&quot;&gt;\n        &lt;div class=&quot;login-box&quot; style=&quot;position: relative;&quot;&gt;\n            &lt;!-- Config Gear Icon --&gt;\n            &lt;button id=&quot;config-gear-btn&quot; class=&quot;config-gear-btn&quot; title=&quot;Configure Maximo Connection&quot;&gt;\n                &lt;svg viewBox=&quot;0 0 24 24&quot; width=&quot;18&quot; height=&quot;18&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2.2&quot; fill=&quot;none&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;\n                    &lt;circle cx=&quot;12&quot; cy=&quot;12&quot; r=&quot;3&quot;&gt;&lt;/circle&gt;\n                    &lt;path d=&quot;M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z&quot;&gt;&lt;/path&gt;\n                &lt;/svg&gt;\n            &lt;/button&gt;\n\n            &lt;div class=&quot;login-header&quot;&gt;\n                &lt;div class=&quot;logo-icon&quot;&gt;M&lt;/div&gt;\n                &lt;h2&gt;MaxAssist&lt;/h2&gt;\n                &lt;p&gt;Log in with your Maximo credentials to start&lt;/p&gt;\n            &lt;/div&gt;\n            \n            &lt;form id=&quot;login-form&quot;&gt;\n                &lt;div id=&quot;login-error&quot; class=&quot;login-error-alert hidden&quot;&gt;&lt;/div&gt;\n                \n                &lt;div class=&quot;login-group&quot;&gt;\n                    &lt;label for=&quot;username&quot;&gt;Username&lt;/label&gt;\n                    &lt;input type=&quot;text&quot; id=&quot;username&quot; placeholder=&quot;e.g. maxadmin&quot; required /&gt;\n                &lt;/div&gt;\n                \n                &lt;div class=&quot;login-group&quot;&gt;\n                    &lt;label for=&quot;password&quot;&gt;Password&lt;/label&gt;\n                    &lt;input type=&quot;password&quot; id=&quot;password&quot; placeholder=&quot;••••••••&quot; required /&gt;\n                &lt;/div&gt;\n                \n                &lt;button type=&quot;submit&quot; id=&quot;login-submit-btn&quot; class=&quot;login-btn&quot;&gt;\n                    &lt;span&gt;Log In&lt;/span&gt;\n                    &lt;div class=&quot;spinner hidden&quot;&gt;&lt;/div&gt;\n                &lt;/button&gt;\n            &lt;/form&gt;\n        &lt;/div&gt;\n    &lt;/div&gt;\n\n    &lt;!-- Config Overlay Modal --&gt;\n    &lt;div id=&quot;config-overlay&quot; class=&quot;login-overlay hidden&quot;&gt;\n        &lt;div class=&quot;login-box&quot;&gt;\n            &lt;div class=&quot;login-header&quot;&gt;\n                &lt;h2&gt;Configure Maximo URL&lt;/h2&gt;\n                &lt;p&gt;Update the base connection endpoint URL for the instance&lt;/p&gt;\n            &lt;/div&gt;\n            \n            &lt;form id=&quot;config-form&quot;&gt;\n                &lt;div id=&quot;config-error&quot; class=&quot;login-error-alert hidden&quot;&gt;&lt;/div&gt;\n                \n                &lt;div class=&quot;login-group&quot;&gt;\n                    &lt;label for=&quot;maximo-url&quot;&gt;Maximo Base URL&lt;/label&gt;\n                    &lt;input type=&quot;url&quot; id=&quot;maximo-url&quot; placeholder=&quot;http://localhost:9084/maximo&quot; required /&gt;\n                &lt;/div&gt;\n                \n                &lt;div style=&quot;display: flex; gap: 10px;&quot;&gt;\n                    &lt;button type=&quot;submit&quot; id=&quot;config-save-btn&quot; class=&quot;login-btn&quot;&gt;Save&lt;/button&gt;\n                    &lt;button type=&quot;button&quot; id=&quot;config-cancel-btn&quot; class=&quot;login-btn&quot; style=&quot;background: var(--bg-surface); color: var(--text-secondary); box-shadow: none;&quot;&gt;Cancel&lt;/button&gt;\n                &lt;/div&gt;\n            &lt;/form&gt;\n        &lt;/div&gt;\n    &lt;/div&gt;\n\n    &lt;!-- Main Chat Workspace --&gt;\n    &lt;div id=&quot;sidebar-overlay&quot; class=&quot;sidebar-overlay&quot;&gt;&lt;/div&gt;\n    &lt;div class=&quot;app-container hidden&quot; id=&quot;app-workspace&quot;&gt;\n        &lt;!-- Sidebar --&gt;\n        &lt;aside class=&quot;sidebar&quot; id=&quot;app-sidebar&quot;&gt;\n            &lt;div class=&quot;sidebar-header&quot;&gt;\n                &lt;div class=&quot;logo-container&quot;&gt;\n                    &lt;div class=&quot;logo-icon&quot;&gt;M&lt;/div&gt;\n                    &lt;div class=&quot;logo-text&quot;&gt;\n                        &lt;h2&gt;MaxAssist&lt;/h2&gt;\n                        &lt;span&gt;Smart Support Assistant&lt;/span&gt;\n                    &lt;/div&gt;\n                &lt;/div&gt;\n            &lt;/div&gt;\n            \n            &lt;div class=&quot;connection-status&quot;&gt;\n                &lt;div class=&quot;status-indicator active&quot;&gt;&lt;/div&gt;\n                &lt;div class=&quot;status-details&quot;&gt;\n                    &lt;p class=&quot;status-label&quot;&gt;Server Status&lt;/p&gt;\n                    &lt;p class=&quot;status-value&quot;&gt;Connected&lt;/p&gt;\n                &lt;/div&gt;\n            &lt;/div&gt;\n\n\n\n            &lt;div class=&quot;audit-section&quot;&gt;\n                &lt;div class=&quot;audit-header&quot;&gt;\n                    &lt;h3&gt;Activity Log&lt;/h3&gt;\n                    &lt;button id=&quot;clear-logs-btn&quot; title=&quot;Clear Trace Logs&quot;&gt;Clear&lt;/button&gt;\n                &lt;/div&gt;\n                &lt;div class=&quot;audit-list&quot; id=&quot;audit-list&quot;&gt;\n                    &lt;!-- Dynamic audit logs will appear here --&gt;\n                    &lt;div class=&quot;audit-empty&quot;&gt;No activity logged yet.&lt;/div&gt;\n                &lt;/div&gt;\n            &lt;/div&gt;\n        &lt;/aside&gt;\n\n        &lt;!-- Main Chat Area --&gt;\n        &lt;main class=&quot;chat-area&quot;&gt;\n            &lt;header class=&quot;chat-header&quot;&gt;\n                &lt;button id=&quot;sidebar-toggle-btn&quot; class=&quot;sidebar-toggle-btn&quot; title=&quot;Toggle Menu&quot;&gt;\n                    &lt;svg viewBox=&quot;0 0 24 24&quot; width=&quot;22&quot; height=&quot;22&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2.5&quot; fill=&quot;none&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;\n                        &lt;line x1=&quot;3&quot; y1=&quot;12&quot; x2=&quot;21&quot; y2=&quot;12&quot;&gt;&lt;/line&gt;\n                        &lt;line x1=&quot;3&quot; y1=&quot;6&quot; x2=&quot;21&quot; y2=&quot;6&quot;&gt;&lt;/line&gt;\n                        &lt;line x1=&quot;3&quot; y1=&quot;18&quot; x2=&quot;21&quot; y2=&quot;18&quot;&gt;&lt;/line&gt;\n                    &lt;/svg&gt;\n                &lt;/button&gt;\n                &lt;div class=&quot;header-info&quot;&gt;\n                    &lt;h1&gt;MaxAssist&lt;/h1&gt;\n                &lt;/div&gt;\n                &lt;div class=&quot;user-profile&quot;&gt;\n                    &lt;span class=&quot;user-badge&quot; id=&quot;user-badge-name&quot;&gt;MAXADMIN&lt;/span&gt;\n                    &lt;button id=&quot;logout-btn&quot; class=&quot;logout-btn-header&quot;&gt;Logout&lt;/button&gt;\n                &lt;/div&gt;\n            &lt;/header&gt;\n\n            &lt;!-- Message History --&gt;\n            &lt;section class=&quot;messages-container&quot; id=&quot;messages-container&quot;&gt;\n                &lt;div class=&quot;message bot-message&quot;&gt;\n                    &lt;div class=&quot;message-avatar&quot;&gt;AI&lt;/div&gt;\n                    &lt;div class=&quot;message-bubble&quot;&gt;\n                        &lt;p&gt;Hello! I am your &lt;strong&gt;Maximo Assistant&lt;/strong&gt;. I can help you find Work Orders, check Service Requests, and create new tickets.&lt;/p&gt;\n                        &lt;p&gt;After finding a Work Order or Service Request, you can ask follow-up questions about specific fields (e.g. &lt;em&gt;&quot;what is the location?&quot;&lt;/em&gt; or &lt;em&gt;&quot;who reported it?&quot;&lt;/em&gt;).&lt;/p&gt;\n                        &lt;p&gt;Choose a quick action below or type your query to get started.&lt;/p&gt;\n                    &lt;/div&gt;\n                &lt;/div&gt;\n            &lt;/section&gt;\n\n            &lt;!-- Quick Suggestions --&gt;\n            &lt;div class=&quot;quick-suggestions&quot;&gt;\n                &lt;button class=&quot;suggest-btn&quot; data-input=&quot;Find WO 1000&quot;&gt;🔍 Find Work Order 1000&lt;/button&gt;\n                &lt;button class=&quot;suggest-btn&quot; data-input=&quot;Status of SR 1177&quot;&gt;🎫 Check SR 1177&lt;/button&gt;\n                &lt;button class=&quot;suggest-btn&quot; data-input=&quot;Create SR&quot;&gt;📝 New Service Request&lt;/button&gt;\n                &lt;button class=&quot;suggest-btn&quot; data-input=&quot;Create WO&quot;&gt;🔧 New Work Order&lt;/button&gt;\n                &lt;button class=&quot;suggest-btn&quot; data-input=&quot;help&quot;&gt;❓ Help&lt;/button&gt;\n            &lt;/div&gt;\n\n            &lt;!-- Chat Input Area --&gt;\n            &lt;footer class=&quot;chat-input-area&quot;&gt;\n                &lt;form id=&quot;chat-form&quot; class=&quot;chat-form&quot;&gt;\n                    &lt;input type=&quot;text&quot; id=&quot;message-input&quot; autocomplete=&quot;off&quot; placeholder=&quot;Ask me anything about Work Orders or Service Requests...&quot; required&gt;\n                    &lt;button type=&quot;submit&quot; class=&quot;send-btn&quot;&gt;\n                        &lt;svg viewBox=&quot;0 0 24 24&quot; width=&quot;20&quot; height=&quot;20&quot; stroke=&quot;currentColor&quot; stroke-width=&quot;2&quot; fill=&quot;none&quot; stroke-linecap=&quot;round&quot; stroke-linejoin=&quot;round&quot;&gt;\n                            &lt;line x1=&quot;22&quot; y1=&quot;2&quot; x2=&quot;11&quot; y2=&quot;13&quot;&gt;&lt;/line&gt;\n                            &lt;polygon points=&quot;22 2 15 22 11 13 2 9 22 2&quot;&gt;&lt;/polygon&gt;\n                        &lt;/svg&gt;\n                    &lt;/button&gt;\n                &lt;/form&gt;\n            &lt;/footer&gt;\n        &lt;/main&gt;\n    &lt;/div&gt;\n    &lt;script src=&quot;app.js&quot;&gt;&lt;/script&gt;\n&lt;/body&gt;\n&lt;/html&gt;\n</pre>\n              </div>\n\n              <h3>12. UI CSS Styles: static/style.css</h3>\n              <div class=\"ibm-code-block\" style=\"max-height: 300px; overflow-y: auto;\">\n                <div class=\"ibm-code-header\"><span>style.css</span></div>\n                <pre>/* ============================================\n   Maximo Chatbot v4 — Clean &amp; Comfortable Theme\n   ============================================ */\n\n/* Reset and Base Styles */\n* {\n    margin: 0;\n    padding: 0;\n    box-sizing: border-box;\n    font-family: &#x27;Inter&#x27;, sans-serif;\n}\n\n:root {\n    /* Clean Light Palette — warm &amp; eye-comfortable */\n    --bg-main: #F7F8FA;\n    --bg-panel: #FFFFFF;\n    --bg-surface: #F0F2F5;\n    --border-color: #E2E5EA;\n    --border-subtle: #ECEEF2;\n\n    --text-primary: #1A1D24;\n    --text-secondary: #5F6B7A;\n    --text-muted: #8994A3;\n\n    --primary-color: #4F6EF7;\n    --primary-soft: #EEF1FE;\n    --primary-hover: #3B5BDB;\n    --primary-glow: rgba(79, 110, 247, 0.12);\n\n    --accent-color: #12B886;\n    --accent-soft: #E6FCF5;\n\n    --error-color: #FA5252;\n    --warning-soft: #FFF9DB;\n\n    --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.04);\n    --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.06);\n    --shadow-lg: 0 8px 24px rgba(0, 0, 0, 0.08);\n\n    --radius-sm: 8px;\n    --radius-md: 12px;\n    --radius-lg: 20px;\n\n    --sidebar-width: 300px;\n    --header-height: 64px;\n    --input-area-height: 76px;\n}\n\nbody {\n    background-color: var(--bg-main);\n    color: var(--text-primary);\n    overflow: hidden;\n    height: 100vh;\n    height: 100dvh;\n    width: 100vw;\n    -webkit-font-smoothing: antialiased;\n    -moz-osx-font-smoothing: grayscale;\n}\n\n/* App Container */\n.app-container {\n    display: flex;\n    height: 100vh;\n    height: 100dvh;\n    width: 100vw;\n}\n\n/* ============================\n   SIDEBAR\n   ============================ */\n.sidebar {\n    width: var(--sidebar-width);\n    background-color: var(--bg-panel);\n    border-right: 1px solid var(--border-color);\n    display: flex;\n    flex-direction: column;\n    height: 100%;\n    box-shadow: var(--shadow-sm);\n}\n\n.sidebar-header {\n    padding: 20px 22px;\n    border-bottom: 1px solid var(--border-subtle);\n}\n\n.logo-container {\n    display: flex;\n    align-items: center;\n    gap: 12px;\n}\n\n.logo-icon {\n    width: 38px;\n    height: 38px;\n    background: linear-gradient(135deg, var(--primary-color), #7C8CF8);\n    border-radius: var(--radius-sm);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-family: &#x27;Outfit&#x27;, sans-serif;\n    font-weight: 800;\n    font-size: 18px;\n    color: white;\n    box-shadow: 0 3px 10px var(--primary-glow);\n}\n\n.logo-text h2 {\n    font-family: &#x27;Outfit&#x27;, sans-serif;\n    font-size: 15px;\n    font-weight: 700;\n    color: var(--text-primary);\n}\n\n.logo-text span {\n    font-size: 11px;\n    color: var(--text-muted);\n    letter-spacing: 0.4px;\n}\n\n/* Connection Status */\n.connection-status {\n    margin: 14px 18px;\n    padding: 10px 14px;\n    background-color: var(--accent-soft);\n    border-radius: var(--radius-sm);\n    border: 1px solid #C3FAE8;\n    display: flex;\n    align-items: center;\n    gap: 10px;\n}\n\n.status-indicator {\n    width: 8px;\n    height: 8px;\n    border-radius: 50%;\n}\n\n.status-indicator.active {\n    background-color: var(--accent-color);\n    box-shadow: 0 0 6px rgba(18, 184, 134, 0.5);\n    animation: pulse-dot 2s ease-in-out infinite;\n}\n\n@keyframes pulse-dot {\n    0%, 100% { opacity: 1; }\n    50% { opacity: 0.5; }\n}\n\n.status-label {\n    font-size: 10px;\n    color: var(--text-muted);\n    text-transform: uppercase;\n    letter-spacing: 0.5px;\n    font-weight: 500;\n}\n\n.status-value {\n    font-size: 12px;\n    font-weight: 600;\n    color: #0CA678;\n}\n\n/* Sidebar Menu / Commands */\n.sidebar-menu {\n    padding: 16px 22px;\n}\n\n.sidebar-menu h3 {\n    font-size: 10px;\n    font-weight: 700;\n    color: var(--text-muted);\n    text-transform: uppercase;\n    letter-spacing: 1.2px;\n    margin-bottom: 10px;\n}\n\n.sidebar-menu ul {\n    list-style: none;\n}\n\n.sidebar-menu li {\n    display: flex;\n    flex-direction: column;\n    gap: 3px;\n    padding: 9px 12px;\n    background: var(--bg-surface);\n    border-radius: var(--radius-sm);\n    margin-bottom: 6px;\n    border: 1px solid transparent;\n    transition: all 0.2s ease;\n    cursor: default;\n}\n\n.sidebar-menu li:hover {\n    background: var(--primary-soft);\n    border-color: rgba(79, 110, 247, 0.15);\n}\n\n.command-tag {\n    font-family: &#x27;Inter&#x27;, monospace;\n    font-size: 12px;\n    font-weight: 700;\n    color: var(--primary-color);\n}\n\n.command-desc {\n    font-size: 11px;\n    color: var(--text-secondary);\n}\n\n/* Audit Section */\n.audit-section {\n    flex-grow: 1;\n    display: flex;\n    flex-direction: column;\n    border-top: 1px solid var(--border-subtle);\n    padding: 14px 18px;\n    overflow: hidden;\n}\n\n.audit-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    margin-bottom: 10px;\n}\n\n.audit-header h3 {\n    font-size: 10px;\n    font-weight: 700;\n    color: var(--text-muted);\n    text-transform: uppercase;\n    letter-spacing: 1.2px;\n}\n\n#clear-logs-btn {\n    background: var(--bg-surface);\n    border: 1px solid var(--border-color);\n    color: var(--text-secondary);\n    font-size: 10px;\n    font-weight: 500;\n    cursor: pointer;\n    padding: 3px 10px;\n    border-radius: 4px;\n    transition: all 0.2s;\n}\n\n#clear-logs-btn:hover {\n    background: var(--primary-soft);\n    color: var(--primary-color);\n    border-color: rgba(79, 110, 247, 0.2);\n}\n\n.audit-list {\n    flex-grow: 1;\n    overflow-y: auto;\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n    padding-right: 4px;\n}\n\n.audit-list::-webkit-scrollbar {\n    width: 4px;\n}\n\n.audit-list::-webkit-scrollbar-track {\n    background: transparent;\n}\n\n.audit-list::-webkit-scrollbar-thumb {\n    background: var(--border-color);\n    border-radius: 2px;\n}\n\n.audit-empty {\n    color: var(--text-muted);\n    font-size: 12px;\n    font-style: italic;\n    text-align: center;\n    padding: 24px 0;\n}\n\n.audit-item {\n    font-size: 11px;\n    padding: 9px 10px;\n    background: var(--bg-surface);\n    border-radius: 6px;\n    border-left: 3px solid var(--primary-color);\n}\n\n.audit-item.update {\n    border-left-color: var(--accent-color);\n}\n\n.audit-time {\n    color: var(--text-muted);\n    font-size: 9px;\n    margin-bottom: 3px;\n    display: block;\n}\n\n.audit-action {\n    font-weight: 600;\n    color: var(--text-primary);\n    margin-bottom: 2px;\n}\n\n.audit-details {\n    color: var(--text-secondary);\n    word-break: break-all;\n}\n\n/* ============================\n   MAIN CHAT AREA\n   ============================ */\n.chat-area {\n    flex-grow: 1;\n    display: flex;\n    flex-direction: column;\n    background-color: var(--bg-main);\n    height: 100%;\n    position: relative;\n    overflow: hidden;\n}\n\n/* Gemini-style animated gradient background */\n.chat-area::before,\n.chat-area::after {\n    content: &#x27;&#x27;;\n    position: absolute;\n    border-radius: 50%;\n    filter: blur(80px);\n    opacity: 0.35;\n    z-index: 0;\n    pointer-events: none;\n}\n\n.chat-area::before {\n    width: 500px;\n    height: 500px;\n    background: radial-gradient(circle, #C5D5FF 0%, #DBEAFE 40%, transparent 70%);\n    bottom: -120px;\n    left: -60px;\n    animation: aurora-drift-1 12s ease-in-out infinite alternate;\n}\n\n.chat-area::after {\n    width: 450px;\n    height: 450px;\n    background: radial-gradient(circle, #BAE6FD 0%, #E0F2FE 40%, transparent 70%);\n    bottom: -80px;\n    right: -40px;\n    animation: aurora-drift-2 14s ease-in-out infinite alternate;\n}\n\n@keyframes aurora-drift-1 {\n    0% {\n        transform: translate(0, 0) scale(1);\n        opacity: 0.3;\n    }\n    50% {\n        transform: translate(60px, -40px) scale(1.15);\n        opacity: 0.45;\n    }\n    100% {\n        transform: translate(120px, -20px) scale(1.05);\n        opacity: 0.3;\n    }\n}\n\n@keyframes aurora-drift-2 {\n    0% {\n        transform: translate(0, 0) scale(1);\n        opacity: 0.25;\n    }\n    50% {\n        transform: translate(-50px, -50px) scale(1.2);\n        opacity: 0.4;\n    }\n    100% {\n        transform: translate(-100px, -30px) scale(1);\n        opacity: 0.25;\n    }\n}\n\n/* Ensure all chat-area children sit above the gradient blobs */\n.chat-area &gt; * {\n    position: relative;\n    z-index: 1;\n}\n\n.chat-header {\n    height: var(--header-height);\n    border-bottom: 1px solid var(--border-color);\n    padding: 0 28px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    background-color: var(--bg-panel);\n    box-shadow: var(--shadow-sm);\n}\n\n.header-info h1 {\n    font-family: &#x27;Outfit&#x27;, sans-serif;\n    font-size: 17px;\n    font-weight: 600;\n    color: var(--text-primary);\n}\n\n.header-info p {\n    font-size: 12px;\n    color: var(--text-muted);\n}\n\n.user-badge {\n    padding: 5px 14px;\n    background: var(--primary-soft);\n    border: 1px solid rgba(79, 110, 247, 0.15);\n    border-radius: var(--radius-lg);\n    color: var(--primary-color);\n    font-size: 11px;\n    font-weight: 600;\n    letter-spacing: 0.5px;\n}\n\n/* Message History Container */\n.messages-container {\n    flex-grow: 1;\n    overflow-y: auto;\n    padding: 28px 32px;\n    display: flex;\n    flex-direction: column;\n    gap: 20px;\n}\n\n.messages-container::-webkit-scrollbar {\n    width: 5px;\n}\n\n.messages-container::-webkit-scrollbar-track {\n    background: transparent;\n}\n\n.messages-container::-webkit-scrollbar-thumb {\n    background: var(--border-color);\n    border-radius: 3px;\n}\n\n/* Message Bubbles */\n.message {\n    display: flex;\n    gap: 14px;\n    max-width: 78%;\n    animation: fadeIn 0.3s ease forwards;\n}\n\n.bot-message {\n    align-self: flex-start;\n}\n\n.user-message {\n    align-self: flex-end;\n    flex-direction: row-reverse;\n}\n\n.message-avatar {\n    width: 34px;\n    height: 34px;\n    border-radius: 50%;\n    background: linear-gradient(135deg, var(--primary-color), #7C8CF8);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-weight: 700;\n    font-size: 12px;\n    color: white;\n    flex-shrink: 0;\n    box-shadow: 0 2px 8px var(--primary-glow);\n}\n\n.user-message .message-avatar {\n    background: linear-gradient(135deg, #845EF7, #B197FC);\n    box-shadow: 0 2px 8px rgba(132, 94, 247, 0.2);\n}\n\n.message-bubble {\n    padding: 14px 18px;\n    border-radius: var(--radius-lg);\n    font-size: 13.5px;\n    line-height: 1.6;\n}\n\n.bot-message .message-bubble {\n    background-color: var(--bg-panel);\n    border: 1px solid var(--border-color);\n    border-top-left-radius: 4px;\n    color: var(--text-primary);\n    box-shadow: var(--shadow-sm);\n}\n\n.user-message .message-bubble {\n    background: linear-gradient(135deg, var(--primary-color), var(--primary-hover));\n    color: white;\n    border-top-right-radius: 4px;\n    box-shadow: 0 3px 10px var(--primary-glow);\n}\n\n.message-bubble p {\n    margin-bottom: 8px;\n}\n\n.message-bubble p:last-child {\n    margin-bottom: 0;\n}\n\n/* Data Display Cards */\n.data-card {\n    background: var(--bg-surface);\n    border: 1px solid var(--border-color);\n    border-radius: var(--radius-md);\n    padding: 14px;\n    margin-top: 10px;\n    display: grid;\n    grid-template-columns: auto 1fr;\n    gap: 6px 14px;\n    font-size: 12.5px;\n}\n\n.card-title {\n    grid-column: 1 / -1;\n    font-weight: 700;\n    color: var(--primary-color);\n    border-bottom: 1px solid var(--border-color);\n    padding-bottom: 8px;\n    margin-bottom: 4px;\n    font-size: 13px;\n}\n\n.card-label {\n    color: var(--text-muted);\n    font-weight: 500;\n}\n\n.card-value {\n    color: var(--text-primary);\n    font-weight: 600;\n}\n\n/* Quick Suggestion Buttons */\n.quick-suggestions {\n    padding: 0 28px 14px 28px;\n    display: flex;\n    flex-wrap: wrap;\n    gap: 8px;\n}\n\n.suggest-btn {\n    background: var(--bg-panel);\n    border: 1px solid var(--border-color);\n    border-radius: 24px;\n    padding: 7px 16px;\n    font-size: 12px;\n    color: var(--text-secondary);\n    cursor: pointer;\n    transition: all 0.2s ease;\n    font-weight: 500;\n    box-shadow: var(--shadow-sm);\n}\n\n.suggest-btn:hover {\n    background: var(--primary-soft);\n    border-color: rgba(79, 110, 247, 0.25);\n    color: var(--primary-color);\n    transform: translateY(-1px);\n    box-shadow: var(--shadow-md);\n}\n\n/* Chat Input Area */\n.chat-input-area {\n    height: var(--input-area-height);\n    border-top: 1px solid var(--border-color);\n    padding: 12px 28px;\n    background-color: var(--bg-panel);\n}\n\n.chat-form {\n    display: flex;\n    gap: 12px;\n    width: 100%;\n    height: 100%;\n}\n\n#message-input {\n    flex-grow: 1;\n    background-color: #FFFFFF;\n    border: 1.5px solid var(--border-color);\n    border-radius: 28px;\n    padding: 0 24px;\n    color: var(--text-primary);\n    font-size: 14.5px;\n    outline: none;\n    transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);\n    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.02);\n}\n\n#message-input::placeholder {\n    color: var(--text-muted);\n}\n\n#message-input:hover {\n    border-color: #B0B5C0;\n    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);\n}\n\n#message-input:focus {\n    border-color: var(--primary-color);\n    box-shadow: 0 0 0 4px rgba(79, 110, 247, 0.15), 0 3px 12px rgba(79, 110, 247, 0.05);\n    background-color: #FFFFFF;\n}\n\n.send-btn {\n    width: 50px;\n    height: 50px;\n    background: linear-gradient(135deg, var(--primary-color), var(--primary-hover));\n    border: none;\n    border-radius: 50%;\n    color: white;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    transition: transform 0.15s, box-shadow 0.15s, background-color 0.15s;\n    box-shadow: 0 3px 10px var(--primary-glow);\n}\n\n\n.send-btn:hover {\n    transform: scale(1.04);\n    box-shadow: 0 4px 14px rgba(79, 110, 247, 0.3);\n}\n\n.send-btn:active {\n    transform: scale(0.97);\n}\n\n/* ============================\n   INLINE SR/WO CREATION FORM\n   ============================ */\n.sr-form {\n    margin-top: 14px;\n    padding: 16px;\n    background: var(--bg-main);\n    border: 1px solid var(--border-color);\n    border-radius: var(--radius-md);\n}\n\n.sr-form-group {\n    margin-bottom: 12px;\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n    flex: 1;\n    position: relative;\n}\n\n.sr-form-group label {\n    font-size: 11px;\n    font-weight: 600;\n    color: var(--text-secondary);\n    text-transform: uppercase;\n    letter-spacing: 0.5px;\n}\n\n.sr-required {\n    color: #FA5252;\n}\n\n.sr-form-row {\n    display: flex;\n    gap: 10px;\n}\n\n.sr-input {\n    padding: 9px 12px;\n    border: 1.5px solid var(--border-color);\n    border-radius: var(--radius-sm);\n    background: var(--bg-panel);\n    color: var(--text-primary);\n    font-size: 13px;\n    font-family: &#x27;Inter&#x27;, sans-serif;\n    outline: none;\n    transition: border-color 0.2s, box-shadow 0.2s;\n    width: 100%;\n    resize: none;\n}\n\n.sr-input::placeholder {\n    color: var(--text-muted);\n}\n\n.sr-input:focus {\n    border-color: var(--primary-color);\n    box-shadow: 0 0 0 3px var(--primary-glow);\n}\n\n.sr-submit-btn {\n    margin-top: 6px;\n    width: 100%;\n    padding: 10px;\n    background: linear-gradient(135deg, var(--primary-color), var(--primary-hover));\n    color: white;\n    border: none;\n    border-radius: var(--radius-sm);\n    font-size: 13px;\n    font-weight: 600;\n    font-family: &#x27;Inter&#x27;, sans-serif;\n    cursor: pointer;\n    transition: transform 0.15s, opacity 0.15s, box-shadow 0.15s;\n    box-shadow: 0 3px 10px var(--primary-glow);\n}\n\n.sr-submit-btn:hover {\n    transform: translateY(-1px);\n    box-shadow: 0 4px 14px rgba(79, 110, 247, 0.3);\n}\n\n.sr-submit-btn:active {\n    transform: scale(0.98);\n}\n\n.sr-submit-btn:disabled {\n    opacity: 0.6;\n    cursor: not-allowed;\n    transform: none;\n}\n\n/* Animations */\n@keyframes fadeIn {\n    from {\n        opacity: 0;\n        transform: translateY(6px);\n    }\n    to {\n        opacity: 1;\n        transform: translateY(0);\n    }\n}\n\n/* Sidebar Toggle Button (Hidden on Desktop) */\n.sidebar-toggle-btn {\n    display: none;\n    background: transparent;\n    border: none;\n    color: var(--text-primary);\n    cursor: pointer;\n    padding: 6px;\n    border-radius: var(--radius-sm);\n    align-items: center;\n    justify-content: center;\n    transition: background 0.2s;\n    margin-right: 8px;\n}\n\n.sidebar-toggle-btn:hover {\n    background: var(--bg-surface);\n}\n\n/* Sidebar Overlay Backdrop */\n.sidebar-overlay {\n    position: fixed;\n    top: 0;\n    left: 0;\n    width: 100vw;\n    height: 100vh;\n    background: rgba(26, 29, 36, 0.4);\n    backdrop-filter: blur(3px);\n    z-index: 998;\n    opacity: 0;\n    visibility: hidden;\n    transition: opacity 0.25s ease, visibility 0.25s ease;\n}\n\n.sidebar-overlay.open {\n    opacity: 1;\n    visibility: visible;\n}\n\n/* Responsive Styles */\n@media (max-width: 768px) {\n    .sidebar-toggle-btn {\n        display: flex;\n    }\n    .sidebar {\n        position: fixed;\n        left: -320px;\n        top: 0;\n        bottom: 0;\n        width: 300px;\n        z-index: 999;\n        transition: left 0.3s cubic-bezier(0.16, 1, 0.3, 1);\n        box-shadow: var(--shadow-lg);\n    }\n    .sidebar.open {\n        left: 0;\n    }\n    .messages-container {\n        padding: 20px 16px;\n    }\n    .quick-suggestions {\n        padding: 0 16px 12px 16px;\n    }\n    .chat-input-area {\n        padding: 12px 16px;\n    }\n    .chat-header {\n        padding: 0 16px;\n    }\n}\n\n/* ============================================\n   AUTHENTICATION &amp; LOGIN OVERLAY STYLES\n   ============================================ */\n.hidden {\n    display: none !important;\n}\n\n.login-overlay {\n    position: fixed;\n    top: 0;\n    left: 0;\n    width: 100vw;\n    height: 100vh;\n    background: radial-gradient(circle at 30% 30%, #E0E7FF 0%, #F1F5F9 50%, #E2E8F0 100%);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    z-index: 9999;\n}\n\n.login-box {\n    background: rgba(255, 255, 255, 0.85);\n    backdrop-filter: blur(16px);\n    border: 1px solid rgba(255, 255, 255, 0.6);\n    border-radius: var(--radius-lg);\n    width: 420px;\n    padding: 40px;\n    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.08);\n    display: flex;\n    flex-direction: column;\n    gap: 24px;\n    animation: fadeIn 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards;\n}\n\n.login-header {\n    text-align: center;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 12px;\n}\n\n.login-header .logo-icon {\n    width: 50px;\n    height: 50px;\n    font-size: 24px;\n    margin-bottom: 8px;\n}\n\n.login-header h2 {\n    font-family: &#x27;Outfit&#x27;, sans-serif;\n    font-size: 22px;\n    font-weight: 800;\n    color: var(--text-primary);\n}\n\n.login-header p {\n    font-size: 13px;\n    color: var(--text-secondary);\n}\n\n.login-group {\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n    margin-bottom: 16px;\n}\n\n.login-group label {\n    font-size: 11px;\n    font-weight: 700;\n    color: var(--text-secondary);\n    text-transform: uppercase;\n    letter-spacing: 0.8px;\n}\n\n.login-group input {\n    padding: 12px 16px;\n    border: 1.5px solid var(--border-color);\n    border-radius: var(--radius-md);\n    background: #FFFFFF;\n    color: var(--text-primary);\n    font-size: 14px;\n    outline: none;\n    transition: all 0.2s;\n}\n\n.login-group input:focus {\n    border-color: var(--primary-color);\n    box-shadow: 0 0 0 4px var(--primary-glow);\n}\n\n.login-btn {\n    width: 100%;\n    padding: 14px;\n    background: linear-gradient(135deg, var(--primary-color), var(--primary-hover));\n    color: white;\n    border: none;\n    border-radius: var(--radius-md);\n    font-size: 14px;\n    font-weight: 700;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    gap: 10px;\n    box-shadow: 0 4px 14px var(--primary-glow);\n    transition: all 0.2s;\n}\n\n.login-btn:hover {\n    transform: translateY(-1px);\n    box-shadow: 0 6px 20px rgba(79, 110, 247, 0.3);\n}\n\n.login-btn:active {\n    transform: scale(0.98);\n}\n\n.login-error-alert {\n    background-color: #FFF5F5;\n    border: 1px solid #FFE3E3;\n    color: var(--error-color);\n    padding: 10px 14px;\n    border-radius: var(--radius-sm);\n    font-size: 12.5px;\n    font-weight: 500;\n    line-height: 1.5;\n}\n\n.logout-btn-header {\n    background: transparent;\n    border: 1px solid var(--border-color);\n    padding: 5px 12px;\n    border-radius: var(--radius-lg);\n    font-size: 11px;\n    font-weight: 600;\n    color: var(--text-secondary);\n    cursor: pointer;\n    margin-left: 8px;\n    transition: all 0.2s;\n}\n\n.logout-btn-header:hover {\n    background: #FFF5F5;\n    color: var(--error-color);\n    border-color: #FFE3E3;\n}\n\n/* Spinner */\n.spinner {\n    width: 16px;\n    height: 16px;\n    border: 2px solid rgba(255, 255, 255, 0.3);\n    border-top-color: white;\n    border-radius: 50%;\n    animation: spin 0.8s linear infinite;\n}\n\n@keyframes spin {\n    to { transform: rotate(360deg); }\n}\n\n/* Gear Button Placement */\n.config-gear-btn {\n    position: absolute;\n    top: 18px;\n    right: 18px;\n    background: transparent;\n    border: none;\n    color: var(--text-secondary);\n    cursor: pointer;\n    padding: 6px;\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    transition: all 0.25s ease;\n    z-index: 10;\n}\n\n.config-gear-btn:hover {\n    background: var(--bg-surface);\n    color: var(--primary-color);\n    transform: rotate(45deg);\n}\n\n</pre>\n              </div>\n\n              <h3>13. UI Javascript logic: static/app.js</h3>\n              <div class=\"ibm-code-block\" style=\"max-height: 300px; overflow-y: auto;\">\n                <div class=\"ibm-code-header\"><span>app.js</span></div>\n                <pre>// Chatbot UI Controller\ndocument.addEventListener(&quot;DOMContentLoaded&quot;, () =&gt; {\n    // Auth DOM Elements\n    const loginOverlay = document.getElementById(&quot;login-overlay&quot;);\n    const loginForm = document.getElementById(&quot;login-form&quot;);\n    const usernameInput = document.getElementById(&quot;username&quot;);\n    const passwordInput = document.getElementById(&quot;password&quot;);\n    const loginError = document.getElementById(&quot;login-error&quot;);\n    const loginSubmitBtn = document.getElementById(&quot;login-submit-btn&quot;);\n    const appWorkspace = document.getElementById(&quot;app-workspace&quot;);\n    const logoutBtn = document.getElementById(&quot;logout-btn&quot;);\n    const userBadgeName = document.getElementById(&quot;user-badge-name&quot;);\n\n    // Config DOM Elements\n    const configGearBtn = document.getElementById(&quot;config-gear-btn&quot;);\n    const configOverlay = document.getElementById(&quot;config-overlay&quot;);\n    const configForm = document.getElementById(&quot;config-form&quot;);\n    const maximoUrlInput = document.getElementById(&quot;maximo-url&quot;);\n    const configCancelBtn = document.getElementById(&quot;config-cancel-btn&quot;);\n    const configError = document.getElementById(&quot;config-error&quot;);\n\n    // Chatbot DOM Elements\n    const chatForm = document.getElementById(&quot;chat-form&quot;);\n    const messageInput = document.getElementById(&quot;message-input&quot;);\n    const messagesContainer = document.getElementById(&quot;messages-container&quot;);\n    const auditList = document.getElementById(&quot;audit-list&quot;);\n    const clearLogsBtn = document.getElementById(&quot;clear-logs-btn&quot;);\n    const suggestButtons = document.querySelectorAll(&quot;.suggest-btn&quot;);\n\n    // Chatbot state context\n    let chatContext = {",
    "title_hi": "4.10: Chatbot v10 Source Code Aur Environment Setup",
    "subtitle_hi": "Enterprise production environment ke liye copyable complete source code.",
    "html_hi": "<h1>4.10: Chatbot v10 Source Code Aur Environment Setup</h1>\n<p class=\"page-subtitle\">Enterprise production environment ke liye copyable complete source code.</p>\n<section>\n  <h2>Environment Config File</h2>\n  <p><code>connection_config/maximo.json</code> me base URL configure karein:</p>\n  <div class=\"ibm-code-block\">\n    <pre>{\n  \"MAXIMO_BASE_URL\": \"http://localhost:9084/maximo\"\n}</pre>\n  </div>\n  <p>English tab me app.py, nlp_engine.py aur chat_engine.py ka full verified enterprise code copy karne ke liye available hai.</p>\n</section>"
  },
  "chatbot-nlu-development": {
    "id": "chatbot-nlu-development",
    "title": "4.7: NLU Model Development &amp; Intent Identification",
    "subtitle": "Designing and training a decoupled scikit-learn intent classifier pipeline.",
    "html": "<h1>4.7: NLU Model Development &amp; Intent Identification</h1>\n            <p class=\"page-subtitle\">Designing and training a decoupled scikit-learn intent classifier pipeline.</p>\n            \n            <section>\n              <h2>Overview</h2>\n              <p>To enable natural conversational queries instead of strict regular expression (regex) matches, the chatbot uses a decoupled Natural Language Understanding (NLU) model. The classifier pipeline is built using python's <strong>scikit-learn</strong> library. It converts incoming user utterances into token matrices, extracts features, and runs a classification model to output the most probable intent label.</p>\n              \n              <h3>Key Features</h3>\n              <ul>\n                <li><strong>Feature Extraction:</strong> Uses <code>TfidfVectorizer(ngram_range=(1, 2))</code> to extract unigrams and bigrams, capturing both single keywords (e.g. <em>\"status\"</em>) and keyword sequences (e.g. <em>\"work order\"</em>).</li>\n                <li><strong>Classification Engine:</strong> Utilizes <code>LogisticRegression(C=1000.0)</code> with low regularization penalty to optimize predictions on small training datasets.</li>\n                <li><strong>Auto-retraining:</strong> Monitors file system modifications. If <code>intent_config.json</code> is updated, the server automatically triggers the training script to regenerate the serialized model.</li>\n              </ul>\n            </section>\n\n            <section>\n              <h2>Directory Structure</h2>\n              <p>The intent model is designed inside the <code>enterprise_nlp</code> package with the following directory layout:</p>\n              <div class=\"ibm-code-block\">\n                <pre>enterprise_nlp/\n├── config/\n│   ├── intents.yaml           # YAML-based intent template examples\n│   ├── dictionary.yaml        # Synonyms and spelling corrections mapping\n│   └── pipeline_config.yaml   # Target save path configurations for pkl model\n├── src/\n│   ├── core/\n│   │   └── interfaces.py      # Abstract interface definitions\n│   ├── intent/\n│   │   └── sklearn_classifier.py  # Scikit-learn Pipeline definitions\n│   └── training/\n│       └── train.py           # Classifier training manager loop\n└── models/\n    └── intent_classifier.pkl  # Serialized trained model ready for deployment</pre>\n              </div>\n            </section>\n\n            <section>\n              <h2>NLU Classifier Logic</h2>\n              <p>The preprocessing pipeline cleans user queries by stripping punctuation, checking character distances for spelling correction, expanding synonyms, and stemming. The preprocessed string is fed into the vectorizer which calculates Term Frequency-Inverse Document Frequency weightings. The classifier evaluates the multi-class probabilities, applies an out-of-vocabulary penalty ratio, and yields the final predicted intent (e.g. <code>SEARCH_WORK_ORDER</code>) if the confidence value surpasses the threshold.</p>\n            </section>\n\n            <section>\n              <h2>NLU Development Source Code</h2>\n\n              <h3>1. Intent Classifier Pipeline: sklearn_classifier.py</h3>\n              <div class=\"ibm-code-block\" style=\"max-height: 400px; overflow-y: auto;\">\n                <div class=\"ibm-code-header\">\n                  <span>sklearn_classifier.py</span>\n                </div>\n                <pre>import pickle\nfrom typing import Dict, List\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.pipeline import Pipeline\nfrom src.core.interfaces import BaseIntentClassifier\n\nclass SklearnIntentClassifier(BaseIntentClassifier):\n    def __init__(self):\n        # Build the scikit-learn pipeline.\n        # We use a ngram_range of (1, 2) to capture both individual words and word pairs (e.g. &quot;work order&quot;).\n        self.model = Pipeline([\n            (&#x27;vectorizer&#x27;, TfidfVectorizer(ngram_range=(1, 2), lowercase=True)),\n            (&#x27;classifier&#x27;, LogisticRegression(C=1000.0, max_iter=1000))\n        ])\n        self.is_trained = False\n\n    def train(self, data: Dict[str, List[str]]) -&gt; None:\n        X = []\n        y = []\n        for intent, sentences in data.items():\n            for sentence in sentences:\n                X.append(sentence)\n                y.append(intent)\n        \n        if not X:\n            raise ValueError(&quot;Training data is empty.&quot;)\n            \n        self.model.fit(X, y)\n        self.is_trained = True\n\n    def predict(self, text: str) -&gt; str:\n        if not self.is_trained:\n            raise ValueError(&quot;Classifier is not trained yet. Call train() or load() first.&quot;)\n        return str(self.model.predict([text])[0])\n\n    def predict_proba(self, text: str) -&gt; float:\n        if not self.is_trained:\n            raise ValueError(&quot;Classifier is not trained yet. Call train() or load() first.&quot;)\n        # Find the index of the predicted class to get its corresponding probability\n        probs = self.model.predict_proba([text])[0]\n        classes = self.model.classes_\n        predicted_class = self.predict(text)\n        class_idx = list(classes).index(predicted_class)\n        return float(probs[class_idx])\n\n    def save(self, filepath: str) -&gt; None:\n        if not self.is_trained:\n            raise ValueError(&quot;Cannot save an untrained model.&quot;)\n        with open(filepath, &#x27;wb&#x27;) as f:\n            pickle.dump({\n                &#x27;model&#x27;: self.model,\n                &#x27;is_trained&#x27;: self.is_trained\n            }, f)\n\n    def load(self, filepath: str) -&gt; None:\n        with open(filepath, &#x27;rb&#x27;) as f:\n            data = pickle.load(f)\n            self.model = data[&#x27;model&#x27;]\n            self.is_trained = data[&#x27;is_trained&#x27;]\n            \n    @property\n    def classes(self) -&gt; List[str]:\n        if not self.is_trained:\n            return []\n        return list(self.model.named_steps[&#x27;classifier&#x27;].classes_)\n</pre>\n              </div>\n\n              <h3>2. Model Training Routine: train.py</h3>\n              <div class=\"ibm-code-block\" style=\"max-height: 400px; overflow-y: auto;\">\n                <div class=\"ibm-code-header\">\n                  <span>train.py</span>\n                </div>\n                <pre>import os\nimport yaml\nfrom typing import Dict, List\nfrom src.preprocessing.preprocessor import TextPreprocessor\nfrom src.normalization.dictionary_resolver import DictionaryResolver\nfrom src.intent.sklearn_classifier import SklearnIntentClassifier\n\nimport csv\n\ndef load_yaml(filepath: str) -&gt; dict:\n    with open(filepath, &#x27;r&#x27;) as f:\n        return yaml.safe_load(f)\n\ndef train_model():\n    # Define config paths\n    base_dir = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n    intents_yaml_path = os.path.join(base_dir, &quot;config&quot;, &quot;intents.yaml&quot;)\n    intents_xlsx_path = os.path.join(base_dir, &quot;config&quot;, &quot;maximo_nlp_training_dataset_v3.xlsx&quot;)\n    intents_csv_path = os.path.join(base_dir, &quot;config&quot;, &quot;intents.csv&quot;)\n    dict_path = os.path.join(base_dir, &quot;config&quot;, &quot;dictionary.yaml&quot;)\n    pipeline_config_path = os.path.join(base_dir, &quot;config&quot;, &quot;pipeline_config.yaml&quot;)\n\n    # Load dictionaries and configurations\n    dict_data = load_yaml(dict_path)\n    pipeline_config = load_yaml(pipeline_config_path)\n\n    # Instantiate preprocessor and normalizer\n    preprocessor = TextPreprocessor()\n    normalizer = DictionaryResolver(dict_data.get(&quot;synonyms&quot;, {}))\n\n    cleaned_training_data: Dict[str, List[str]] = {}\n\n    # Check if Excel exists and is populated\n    if os.path.exists(intents_xlsx_path):\n        print(f&quot;Loading training data from Excel: {intents_xlsx_path}&quot;)\n        import pandas as pd\n        df = pd.read_excel(intents_xlsx_path)\n        # Fallback to standard column names if custom ones are not found\n        text_col = &quot;sentence&quot; if &quot;sentence&quot; in df.columns else (&quot;text&quot; if &quot;text&quot; in df.columns else None)\n        intent_col = &quot;intent&quot; if &quot;intent&quot; in df.columns else None\n\n        if text_col and intent_col:\n            for _, row in df.iterrows():\n                text = str(row[text_col])\n                intent = str(row[intent_col])\n                if text and intent and text != &quot;nan&quot; and intent != &quot;nan&quot;:\n                    prep_text = preprocessor.preprocess(text)\n                    norm_text = normalizer.normalize(prep_text)\n                    if intent not in cleaned_training_data:\n                        cleaned_training_data[intent] = []\n                    cleaned_training_data[intent].append(norm_text)\n        else:\n            raise ValueError(f&quot;Excel file must contain both text/sentence and intent columns. Found: {df.columns.tolist()}&quot;)\n\n    # Check if CSV exists and is populated\n    elif os.path.exists(intents_csv_path):\n        print(f&quot;Loading training data from CSV: {intents_csv_path}&quot;)\n        with open(intents_csv_path, &#x27;r&#x27;, encoding=&#x27;utf-8&#x27;) as f:\n            reader = csv.DictReader(f)\n            for row in reader:\n                text = row.get(&quot;text&quot;, &quot;&quot;)\n                intent = row.get(&quot;intent&quot;, &quot;&quot;)\n                if text and intent:\n                    prep_text = preprocessor.preprocess(text)\n                    norm_text = normalizer.normalize(prep_text)\n                    if intent not in cleaned_training_data:\n                        cleaned_training_data[intent] = []\n                    cleaned_training_data[intent].append(norm_text)\n    else:\n        print(f&quot;Loading training data from YAML: {intents_yaml_path}&quot;)\n        intents_data = load_yaml(intents_yaml_path)\n        for intent, examples in intents_data.get(&quot;intents&quot;, {}).items():\n            cleaned_examples = []\n            for example in examples:\n                prep_text = preprocessor.preprocess(example)\n                norm_text = normalizer.normalize(prep_text)\n                cleaned_examples.append(norm_text)\n            cleaned_training_data[intent] = cleaned_examples\n\n    # Train classifier\n    print(&quot;Training SklearnIntentClassifier...&quot;)\n    classifier = SklearnIntentClassifier()\n    classifier.train(cleaned_training_data)\n    print(&quot;Training completed successfully.&quot;)\n\n    # Save model\n    model_path_rel = pipeline_config.get(&quot;pipeline&quot;, {}).get(&quot;model_path&quot;, &quot;models/intent_classifier.pkl&quot;)\n    model_path = os.path.join(base_dir, model_path_rel)\n    os.makedirs(os.path.dirname(model_path), exist_ok=True)\n    \n    classifier.save(model_path)\n    print(f&quot;Model saved to {model_path}&quot;)\n\nif __name__ == &quot;__main__&quot;:\n    train_model()\n</pre>\n              </div>\n            </section>",
    "title_hi": "4.11: Machine Learning NLU Intent Model Development",
    "subtitle_hi": "Scikit-learn Logistic Regression pipeline aur intent training architecture.",
    "html_hi": "<h1>4.11: Machine Learning NLU Intent Model Development</h1>\n<p class=\"page-subtitle\">Scikit-learn Logistic Regression pipeline aur intent training architecture.</p>\n<section>\n  <h2>Scikit-Learn ML Intent Classifier</h2>\n  <p>Chatbot user ke message ko classify karne ke liye <code>TfidfVectorizer</code> aur <code>LogisticRegression</code> classification model use karta hai jo fast aur highly accurate intent identification provide karta hai.</p>\n</section>"
  },
  "chatbot-oslc-troubleshoot": {
    "id": "chatbot-oslc-troubleshoot",
    "title": "4.8: OSLC Security &amp; Troubleshooting",
    "subtitle": "Diagnosing and resolving BMXAA0024E signature option errors, Object Structure authorization, and session credential issues in Maximo OSLC REST integrations.",
    "html": "<h1>4.8: OSLC Security &amp; Troubleshooting</h1>\n            <p class=\"page-subtitle\">Diagnosing and resolving <code>BMXAA0024E</code> signature option errors, Object Structure authorization, and session credential issues in Maximo OSLC REST integrations.</p>\n            \n            <section>\n              <h2>Overview</h2>\n              <p>When integrating with Maximo's OSLC REST APIs, the most common class of errors during record <strong>creation</strong> (POST) is the signature option authorization failure. This guide documents the root cause analysis, the internal Maximo Java security framework flow, and the exact resolution steps derived from live debugging of the Chatbot v11 Labor creation feature.</p>\n              \n              <div class=\"ibm-callout ibm-callout-warning\">\n                <p><strong>Key Takeaway:</strong> Maximo's OSLC POST internally invokes <code>checkMethodAccess(\"add\")</code>, which then checks for the <code>\"INSERT\"</code> signature option on the application context. If the Object Structure's <code>authapp</code> points to an application where the user's security group doesn't have INSERT granted, the operation fails with <code>BMXAA0024E</code>.</p>\n              </div>\n            </section>\n\n            <section>\n              <h2>Error: BMXAA0024E - The action ADD is not allowed</h2>\n              <p>When sending a POST request to create a Labor record via <code>/oslc/os/mxapilabor</code>, Maximo returns:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>Error Response</span></div>\n<pre>{\n  \"oslc:Error\": {\n    \"oslc:statusCode\": \"400\",\n    \"spi:reasonCode\": \"BMXAA0024E\",\n    \"oslc:message\": \"BMXAA0024E - The action ADD is not allowed\n                     on object LABOR.\"\n  }\n}</pre>\n              </div>\n              \n              <h3>Root Cause</h3>\n              <p>This error occurs because of the internal security flow inside Maximo's <strong>MboSet.java</strong> framework. When an OSLC POST request arrives:</p>\n              <ol>\n                <li>The OSLC engine calls <code>mboSet.add()</code> to create a new MBO record.</li>\n                <li>The <code>add()</code> method internally calls <code>checkMethodAccess(\"add\")</code>.</li>\n                <li><code>checkMethodAccess</code> in <code>MboSet.java</code> detects the method name is <code>\"add\"</code>, and then checks if the current user's profile has the <strong><code>\"INSERT\"</code></strong> signature option granted for the application context (<code>getApp()</code>).</li>\n                <li>If <code>getApp()</code> returns the Object Structure's <code>authapp</code> value (e.g. <code>MXAPILABOR</code>), and the user's security group does NOT have INSERT granted for that specific application, the error is thrown.</li>\n              </ol>\n\n              <h3>Java Source: MboSet.checkMethodAccess</h3>\n              <p>The following is the decompiled excerpt from <code>psdi.mbo.MboSet.java</code> showing how the <code>\"add\"</code> method triggers the <code>\"INSERT\"</code> signature option check:</p>\n              <div class=\"ibm-code-block\">\n                <div class=\"ibm-code-header\"><span>MboSet.java - checkMethodAccess (decompiled)</span></div>\n<pre>public void checkMethodAccess(String methodName, long accessModifier)\n        throws MXException, RemoteException {\n\n    // ...user status checks...\n\n    if (methodName.equalsIgnoreCase(\"add\")) {\n        ProfileRemote profile = getProfile();\n        String testApp = getApp();  // Gets authapp from Object Structure\n        String siteorg = null;\n\n        // Resolve site/org based on app level\n        if (profile.orgLevelApp(testApp)) {\n            siteorg = getInsertOrg();\n        } else if (profile.siteLevelApp(testApp)) {\n            siteorg = getInsertSite();\n        }\n\n        // THE CRITICAL CHECK: looks for \"INSERT\" option, NOT \"ADD\"\n        if (testApp != null &amp;&amp; testApp.length() &gt; 0\n            &amp;&amp; !profile.getAppOptionAuth(testApp, \"INSERT\", siteorg)) {\n            Object[] args = { methodName.toUpperCase(), getName()",
    "title_hi": "4.12: OSLC Security Aur Troubleshooting Guide",
    "subtitle_hi": "BMXAA0024E authorization error solve karna aur OSLC security signature options setup.",
    "html_hi": "<h1>4.12: OSLC Security Aur Troubleshooting Guide</h1>\n<p class=\"page-subtitle\">BMXAA0024E authorization error solve karna aur OSLC security signature options setup.</p>\n<section>\n  <h2>BMXAA0024E Security Authorization Error</h2>\n  <div class=\"ibm-callout ibm-danger\">\n    <div class=\"ibm-callout-title\"><i class=\"fa-solid fa-circle-xmark\"></i> Authorization Error</div>\n    <div class=\"ibm-callout-content\">\n      <p><code>BMXAA0024E: You are not authorized for the requested option for the MXAPILABOR application.</code></p>\n    </div>\n  </div>\n  <p>Security Groups application me user ke group ko <code>MXAPILABOR</code>, <code>MXAPIWO</code>, aur <code>MXAPISR</code> par <strong>INSERT</strong>, <strong>SAVE</strong> aur <strong>READ</strong> permission grant karein.</p>\n</section>"
  }
};
